/* VIA·L — библиотека статей. СОБРАНО tools/build-articles.py из docs/articles/<язык>/*.md — руками не править.
   Данные: ART[язык][ключ] = {t: заголовок, min: время чтения, h: HTML тела, codes: темы базы для «На чём основано»}. */
window.VIAL_ART = {"sections":[["start",["start-peri","start-meno","start-tests"]],["cmp",["hf","sleep","energy","mood","fog","weight","pain","muscle","libido_f","cycle"]],["step",["evening","wake","strength","protein","cool","walk","breath","bed","order"]]],"langs":{"en":{"start-peri":{"t":"What perimenopause is and how to recognise it","min":"4 min read","h":"<p class=\"art-p\">Your sleep has got worse, your periods are less predictable, your mood swings, and yet your tests come back \"normal\". Sound familiar? Very often the reason is perimenopause — the transition years before your last period. It is not an illness but a stage every woman goes through. Yet it is rarely talked about, so many women spend years not understanding what is happening to them.</p><h3 class=\"art-h\">What is happening in the body</h3><p class=\"art-p\">During the transition, hormones do not change smoothly or all at once.</p><p class=\"art-p\"><b>Progesterone falls first, and steadily.</b> After 40, more and more cycles happen without ovulation — and this is a normal part of the transition. Progesterone feeds the brain's natural \"calming system\", so its decline is most often felt as trouble falling asleep.</p><p class=\"art-p\"><b>Oestrogen, meanwhile, does not fall — it swings.</b> It drops, then spikes higher than usual, and only later goes down for good. What unsettles how you feel in these years is mainly the size of these swings, not the level itself. That is why it can feel like \"nothing makes sense\": one week is good, the next is hard.</p><h3 class=\"art-h\">How to recognise it</h3><p class=\"art-p\">Perimenopause is recognised by a picture that builds up over time, not by a single test. Typical signs:</p><ul class=\"art-ul\"><li><b>Your cycle changes.</b> Between 35 and 50, periods often become heavier, longer or more irregular.</li><li><b>Sleep.</b> It is harder to fall asleep, you wake more at night, your mind \"won't switch off\".</li><li><b>Mood.</b> Ups and downs, irritability, the days before your period feel stronger than they used to.</li><li><b>Breasts and fluid.</b> Fullness and tenderness in the breasts, bloating.</li><li><b>Head.</b> Migraines, \"brain fog\", poorer concentration.</li><li><b>Hot flashes and night sweats.</b> These can already start in these years.</li></ul><p class=\"art-p\">You do not need to have all of them at once. The pattern matters more: what repeats and how it relates to your cycle.</p><h3 class=\"art-h\">What to do first</h3><p class=\"art-p\"><b>Start keeping track.</b> The first day of your period, sleep, hot flashes, mood — every day, briefly. After a few weeks you will see connections that memory cannot hold. This is the best \"test\" of the transition.</p><p class=\"art-p\"><b>Set a sleep anchor.</b> Get up at the same time all seven days of the week, weekends included, and get 10–15 minutes of daylight in the first hour after waking. This is the strongest behavioural lever for sleep — stronger than any supplement.</p><p class=\"art-p\"><b>Remove what unsettles the night.</b> Coffee and strong tea before 2 pm, and no alcohol in the evening: it makes you drowsy but breaks up the second half of the night.</p><p class=\"art-p\"><b>Check your iron if your periods are heavy.</b> Heavy periods are the most common cause of iron deficiency in women, and iron stores fall before routine blood tests change. Tiredness, breathlessness on the stairs, hair loss — a reason to ask your doctor for a ferritin test. Iron should be taken based on a test, not blindly.</p><h3 class=\"art-h\">When to see a doctor without delay</h3><ul class=\"art-ul\"><li>You need to change a pad or tampon every hour for several hours in a row.</li><li>Your period lasts longer than 8 days.</li><li>Bleeding between periods.</li><li>Bleeding together with severe tiredness or feeling faint.</li></ul><p class=\"art-p\">This is not \"just the transition\" — these signs need to be seen by a gynaecologist.</p><h3 class=\"art-h\">What to try this week</h3><ul class=\"art-ul\"><li>Log the first day of your period and your sleep in VIA-L.</li><li>Get up at the same time all seven days.</li><li>Coffee before 2 pm, an evening without alcohol.</li></ul><!--EV--><p class=\"art-p art-note\"><i>This is general information, not a prescription. Tests and treatment are chosen by a doctor.</i></p>","codes":["P-F1","P-F3","P-F17","P-F22"]},"start-meno":{"t":"Menopause: what changes after your last period","min":"5 min read","h":"<p class=\"art-p\">Menopause is the point when you have had no periods for twelve months in a row. Everything after that is postmenopause. Oestrogen is now steadily low, and the body adjusts to this new reality. Some changes are felt straight away; others are \"silent\" and only show up years later. It is worth knowing about the second kind in advance: the first years after menopause are exactly when you can do the most for the decades ahead.</p><h3 class=\"art-h\">What you feel</h3><p class=\"art-p\">When oestrogen is low, a recognisable picture forms: hot flashes, night sweats, broken sleep, dryness and discomfort during intimacy, aching joints and muscles, \"brain fog\". This is one story, not a set of separate problems, and it is best tackled as a whole.</p><p class=\"art-p\">A separate word about dryness and discomfort during intimacy. It is a very common change — in half of women or more — yet it is rarely talked about. Unlike hot flashes, it does not go away on its own and tends to get worse over time. The good news is that it responds well to help: a regular moisturiser, a lubricant for intimacy, pelvic floor exercises — and a conversation with your doctor. There is no need to put up with it.</p><h3 class=\"art-h\">What you don't feel, but matters</h3><p class=\"art-p\"><b>Heart and blood vessels.</b> Before menopause, women's risk of heart disease is roughly half that of men; as oestrogen falls, the gap closes quickly. The sharpest acceleration happens in the year or two around the last period: \"bad\" cholesterol rises, and blood vessels become stiffer. This is not a verdict but a window for prevention.</p><p class=\"art-p\"><b>Bones.</b> Bone is lost fastest from about a year before the last period to two years after — up to 2% a year in the spine. There are no symptoms until a fracture. If you had early menopause before 45, a fracture from a minor injury, long-term steroid use, or a parent with a hip fracture — it is worth discussing a bone density scan with your doctor now, without waiting until 65.</p><p class=\"art-p\"><b>Muscles and metabolism.</b> Fat shifts towards the belly, the body handles sugar less well, and muscle responds less to protein and exercise. Sugar cravings, \"fog\" and a changing figure are one chain.</p><h3 class=\"art-h\">What to do</h3><p class=\"art-p\"><b>Strength training twice a week.</b> This is a lever for everything at once: hot flashes, mood, bones, muscles and metabolism. The basics are squats, pulls and presses, without pain.</p><p class=\"art-p\"><b>Protein at every meal, starting with breakfast.</b> After 40, muscle needs more protein than before, and breakfast is usually where there is least.</p><p class=\"art-p\"><b>A walk after meals.</b> 10–15 minutes after eating helps the body cope with sugar.</p><p class=\"art-p\"><b>A Mediterranean way of eating.</b> Olive oil, fish, nuts, vegetables and fibre — the best-studied way to support the heart and blood vessels.</p><p class=\"art-p\"><b>Know your numbers.</b> Blood pressure, sugar, cholesterol — and, if possible, ask your doctor for ApoB and Lp(a): they show the risk to blood vessels more precisely, and Lp(a) only needs to be tested once in a lifetime.</p><h3 class=\"art-h\">When to see a doctor without delay</h3><p class=\"art-p\">Any bleeding after twelve months without periods is always a reason to see a gynaecologist promptly.</p><h3 class=\"art-h\">What to try this week</h3><ul class=\"art-ul\"><li>Two strength sessions of 30–40 minutes on different days.</li><li>A source of protein at every meal; start with breakfast.</li><li>10–15 minutes of walking after your main meal.</li></ul><!--EV--><p class=\"art-p art-note\"><i>This is general information, not a prescription. Tests and treatment are chosen by a doctor.</i></p>","codes":["P-F1","P-F12","P-F13","P-F15"]},"start-tests":{"t":"Why hormone tests after 40 tell you so little","min":"4 min read","h":"<p class=\"art-p\">When you start to feel different, the first instinct is to \"get your hormones checked\" and see the answer in numbers. But in the transition years, these are exactly the tests that let you down most often. Let's look at why — and which tests are really worth doing.</p><h3 class=\"art-h\">Why hormones are hard to catch with a test</h3><p class=\"art-p\"><b>They jump around.</b> In perimenopause, oestrogen swings up and down, and FSH, oestradiol and progesterone change so much after 40 that one test is a snapshot of one random day. Tomorrow the numbers will be different.</p><p class=\"art-p\"><b>Progesterone pulses.</b> Its blood level can change several-fold within minutes. Even a blood test shows just a moment, and home tests do not measure it at all.</p><p class=\"art-p\"><b>Your gadget does not measure hormones.</b> A ring or watch sees the rise in temperature after ovulation — but only after the fact and only as a marker. If there was no rise, that does not mean \"low progesterone\": after 40 some cycles happen without ovulation, and sensor noise, a hot flash or a cold can also get in the way.</p><p class=\"art-p\">That is why perimenopause is recognised not by a test but by the picture over time: how your cycle, sleep, mood and hot flashes change. A diary kept for a few weeks says more than one lab report.</p><h3 class=\"art-h\">What is important to rule out</h3><p class=\"art-p\">Some transition symptoms resemble other conditions that are easy to check and can be dealt with. These are worth ruling out first:</p><ul class=\"art-ul\"><li><b>Thyroid</b> — if you have become sensitive to cold, constipated, or have a slow pulse: a TSH test.</li><li><b>Iron stores</b> — if your periods are heavy, you feel tired, get breathless on the stairs, crave chewing ice, or your legs are restless in the evening: a ferritin test. Iron falls before a routine blood test changes.</li><li><b>Mood</b> — if low mood or anxiety lasts the whole month, not just before your period, that is a reason to talk to your doctor separately.</li><li><b>Breathing during sleep</b> — snoring with pauses, unrefreshing sleep, daytime sleepiness: after menopause this is a common and often missed cause of tiredness.</li></ul><h3 class=\"art-h\">Which tests really help after 40</h3><ul class=\"art-ul\"><li><b>Blood pressure and sugar</b> — regularly.</li><li><b>ApoB</b> — shows the particles that are dangerous for blood vessels more precisely than ordinary \"bad cholesterol\".</li><li><b>Lp(a)</b> — one test in a lifetime is enough: it is inherited and rises after menopause.</li><li><b>hs-CRP</b> — a marker of background inflammation; in women it predicts heart risk well.</li><li><b>Ferritin and TSH</b> — if the signs above apply.</li><li><b>Bone density scan</b> — already at menopause if you have risk factors: menopause before 45, a fracture from a minor injury, long-term steroid use, a parent with a hip fracture.</li></ul><p class=\"art-p\">Ask your doctor for more than just \"cholesterol\" — if possible, ApoB and Lp(a).</p><h3 class=\"art-h\">What to try this week</h3><ul class=\"art-ul\"><li>Start a diary in VIA-L: the first day of your period, sleep, hot flashes, mood.</li><li>Note which items from the \"important to rule out\" list apply to you.</li><li>Make a list for your doctor of the tests you want to discuss.</li></ul><!--EV--><p class=\"art-p art-note\"><i>This is general information, not a prescription. Which tests to take is decided by a doctor.</i></p>","codes":["P-F3","P-F6","P-F13","P-F22"]},"hf":{"t":"Hot flashes: why they happen and what really helps","min":"4 min read","h":"<p class=\"art-p\">Heat rises to your face and neck, you break into a sweat, then you may feel chilly. At night the same thing wakes you, and in the morning it feels as if you have not slept at all. Hot flashes are one of the most common signs of perimenopause and menopause. The good news: a lot is known about them, and some familiar advice works while some does not. Let's sort out which is which.</p><h3 class=\"art-h\">Why the body suddenly overheats</h3><p class=\"art-p\">Each of us has a \"thermal comfort zone\" — a range in which the body does not try either to cool down or to warm up. When oestrogen falls during the transition, this zone narrows. Now even a very small rise in temperature is enough for the body to decide it must cool down urgently: blood vessels widen, the skin flushes, sweat appears.</p><p class=\"art-p\">Hot flashes usually come together with night sweats, broken sleep, dryness, aching joints and \"brain fog\". This is one picture, not a set of separate problems. If you wear a ring or watch, you can often see sharp jumps in skin temperature at night together with awakenings.</p><h3 class=\"art-h\">Why nights are the worst</h3><p class=\"art-p\">Most night-time hot flashes coincide with waking up. The night breaks into pieces, and in the morning you have no energy, your mood is worse and sugar cravings are stronger. So anything that reduces night-time awakenings helps not only with hot flashes but with the whole day.</p><h3 class=\"art-h\">What helps — ranked by strength of evidence</h3><p class=\"art-p\"><b>Strength training twice a week.</b> This is the strongest lever without medication. In the best study, hot flashes roughly halved, and mood improved even before strength and weight had changed. This is where to start, not something to leave \"for later\".</p><p class=\"art-p\"><b>Cognitive behavioural therapy and clinical hypnosis.</b> These are the only non-drug methods with strong support specifically for hot flashes. After CBT, hot flashes are less bothersome and interfere less with life; hypnosis also reduces how often they happen. There are group, online and self-help book formats; they are led by a psychologist or psychotherapist with this experience.</p><p class=\"art-p\"><b>A cool, dark bedroom.</b> Around 16–19 °C, breathable fabrics, clothing and bedding in layers so you can easily take something off at night. To be honest: cooling does not restore the \"comfort zone\", but it noticeably reduces awakenings and discomfort.</p><p class=\"art-p\"><b>Less alcohol and caffeine.</b> Alcohol makes hot flashes worse even in small amounts and breaks up the second half of the night. Coffee and strong tea before 2 pm.</p><h3 class=\"art-h\">What doesn't help with hot flashes, though it is often recommended</h3><ul class=\"art-ul\"><li><b>Breathing practices, yoga, meditation</b> do not reduce hot flashes better than a placebo. But they help with calm and sleep — and that is a good reason to do them.</li><li><b>Soy, tofu and ground flaxseed</b> did not reduce hot flashes in studies. They are good as food — protein and fibre — but not as a \"hot flash remedy\".</li><li><b>Herbs</b> — black cohosh, red clover, dong quai, chasteberry — are no better than a placebo for hot flashes in good-quality studies, and they can interact with medication. If you want to try them, discuss it with a specialist first.</li><li><b>Omega-3</b> is good for the heart and blood vessels, but in studies it does not help with hot flashes.</li></ul><p class=\"art-p\">No over-the-counter supplement has convincing evidence for hot flashes.</p><h3 class=\"art-h\">When to see a doctor</h3><p class=\"art-p\">If hot flashes often wake you at night or get in the way of work and life, that is a reason to see a doctor, not to put up with it. The most effective options here are prescription ones: there are both hormonal and non-hormonal choices. This is a fully valid option, not a \"failure of the natural way\"; nutrition and habits remain a support, not a replacement.</p><p class=\"art-p\">And one more reason to tell your doctor about hot flashes: severe, long-lasting hot flashes and night sweats are not just discomfort. Doctors take them into account when assessing the heart and blood vessels — and after menopause this is especially important.</p><h3 class=\"art-h\">What to try this week</h3><ul class=\"art-ul\"><li>Keep the bedroom cool and dark; bedding and nightwear in breathable fabrics, in layers.</li><li>Two strength sessions of 30–40 minutes on different days; the basics are squats, pulls and presses, without pain.</li><li>Coffee and strong tea only before 2 pm, and no alcohol in the evening.</li></ul><p class=\"art-p\">Log your hot flashes every day in VIA-L: in two or three weeks you will see which of these works for you.</p><!--EV--><p class=\"art-p art-note\"><i>This is general information, not a prescription. The dose and treatment plan are chosen by a doctor.</i></p>","codes":["P-F1","P-F17","P-F13"]},"sleep":{"t":"Why sleep gets worse after 40 and what to do about it","min":"5 min read","h":"<p class=\"art-p\">You used to fall asleep in ten minutes; now you lie awake for an hour. Or you drift off easily, but at three in the morning your eyes are open and your thoughts won't let you sleep again. Sleep is one of the first things to change in the transition. And one of the most rewarding: here, habits work better than pills.</p><h3 class=\"art-h\">What really changes</h3><p class=\"art-p\">To be honest: part of the decline in sleep over the years is simply age. But the transition has its own signs.</p><p class=\"art-p\"><b>It is harder to fall asleep.</b> Progesterone feeds the brain's natural \"calming system\". When there is less of it, falling asleep becomes harder.</p><p class=\"art-p\"><b>Your mind won't switch off.</b> At night it is as if someone is holding a finger on the button — thoughts spin, the body is tired, but sleep does not come. This happens even without any hot flashes.</p><p class=\"art-p\"><b>Hot flashes break up the night.</b> Most night-time hot flashes coincide with waking up.</p><p class=\"art-p\"><b>The evening won't let go.</b> A disrupted daily stress rhythm keeps the body from \"winding down\" by night — hence waking at 3–4 am.</p><p class=\"art-p\">If you wear a ring or watch: they show total sleep, falling asleep and the number of awakenings reliably. \"Deep\" and \"REM\" sleep, however, are only approximate; treat them as a hint, not a fact.</p><h3 class=\"art-h\">What works best</h3><p class=\"art-p\"><b>A wake-up anchor.</b> Get up at the same time all seven days, weekends included, within half an hour. Regularity matters more than how long you sleep. And get 10–15 minutes of daylight in the first hour after waking — outdoors, even on a cloudy day.</p><p class=\"art-p\"><b>Bed is for sleep only.</b> Don't lie awake: if you can't sleep for more than 15–20 minutes, get up and come back when you feel sleepy. Don't work or scroll your phone in bed, and don't look at the clock at night.</p><p class=\"art-p\"><b>A cool, dark bedroom.</b> Around 16–19 °C, breathable fabrics, clothing in layers. This reduces awakenings from hot flashes.</p><p class=\"art-p\"><b>A warm, dim evening.</b> For 30–60 minutes before bed — soft warm light and no screens.</p><h3 class=\"art-h\">What to remove — this matters more than what to add</h3><ul class=\"art-ul\"><li><b>Alcohol in the evening.</b> It is a \"false friend\": it helps you fall asleep but breaks up the second half of the night and makes hot flashes worse — even in small amounts.</li><li><b>Late coffee.</b> Coffee and strong tea only before 2 pm.</li><li><b>A late dinner.</b> Your last heavy meal — three hours before bed.</li></ul><p class=\"art-p\">Daytime movement helps sleep — but evening alcohol cancels that benefit.</p><h3 class=\"art-h\">What about supplements?</h3><p class=\"art-p\">Their effect is modest. <b>Magnesium</b> in the evening has weak evidence; it makes sense if you get little from food (pumpkin seeds, leafy greens, pulses). <b>Melatonin</b> mainly helps those whose sleep is already disrupted and depends on when it is taken — discuss it with a specialist. Valerian is not supported by evidence, and we do not recommend adaptogens such as ashwagandha: there are risks for the liver and thyroid.</p><h3 class=\"art-h\">When to see a doctor</h3><ul class=\"art-ul\"><li>Snoring with pauses or a feeling of choking during sleep, unrefreshing sleep despite enough hours, falling asleep during the day — especially at the wheel. After menopause, breathing problems during sleep are common and often missed.</li><li>An irresistible urge to move your legs in the evening that eases with movement — it is worth checking your iron stores (ferritin).</li><li>Poor sleep for more than three months despite all of the above.</li><li>Severe hot flashes break up the night — treating them improves sleep too.</li></ul><h3 class=\"art-h\">What to try this week</h3><ul class=\"art-ul\"><li>Get up at the same time all seven days.</li><li>Don't lie awake: if you can't sleep, get up and come back when you feel sleepy.</li><li>Coffee before 2 pm, an evening without alcohol.</li></ul><!--EV--><p class=\"art-p art-note\"><i>This is general information, not a prescription. Tests and treatment are chosen by a doctor.</i></p>","codes":["P-F17","P-F3","P-F4"]},"energy":{"t":"Where tiredness after 40 comes from and how to get your energy back","min":"5 min read","h":"<p class=\"art-p\">You seem to be sleeping, you seem to be eating as usual, yet you have no energy from the moment you wake up. By lunchtime you want to lie down; by evening you don't want anything. The first thought is \"I'm low on vitamins\". But most often, vitamins are not the issue.</p><h3 class=\"art-h\">What most often lies behind tiredness</h3><p class=\"art-p\">Falling oestrogen really does affect stamina. But tiredness at this age far more often comes from something else — and almost all of it can be checked and put right:</p><ul class=\"art-ul\"><li><b>Sleep.</b> Broken nights add up, and no amount of coffee makes up for them.</li><li><b>Iron stores.</b> Heavy periods in the transition drain your reserves, and tiredness appears long before a routine blood test changes.</li><li><b>Thyroid.</b> What sets it apart is feeling cold — in menopause it is usually the opposite, you feel hot.</li><li><b>Mood.</b> When nothing has brought you joy for more than two weeks, it is not \"just tiredness\".</li></ul><p class=\"art-p\">So the place to start is not with \"energy\" supplements but with checking.</p><h3 class=\"art-h\">Signs that call for a test, not \"pushing through\"</h3><ul class=\"art-ul\"><li><b>Iron:</b> heavy periods, breathlessness or a racing heart on the stairs, hair loss, pallor, craving to chew ice, restless legs in the evening → ferritin and a blood count.</li><li><b>Thyroid:</b> feeling cold, constipation, a slow pulse, dry skin, puffy eyelids, a hoarse voice → TSH.</li><li><b>Vitamin B12:</b> numbness or tingling in the hands and feet, \"cotton-wool\" legs; the risk is higher with metformin, heartburn medication and a vegan diet → a B12 test.</li><li><b>Breathing during sleep:</b> sleep is unrefreshing despite enough hours, snoring with pauses → see a sleep specialist.</li></ul><p class=\"art-p\">⚠️ A special case: if, after exertion, you feel sharply worse the next day — for hours or a whole day — do not force yourself to do more. See a doctor about this.</p><h3 class=\"art-h\">What brings energy back</h3><p class=\"art-p\"><b>Movement.</b> The strongest energy lever we know of. A combination works best: strength training, short intense bursts with full rest between them, and light cardio. The worst is \"moderately hard all the time\". The good news: in the first years after menopause the body is especially responsive to training.</p><p class=\"art-p\"><b>Protein in the morning.</b> A protein breakfast within an hour or two of waking. A skipped breakfast and sugar spikes themselves drive up stress hormones — and a slump follows during the day.</p><p class=\"art-p\"><b>A walk after meals.</b> 10–15 minutes after your main meals smooths out the \"sugar rollercoaster\" and the after-lunch drowsiness.</p><p class=\"art-p\"><b>A sleep anchor.</b> Get up at the same time all seven days and get daylight in the morning. Sometimes the simplest thing is to go to bed half an hour earlier.</p><h3 class=\"art-h\">What to remove</h3><p class=\"art-p\">Alcohol, refined sweets and ultra-processed food, chronic lack of sleep, intense training without recovery — removing these \"energy leaks\" matters more than adding something.</p><h3 class=\"art-h\">What about supplements?</h3><p class=\"art-p\">Food and movement are stronger than any of them. <b>Iron</b> — only based on a ferritin test, not blindly. <b>Vitamin D</b> is fine even without a test. Magnesium and B vitamins add energy only if you are short of them. Trendy \"youth boosters\" (NMN, NR and the like) did not improve energy in human studies — we do not recommend them.</p><h3 class=\"art-h\">When to see a doctor</h3><ul class=\"art-ul\"><li>Tiredness lasting more than four weeks despite sleep and movement.</li><li>Tiredness together with unexplained weight loss, drenching night sweats or swollen lymph nodes.</li><li>Breathlessness, chest pain or palpitations — urgently.</li></ul><h3 class=\"art-h\">What to try this week</h3><ul class=\"art-ul\"><li>A source of protein at every meal, starting with breakfast.</li><li>10–15 minutes of walking after your main meals.</li><li>Two strength sessions of 30–40 minutes on different days.</li></ul><!--EV--><p class=\"art-p art-note\"><i>This is general information, not a prescription. Tests and treatment are chosen by a doctor.</i></p>","codes":["P-F5","P-F22","P-F4","P-F17"]},"mood":{"t":"Mood swings, anxiety and irritability: what is happening","min":"5 min read","h":"<p class=\"art-p\">\"I don't recognise myself.\" You snap over little things, cry for no reason, anxiety hits out of nowhere, and things that used to bring you joy now leave you cold. Your character has not gone bad. In the transition, this happens to a great many women — and there is an explanation.</p><h3 class=\"art-h\">Why it swings</h3><p class=\"art-p\">Oestrogen supports the brain chemicals responsible for mood and pleasure. In perimenopause it does not simply fall — it swings, and it is the size of these swings that unsettles mood. On top of that, progesterone declines, and with it the brain's natural \"calming system\". Hence anxiety, irritability, bursts of anger, tears, and the feeling that it has become harder to cope with pressure.</p><p class=\"art-p\">Irritability and anger are often stronger than sadness. This is a hormonal picture, not a \"bad character\".</p><p class=\"art-p\">And something important, so you are not frightened: for most women this is a passing reaction. It usually peaks in perimenopause and then settles. Those who have had serious periods of low mood before should be more watchful.</p><h3 class=\"art-h\">How to tell what exactly is going on</h3><p class=\"art-p\">The key is <b>when</b> you feel bad:</p><ul class=\"art-ul\"><li><b>only in the last week before your period</b>, easing in the first days after it starts;</li><li><b>all month</b>, but worse before your period;</li><li><b>all month</b>, with no link to your cycle.</li></ul><p class=\"art-p\">What will help depends on this. And you can only tell the difference with a diary covering at least two cycles — in hindsight, memory blames everything on \"before my period\". Log your mood and the first day of your period in VIA-L — after a couple of months the pattern will be clear.</p><h3 class=\"art-h\">What helps</h3><p class=\"art-p\"><b>Sleep.</b> Broken sleep and built-up tiredness amplify the hormonal mood swings. If your sleep is broken, start there.</p><p class=\"art-p\"><b>Movement.</b> The best-proven lever, for many comparable in strength to medication. About 150 minutes a week: walking, strength training — and gentle practices such as yoga and tai chi ease anxiety the most. Strength training helps women especially.</p><p class=\"art-p\"><b>Morning light.</b> Bright daylight right after waking noticeably lifts mood in perimenopause. A walk in daylight is a simple daily step.</p><p class=\"art-p\"><b>Slow breathing.</b> 5–10 minutes a day with a longer out-breath — about six breaths a minute. It acts on anxiety directly, without \"willpower\".</p><p class=\"art-p\"><b>Food.</b> A Mediterranean style, fibre, fermented foods, a protein breakfast. Magnesium is best from food — dark leafy greens, pumpkin seeds, pulses; a supplement makes sense if there is little in your diet.</p><h3 class=\"art-h\">What to remove</h3><ul class=\"art-ul\"><li><b>Alcohol.</b> It calms you for an hour, and then anxiety comes back stronger — especially in perimenopause.</li><li><b>A lot of coffee.</b> Caffeine winds up anxiety and makes hot flashes worse — only before midday.</li><li><b>\"Stress formulas\" with vitamin B6</b> are not safe when taken long term.</li></ul><h3 class=\"art-h\">What a doctor can offer</h3><p class=\"art-p\">If low mood or anxiety gets in the way of life, the foundation of help is psychotherapy (including programmes designed specifically for menopause) and, if needed, medication. In perimenopause, especially together with hot flashes, hormone therapy can also help mood — this is for a doctor to decide.</p><h3 class=\"art-h\">When to seek help straight away</h3><ul class=\"art-ul\"><li>Any thoughts of harming yourself, or that it would be \"better not to live\" — contact a specialist or a crisis helpline immediately. This is not something to wait out.</li><li>Low mood or loss of interest almost every day for more than two weeks, or anxiety that gets in the way of life and work — see a doctor in the next few days.</li><li>You are sleeping much less yet have lots of energy, your speech has sped up, you feel drawn to impulsive spending and decisions — see a doctor.</li></ul><h3 class=\"art-h\">What to try this week</h3><ul class=\"art-ul\"><li>A walk in daylight in the first hour after waking.</li><li>Get up at the same time all seven days.</li><li>Log your mood and the first day of your period in VIA-L.</li></ul><!--EV--><p class=\"art-p art-note\"><i>This is general information, not a prescription. Tests and treatment are chosen by a doctor.</i></p>","codes":["P-F9","P-F4","P-F17"]},"fog":{"t":"\"Brain fog\": I forget words and lose my train of thought — what's wrong with me?","min":"4 min read","h":"<p class=\"art-p\">You walk into a room and can't remember why. A friend's name is \"on the tip of your tongue\". A thought slips away mid-sentence. Many women in the transition are frightened: \"Is my memory starting to fail?\" Let's look at this calmly.</p><h3 class=\"art-h\">It is real — and it passes</h3><p class=\"art-p\">Oestrogen nourishes the brain: the areas responsible for memory and speech, and the way the brain gets its energy. So \"fog\" in the transition is not imaginary. Most often it affects finding words, speed, and remembering what you hear.</p><p class=\"art-p\">But here is what is important to know:</p><ul class=\"art-ul\"><li>according to large studies, this fog is <b>mild</b> and usually <b>passes</b> after menopause;</li><li>it is <b>not the start of a memory disease</b> — such diseases are very rare at this age;</li><li>the feeling of fog is usually <b>stronger</b> than what tests show.</li></ul><h3 class=\"art-h\">What makes the fog worse</h3><p class=\"art-p\"><b>Anxiety and mood.</b> The very thought \"Am I losing my mind?\" worsens concentration — and the circle closes. Fog often comes from anxiety rather than from a \"weak memory\".</p><p class=\"art-p\"><b>Lack of sleep.</b> Broken nights hit attention harder than it seems.</p><p class=\"art-p\"><b>Overload.</b> Ten things at once — and the brain loses the thread. One task at a time is a simple technique that works.</p><h3 class=\"art-h\">What is worth checking</h3><p class=\"art-p\">Not everything should be put down to menopause. With these signs — see a doctor to get checked:</p><ul class=\"art-ul\"><li><b>Thyroid</b> — feeling cold, constipation, a slow pulse → TSH.</li><li><b>Vitamin B12</b> — numbness or tingling in the hands and feet; the risk is higher with metformin, heartburn medication and a vegan diet.</li><li><b>Iron stores</b> — if your periods are heavy → ferritin.</li><li><b>Breathing during sleep</b> — sleep is unrefreshing, you snore.</li><li><b>Medication.</b> Some \"sleep\" antihistamines, sleeping pills and remedies for frequent urges to urinate dull memory and attention. Don't stop them yourself — discuss an alternative with your doctor.</li><li><b>Hearing.</b> Hearing loss is a notable factor for the brain, and it can be addressed.</li></ul><h3 class=\"art-h\">What helps the brain</h3><p class=\"art-p\"><b>Movement.</b> The strongest lever: both walking and strength training improve attention and the ability to keep several tasks in mind.</p><p class=\"art-p\"><b>Sleep.</b> Start with it — fog more often comes from lack of sleep.</p><p class=\"art-p\"><b>Food.</b> A Mediterranean style, oily fish (actual fish, not capsules), eggs, berries.</p><p class=\"art-p\"><b>Heart and blood vessels.</b> Blood pressure, sugar, waist — what is good for the heart is good for the brain. Less alcohol.</p><p class=\"art-p\"><b>People and new things.</b> Social and mental activity support the brain.</p><h3 class=\"art-h\">What about \"memory\" supplements?</h3><p class=\"art-p\">Ready-made \"memory\" supplements have shown no benefit — neither ginkgo nor trendy \"nootropics\". <b>Creatine</b> gives a small improvement in memory in studies — most noticeably with lack of sleep and in people over 65; for women in peri- and postmenopause there is one first small study in which reaction time became faster, but the result has not yet been repeated. With kidney disease — only after talking to a doctor.</p><h3 class=\"art-h\">When to see a doctor without delay</h3><p class=\"art-p\">This is no longer ordinary fog if:</p><ul class=\"art-ul\"><li>everyday things become hard to manage — money, medication, finding your way in familiar places;</li><li>people close to you notice the decline more than you do;</li><li>it gets worse month after month, with no \"good days\";</li><li>you repeat the same question without noticing, or mix up the meaning of words.</li></ul><h3 class=\"art-h\">What to try this week</h3><ul class=\"art-ul\"><li>Get up at the same time all seven days — sleep first.</li><li>Two strength sessions of 30–40 minutes on different days.</li><li>One task at a time: important things one by one, without switching.</li></ul><!--EV--><p class=\"art-p art-note\"><i>This is general information, not a prescription. Tests and treatment are chosen by a doctor.</i></p>","codes":["P-F10","P-F9","P-F17"]},"weight":{"t":"Why your waist grows even when your weight barely changes","min":"5 min read","h":"<p class=\"art-p\">You eat as before, yet your jeans won't do up. The scales show almost the same number, but your belly looks different. Many women in the transition know this. And it is not \"weak willpower\" — the body has its own logic here.</p><h3 class=\"art-h\">What is happening</h3><p class=\"art-p\">When oestrogen falls, the body responds less well to sugar, and fat starts to be stored not on the hips but around the waist — in the transition, about 6% more each year. Hence three things that seem separate but are really one chain:</p><ul class=\"art-ul\"><li>sugar cravings and energy slumps after meals;</li><li>\"fog\" after lunch;</li><li>a growing waist at the same weight.</li></ul><p class=\"art-p\">A slump after eating and sugar cravings are the body's reaction to a rise and fall in blood sugar, not a matter of character.</p><h3 class=\"art-h\">Measure your waist, not your weight</h3><p class=\"art-p\">In the transition, weight may barely change while fat around the waist grows. So the scales tell you little. The most reliable home guide is <b>a waist smaller than half your height</b>: for example, at a height of 166 cm — under 83 cm. A waist of around 88 cm is a signal to pay attention (for an Asian build — around 80 cm). This is a guide, not a verdict.</p><h3 class=\"art-h\">What has the biggest effect</h3><p class=\"art-p\"><b>Lack of sleep.</b> Even an hour or two of lost sleep noticeably worsens how the body handles sugar — especially in women in menopause. Sleep is a metabolic lever, not just rest.</p><p class=\"art-p\"><b>Too little muscle work.</b> Muscle is the main \"consumer\" of sugar. The less of it there is, the harder it is for the body.</p><p class=\"art-p\"><b>Sugar spikes after meals.</b> They can be noticeably smoothed out — by the order of food and by movement.</p><h3 class=\"art-h\">What to do</h3><p class=\"art-p\"><b>Vegetables and protein before carbohydrates.</b> Start a meal with vegetables and protein, and have bread, grains or sweets afterwards. This smooths the sugar spike by about a third.</p><p class=\"art-p\"><b>A walk after meals.</b> 10–15 minutes straight after eating is a separate route by which muscles take up sugar. It works together with the order of food.</p><p class=\"art-p\"><b>Strength training.</b> The main lever in menopause: muscle takes up sugar and keeps itself from wasting away with age.</p><p class=\"art-p\"><b>Protein at every meal, and fibre.</b> Protein keeps you full and maintains muscle; fibre from vegetables, pulses and whole grains smooths blood sugar.</p><p class=\"art-p\"><b>An early dinner.</b> In the evening blood sugar stays higher, so the main meal is better earlier. But strict fasting does women in the transition no good.</p><p class=\"art-p\"><b>Less refined sugar, fewer sweet drinks and less alcohol.</b></p><h3 class=\"art-h\">About the liver</h3><p class=\"art-p\">A frequent silent companion of a growing waist is fat in the liver. It usually causes no symptoms, and standard liver tests may be normal. No \"cleanses\" or \"detoxes\" are needed — the same steps work: waist, whole foods, strength training, less sugar and alcohol. A doctor can assess the risk.</p><h3 class=\"art-h\">What about weight-loss supplements?</h3><p class=\"art-p\">\"Weight-loss\" supplements have no evidence behind them, and blends with green tea extract can harm the liver. What works is protein at every meal and fibre from food.</p><h3 class=\"art-h\">When to see a doctor</h3><p class=\"art-p\">Severe thirst, frequent urination, sudden unexplained weight loss, episodes of feeling faint — these are reasons to see a doctor and get your blood sugar checked.</p><h3 class=\"art-h\">What to try this week</h3><ul class=\"art-ul\"><li>Start meals with vegetables and protein, carbohydrates afterwards.</li><li>10–15 minutes of walking after your main meals.</li><li>One strength session this week — or better, two.</li></ul><!--EV--><p class=\"art-p art-note\"><i>This is general information, not a prescription. Tests and treatment are chosen by a doctor.</i></p>","codes":["P-F7","P-F1","P-F8"]},"pain":{"t":"Aching joints and morning stiffness: what it is and how to help your body","min":"5 min read","h":"<p class=\"art-p\">You get up in the morning and your body feels wooden. Your knees, fingers and shoulders ache, though nothing has happened. This is often put down to \"age\". But this kind of aching in the transition has a clear cause — and clear steps.</p><h3 class=\"art-h\">Why it hurts</h3><p class=\"art-p\">Oestrogen acts throughout the musculoskeletal system — in bones, joints, ligaments and muscles. When there is less of it, you feel it everywhere at once. Joint aches and stiffness <b>without swelling</b> affect more than half of women in the transition. This is part of the transition, not \"just age\".</p><p class=\"art-p\">On top of that, falling oestrogen removes the natural \"brake\" on background inflammation — so joints, sleep, tiredness and mood often drag each other down.</p><p class=\"art-p\">Another common story at 50–60 is \"frozen shoulder\": the arm is hard to raise both by yourself and with someone's help. For this — see a physiotherapist or orthopaedic specialist.</p><h3 class=\"art-h\">Rest or move?</h3><p class=\"art-p\">Move. Strength training and regular movement are the foundation for joints, muscles and bones.</p><h3 class=\"art-h\">What helps</h3><p class=\"art-p\"><b>Strength training 2–3 times a week, without pain.</b> This is the foundation for joints, muscles and bones alike. Strength training combined with walking or other cardio is best. With a trainer, the protection for bones is noticeably greater, and under supervision even intense strength training is safe.</p><p class=\"art-p\"><b>A little jumping and impact</b> — if your joints allow. This kind of load supports the bones of the hip and spine best.</p><p class=\"art-p\"><b>Balance and mobility.</b> Balance exercises help prevent falls, and therefore fractures.</p><p class=\"art-p\"><b>Protein at every meal.</b> After 40, muscle responds less well to protein and exercise — you need more of both.</p><p class=\"art-p\"><b>A Mediterranean style.</b> Oily fish, olive oil, berries, vegetables and whole grains lower background inflammation; processed meat, sweet drinks and ultra-processed food drive it up.</p><h3 class=\"art-h\">About bones — the part that doesn't hurt</h3><p class=\"art-p\">Bone is lost fastest from about a year before the last period to two years after, and there are no symptoms until a fracture. Indirect signs: you have become more than 4 cm shorter than when you were young, you have started to stoop, your grip has weakened. If you have risk factors — menopause before 45, a fracture from a minor injury, long-term steroid use, a parent with a hip fracture — it is worth discussing a bone density scan with your doctor now. If the risk is high, doctors have treatments that noticeably lower the risk of fractures.</p><h3 class=\"art-h\">What about supplements?</h3><ul class=\"art-ul\"><li><b>Calcium</b> — better from food: yoghurt, cheese, sardines with bones, tofu. Calcium from food is safe, while large supplement doses are debated.</li><li><b>Vitamin D</b> is fine even without a test.</li><li><b>Collagen</b> does not help muscles.</li></ul><h3 class=\"art-h\">When to see a doctor without delay</h3><ul class=\"art-ul\"><li>A joint is swollen, hot or red; small joints of the hands hurt on both sides; morning stiffness lasts longer than half an hour to an hour and eases with movement — see a rheumatologist: it is important not to miss the first months.</li><li>Sudden back pain from an ordinary movement — a cough, turning over in bed — together with loss of height.</li><li>Any fracture from a minor injury.</li><li>Back pain that wakes you at night, together with a fever or unexplained weight loss.</li><li>Numbness in the groin area, weakness in both legs, problems passing urine — urgently.</li></ul><h3 class=\"art-h\">What to try this week</h3><ul class=\"art-ul\"><li>Two strength sessions of 30–40 minutes on different days; the basics are squats, pulls and presses, without pain.</li><li>A source of protein at every meal.</li><li>Calcium from food: yoghurt, cheese, sardines with bones or tofu every day.</li></ul><!--EV--><p class=\"art-p art-note\"><i>This is general information, not a prescription. Tests and treatment are chosen by a doctor.</i></p>","codes":["P-F12","P-F8"]},"muscle":{"t":"Muscles after 40: why they weaken and how to keep them","min":"4 min read","h":"<p class=\"art-p\">It is harder to lift a bag, harder to get up from a low sofa, and climbing the stairs leaves you out of breath. Muscle quietly wastes away with age — and in the transition this speeds up. The good news: muscle responds at any age, and getting your strength back is realistic.</p><h3 class=\"art-h\">What is happening</h3><p class=\"art-p\">Oestrogen helps muscles, and when there is less of it, muscle responds less well to both protein and exercise. Put simply, after 40 you need <b>more</b> of both to get the same result.</p><p class=\"art-p\">Why this matters beyond your figure:</p><ul class=\"art-ul\"><li>muscle is the main \"consumer\" of sugar, and the more of it you have, the easier it is for your metabolism;</li><li>muscle is an \"energy factory\": with it, you feel less tired;</li><li>weakness leads to falls, and falls to fractures.</li></ul><h3 class=\"art-h\">What works</h3><p class=\"art-p\"><b>Strength training 2–3 times a week.</b> This is the main thing. The basics are squats, pulls and presses, without pain. The load should be noticeable: the last repetitions take effort. With a trainer, results and safety are better.</p><p class=\"art-p\"><b>Protein — more than you think.</b> Aim for 30–40 g of protein at every meal, starting with breakfast: that is usually where there is least. That is, for example, a portion of cottage cheese or Greek yoghurt with eggs, a piece of fish or chicken, a plate of lentils with tofu. Over the day, aim for at least 1–1.2 g of protein per kilogram of body weight, and more if you do strength training.</p><p class=\"art-p\"><b>Movement every day.</b> Walking, stairs, housework — in addition to strength training, not instead of it.</p><p class=\"art-p\"><b>Balance.</b> Balance exercises protect against falls.</p><h3 class=\"art-h\">What about supplements?</h3><ul class=\"art-ul\"><li><b>Protein powder</b> is convenient if you can't get enough protein from food. It is food, not medicine.</li><li><b>Creatine</b> is best studied together with strength training: a small but real gain in strength and muscle, including in postmenopausal women. Without training, the data are mixed. With kidney disease — only after talking to a doctor. Creatinine in blood tests rises slightly while taking it — this is not kidney damage.</li><li><b>Collagen</b> does not help muscles.</li></ul><h3 class=\"art-h\">When to see a doctor</h3><ul class=\"art-ul\"><li>Weakness is increasing quickly, without a clear reason.</li><li>You have had a fall or a fracture from a minor injury.</li><li>It is hard to get up from a chair without using your hands, when you used to manage.</li></ul><h3 class=\"art-h\">What to try this week</h3><ul class=\"art-ul\"><li>Two strength sessions of 30–40 minutes on different days.</li><li>A source of protein at every meal — start with breakfast.</li><li>At least once a day, take the stairs instead of the lift.</li></ul><!--EV--><p class=\"art-p art-note\"><i>This is general information, not a prescription. Tests and treatment are chosen by a doctor.</i></p>","codes":["P-F12","P-F5"]},"libido_f":{"t":"Desire and intimacy in the transition: what changes and how to get comfort back","min":"5 min read","h":"<p class=\"art-p\">Desire comes less often, intimacy is sometimes unpleasant or painful, and it feels awkward to talk about even with a doctor. You are not alone: this is one of the most common changes in the transition — and one of the most solvable.</p><h3 class=\"art-h\">What changes with desire</h3><p class=\"art-p\">In the transition, <b>spontaneous</b> desire — the kind that arises \"by itself\" — often fades. This is not a fault. For many women desire is <b>responsive</b>: it comes during intimacy rather than before it — and that is a healthy pattern.</p><p class=\"art-p\">Desire is affected by more than hormones. The biggest obstacles are:</p><ul class=\"art-ul\"><li><b>tiredness and lack of sleep</b> — when there is no energy, there is no desire either;</li><li><b>mood and stress</b>;</li><li><b>the relationship</b> — what happens between people, not just in the body;</li><li><b>medication</b> — for example, some antidepressants lower desire; if you suspect this, discuss it with your doctor;</li><li><b>dryness and discomfort</b> — more on these below.</li></ul><h3 class=\"art-h\">Dryness and discomfort: no need to put up with it</h3><p class=\"art-p\">Dryness, burning, pain during intimacy, frequent urges or recurring cystitis affect half of women after menopause or more. Yet they are rarely talked about: only about half tell their doctor, and most do not know this can be dealt with.</p><p class=\"art-p\">It is important to know: unlike hot flashes, this <b>does not go away on its own</b> and tends to get worse over time. But it responds well to help. And one more thing: pain leads to avoiding intimacy, and avoidance leads to less desire. Removing the discomfort often means getting desire back too.</p><h3 class=\"art-h\">What you can start right away, without a prescription</h3><p class=\"art-p\"><b>A moisturiser and a lubricant are different things.</b> They are often confused:</p><ul class=\"art-ul\"><li>a <b>vaginal moisturiser</b> is used regularly, 2–3 times a week, regardless of intimacy — it keeps moisture in the tissues;</li><li>a <b>lubricant</b> is used only during intimacy, to reduce friction. Water-based or silicone, without fragrance or \"warming\" additives.</li></ul><p class=\"art-p\">Regularity matters as much as the product itself: \"expensive\" does not mean \"effective\".</p><p class=\"art-p\"><b>Pelvic floor exercises</b> and regular intimacy or stimulation support blood flow and comfort.</p><p class=\"art-p\"><b>Remove irritants:</b> intimate soaps and gels, douching, scented products, tight synthetic underwear. Drink enough water, don't smoke.</p><h3 class=\"art-h\">What a doctor can offer</h3><p class=\"art-p\">If a moisturiser and lubricant are not enough, it is worth talking to a gynaecologist. There are local treatments, including low-dose oestrogen: they act where they are applied, are barely absorbed into the blood and, according to many studies, noticeably reduce both dryness and urinary symptoms. There are non-hormonal options too. Which one suits you is for a doctor to decide.</p><h3 class=\"art-h\">What doesn't help</h3><ul class=\"art-ul\"><li><b>Supplements \"for libido\"</b> and \"for moisture from within\" — there is no evidence.</li><li><b>\"Laser rejuvenation\"</b> and radiofrequency procedures heavily marketed by clinics: in studies comparing them with a sham procedure, there was no difference. They are expensive and unproven.</li></ul><h3 class=\"art-h\">When to see a doctor</h3><ul class=\"art-ul\"><li><b>Any bleeding or spotting after menopause</b> — even a drop, even after intimacy. Most often the cause is harmless, but you should always get it checked.</li><li>Severe itching, white patches, cracks or sores that don't go away with a moisturiser — see a gynaecologist.</li><li>Cystitis keeps coming back, or you have a fever with lower back pain.</li></ul><h3 class=\"art-h\">What to try this week</h3><ul class=\"art-ul\"><li>Sleep and rest come first: go to bed half an hour earlier on at least three evenings.</li><li>If you have dryness, start a vaginal moisturiser 2–3 times a week, and use a lubricant for intimacy.</li><li>A few minutes of pelvic floor exercises every day.</li></ul><!--EV--><p class=\"art-p art-note\"><i>This is general information, not a prescription. Tests and treatment are chosen by a doctor.</i></p>","codes":["P-F15","P-F9","P-F20"]},"cycle":{"t":"Your cycle after 35: heavier, less frequent, less predictable — what is happening","min":"5 min read","h":"<p class=\"art-p\">Your period comes after three weeks, then disappears for two months. It has become heavier and longer, with clots. A pad doesn't last the night. Between 35 and 50 such changes are very common — they are one of the first signs of the transition. But \"common\" does not mean \"put up with it\".</p><h3 class=\"art-h\">Why your cycle changes</h3><p class=\"art-p\">In the transition, more and more cycles happen without ovulation, and there is less progesterone. Oestrogen, meanwhile, does not fall — it swings, sometimes higher than usual. Hence the unpredictability and heavier periods.</p><p class=\"art-p\">If you wear a ring or watch: they see the rise in night-time temperature after ovulation only after the fact. If there was no rise in a cycle, that does not mean \"low progesterone\" — after 40 some cycles simply happen without ovulation.</p><h3 class=\"art-h\">What counts as heavy</h3><p class=\"art-p\">Heavy periods are often thought of as \"just how I am\" and go unchecked for years. Guides:</p><ul class=\"art-ul\"><li>you need to change a pad or tampon <b>every hour for several hours in a row</b>;</li><li>clots larger than a coin;</li><li>leaks, needing \"double protection\";</li><li>periods lasting longer than 7 days;</li><li>bleeding limits your normal day.</li></ul><h3 class=\"art-h\">Heavy periods and iron</h3><p class=\"art-p\">Heavy periods are the most common cause of iron deficiency in women. Iron stores fall before a routine blood test changes, and tiredness, breathlessness on the stairs, hair loss, brittle nails and feeling cold appear already then. Particular clues: a craving to chew ice and restless legs in the evening.</p><p class=\"art-p\"><b>What to do:</b></p><ul class=\"art-ul\"><li><b>Ask for a ferritin test</b> — it is the main measure of iron stores. Iron should be taken based on a test, not blindly: too much iron is harmful too.</li><li><b>Iron-rich food.</b> Iron from meat, poultry, fish and seafood is absorbed best. Plant sources — lentils, beans, tofu, pumpkin seeds, dark leafy greens — are best combined with vitamin C at the same meal: bell peppers, citrus fruit, kiwi.</li><li><b>Tea, coffee and dairy — separately</b> from iron-rich food, about an hour apart: they interfere with its absorption.</li></ul><p class=\"art-p\">And most importantly: heavy periods can be treated. Gynaecologists have options that reduce blood loss several-fold. Iron without addressing the cause is a patch, not a solution.</p><h3 class=\"art-h\">Keeping track is half the job</h3><p class=\"art-p\">Log the first day of your period in VIA-L. After a few cycles you will see how your cycle length is changing, and it is easier to go to the doctor with this. A diary also helps you see how your cycle is linked to sleep, mood and hot flashes.</p><h3 class=\"art-h\">What you don't need</h3><ul class=\"art-ul\"><li><b>Supplement sets \"by cycle phase\"</b> are marketing: taking supplements by phase is no better than daily.</li><li><b>\"Seed cycling\"</b> — there are no clinical data. Seeds are good as food, but rotating them by day changes nothing.</li></ul><h3 class=\"art-h\">When to see a doctor without delay</h3><ul class=\"art-ul\"><li>You need to change a pad or tampon every hour for several hours in a row.</li><li>Periods lasting longer than 8 days.</li><li>Bleeding between periods or after intimacy.</li><li>Bleeding together with severe tiredness, breathlessness, feeling faint or fainting.</li><li><b>Any bleeding after 12 months without periods</b> — always a reason to see a gynaecologist promptly.</li></ul><h3 class=\"art-h\">What to try this week</h3><ul class=\"art-ul\"><li>Log the first day of your period in VIA-L.</li><li>With heavy periods — iron-rich food together with vitamin C; tea and coffee an hour later.</li><li>If you recognised yourself in the \"heavy\" list — book a gynaecologist and ask for a ferritin test.</li></ul><!--EV--><p class=\"art-p art-note\"><i>This is general information, not a prescription. Tests and treatment are chosen by a doctor.</i></p>","codes":["P-F22","P-F3","P-F1"]},"evening":{"t":"Coffee before 2 pm, no evening alcohol, early dinner: why it works","min":"3 min read","h":"<p class=\"art-p\">This is one of the simplest steps in the \"Focus of the week\" — and one of the most effective for sleep. It is not about adding something, but about removing three things that quietly spoil the night.</p><h3 class=\"art-h\">Why it works</h3><p class=\"art-p\"><b>Coffee keeps the body \"switched on\".</b> Caffeine raises stress hormones and keeps them from falling by evening. It acts for a long time, so a cup at four in the afternoon makes it hard to fall asleep at midnight. The cut-off is around 2 pm, that is, 8–9 hours before bed.</p><p class=\"art-p\"><b>Alcohol is a \"false friend\".</b> A glass in the evening helps you fall asleep but breaks up the second half of the night: more awakenings, poorer recovery. It makes hot flashes worse even in small amounts, and in perimenopause it unsettles anxiety — calming you for an hour, then making things worse.</p><p class=\"art-p\"><b>A late dinner keeps the body from cooling down and settling.</b> Your last heavy meal — three hours before bed.</p><h3 class=\"art-h\">How to do it</h3><ul class=\"art-ul\"><li><b>Coffee and strong tea only before 2 pm.</b> After that — herbal tea, water, decaf.</li><li><b>A one-week break from evening alcohol.</b> Not forever, just for a week — to see the difference for yourself.</li><li><b>Dinner three hours before bed.</b> If you go to bed at 11 pm, have dinner before 8 pm.</li></ul><h3 class=\"art-h\">What can get in the way</h3><ul class=\"art-ul\"><li>The habit of \"coffee after lunch so I don't fall asleep\". Instead — a 10-minute walk outside.</li><li>A glass of wine \"to relax\". Try a replacement ritual: a warm shower, a walk, slow breathing.</li><li>Getting home late from work. Then — a light dinner, with your main meal earlier in the day.</li></ul><h3 class=\"art-h\">What to expect</h3><p class=\"art-p\">Look not at one night but at a week: how quickly you fall asleep, how many times you wake, how you feel in the morning. Log your sleep and hot flashes in VIA-L — that way you will see the difference in numbers, not just in how you feel.</p><h3 class=\"art-h\">Who this step helps</h3><p class=\"art-p\">Those with poor sleep, night-time hot flashes and morning tiredness. It often goes together with the step \"Same wake-up time and morning light\".</p><!--EV--><p class=\"art-p art-note\"><i>This is general information, not a prescription.</i></p>","codes":["P-F17","P-F4","P-F9"]},"wake":{"t":"Same wake-up time and morning light: an anchor for the whole day","min":"3 min read","h":"<p class=\"art-p\">It seems that sleep starts in the evening. In fact it starts in the morning — with what time you get up and see daylight. This is the strongest behavioural lever for sleep, mood and energy, and it costs nothing.</p><h3 class=\"art-h\">Why it works</h3><p class=\"art-p\">Your body has an internal clock. It decides when you feel alert and when you feel sleepy, and it sets itself mainly by two signals: <b>the time you get up</b> and <b>daylight in the morning</b>. When these signals differ every day, the clock drifts: in the evening your mind won't switch off, in the morning it won't get going. In the transition this is felt especially strongly.</p><p class=\"art-p\"><b>A regular wake-up time matters more than how long you sleep.</b> Weekends of \"catching up\" until lunchtime throw the clock off again.</p><p class=\"art-p\"><b>Morning light is the strongest signal for the clock.</b> 10–15 minutes outdoors works even on a cloudy day — stronger than any lamp. And bright morning light also noticeably lifts mood in perimenopause.</p><h3 class=\"art-h\">How to do it</h3><ul class=\"art-ul\"><li><b>Get up at the same time all seven days</b>, weekends included, within half an hour.</li><li><b>In the first hour after waking — 10–15 minutes of daylight.</b> A walk, coffee on the balcony, walking to work.</li><li><b>In the evening — the opposite:</b> for 30–60 minutes before bed, warm dim light and no screens.</li></ul><h3 class=\"art-h\">What can get in the way</h3><ul class=\"art-ul\"><li>A bad night. Even after one, get up at your usual time — that way the next night will be better.</li><li>A dark winter morning. Go outside as soon as it is light, or spend the first minutes by a window.</li><li>Weekends. Half an hour is fine, three hours is not.</li></ul><h3 class=\"art-h\">What to expect</h3><p class=\"art-p\">The clock does not reset overnight. Judge it over a week or two: how you fall asleep, how you wake, your mood in the morning. Log your sleep and how you feel in VIA-L.</p><h3 class=\"art-h\">Who this step helps</h3><p class=\"art-p\">Those who have trouble falling asleep, wake in the night, feel exhausted in the morning, or have mood swings and \"fog\". It works well together with the step \"Coffee before 2 pm, no evening alcohol, early dinner\".</p><!--EV--><p class=\"art-p art-note\"><i>This is general information, not a prescription.</i></p>","codes":["P-F4","P-F17","P-F9"]},"strength":{"t":"Strength training twice a week: one step, benefits for everything","min":"4 min read","h":"<p class=\"art-p\">If you could choose only one piece of advice for the transition, it would be strength training. It works on hot flashes, mood, bones, muscles, metabolism and sleep all at once. And you don't need a gym for it.</p><h3 class=\"art-h\">Why it works</h3><ul class=\"art-ul\"><li><b>Hot flashes.</b> Strength training is the strongest lever without medication: in the best study, hot flashes roughly halved.</li><li><b>Mood.</b> It improves even before strength and weight have changed.</li><li><b>Bones.</b> Load is the main signal for bone to stay strong; strength training together with a little jumping works best.</li><li><b>Muscles and energy.</b> After 40, muscle responds less well to load — so it needs more, not less.</li><li><b>Metabolism.</b> Muscle is the main \"consumer\" of sugar; strength training also lowers background inflammation, even without weight loss.</li><li><b>Brain.</b> Movement improves attention and clarity.</li></ul><h3 class=\"art-h\">How to do it</h3><ul class=\"art-ul\"><li><b>Two sessions of 30–40 minutes on different days.</b></li><li><b>The basics are squats, pulls and presses.</b> For example: squats to a chair, pulling a resistance band towards your waist, push-ups against a wall or table, step-ups, overhead dumbbell presses.</li><li><b>Without pain.</b> The load should be noticeable, but not painful.</li><li><b>Build up gradually.</b> When it gets easy — a little more weight or more repetitions.</li></ul><p class=\"art-p\">With a trainer, results and safety are better. VIA-L has a voice-guided \"Workout of the day\" — you can start with that.</p><h3 class=\"art-h\">Who should take more care</h3><ul class=\"art-ul\"><li><b>High blood pressure:</b> don't hold your breath during effort — breathe out as you lift. After floor exercises, get up slowly.</li><li><b>Diabetes medication:</b> with new exercise, blood sugar can drop more than usual. Keep a quick snack to hand, and stop if you feel weak or shaky.</li><li><b>Joint or back pain:</b> if an exercise causes pain, replace it with an easier one or reduce the weight.</li></ul><p class=\"art-p\">If you are not sure whether the exercise is right for you, discuss it with your doctor.</p><h3 class=\"art-h\">What can get in the way</h3><ul class=\"art-ul\"><li>\"I don't have time.\" Two 30-minute sessions is an hour a week.</li><li>\"I've never done this.\" Start with your own body weight and a chair. Regularity matters, not records.</li></ul><h3 class=\"art-h\">What to expect</h3><p class=\"art-p\">Mood and how you feel often change before strength and figure do. Log your workouts, hot flashes and mood in VIA-L — in a few weeks you will see what is changing for you.</p><h3 class=\"art-h\">Who this step helps</h3><p class=\"art-p\">Almost everyone: with hot flashes, tiredness, mood swings, a growing waist, aching joints and muscle weakness.</p><!--EV--><p class=\"art-p art-note\"><i>This is general information, not a prescription.</i></p>","codes":["P-F1","P-F12","P-F7","P-F8"]},"protein":{"t":"Protein at every meal: why you need more after 40","min":"3 min read","h":"<p class=\"art-p\">In the morning, coffee and a biscuit; during the day, something on the go; in the evening, a proper dinner. A great many people eat like this. And in this pattern there is almost no protein until the evening. After 40 this noticeably affects energy, muscles and sugar cravings.</p><h3 class=\"art-h\">Why it works</h3><p class=\"art-p\"><b>Muscle has become \"more demanding\".</b> After 40 it responds less well to protein, so to keep it you need more protein than before — and spread evenly through the day, not all at dinner.</p><p class=\"art-p\"><b>Protein brings fullness and steady blood sugar.</b> A protein-rich meal keeps you full for longer and smooths out sugar spikes — fewer slumps and fewer sugar cravings.</p><p class=\"art-p\"><b>A protein breakfast evens out the day.</b> A skipped or \"empty\" breakfast keeps stress hormones high, and a slump follows during the day. It is better to have breakfast within an hour or two of waking.</p><h3 class=\"art-h\">How to do it</h3><ul class=\"art-ul\"><li><b>A source of protein at every meal.</b> Aim for 30–40 g of protein per meal.</li><li><b>Start with breakfast:</b> that is usually where there is least protein.</li><li><b>Over the day</b> — at least 1–1.2 g of protein per kilogram of body weight, more if you do strength training.</li></ul><p class=\"art-p\">What 30–40 g of protein looks like in practice — roughly:</p><ul class=\"art-ul\"><li>breakfast: an omelette of 2–3 eggs with cottage cheese, or Greek yoghurt with nuts;</li><li>lunch: a palm-sized portion of fish, chicken or meat;</li><li>dinner: lentils or beans with tofu, cheese, seafood.</li></ul><p class=\"art-p\">Protein powder is a handy back-up if you can't get enough from food.</p><h3 class=\"art-h\">Who should take more care</h3><ul class=\"art-ul\"><li><b>With kidney disease</b>, agree the amount of protein with your doctor.</li><li><b>If you have had difficulties with food</b> — an eating disorder now or in the past — food rules are better discussed with a specialist than introduced on your own.</li></ul><h3 class=\"art-h\">What can get in the way</h3><ul class=\"art-ul\"><li>\"I can't eat in the morning.\" Start small: a yoghurt, an egg, a glass of kefir.</li><li>\"I don't have time to cook.\" Boiled eggs, cottage cheese, tinned fish, ready-cooked lentils — no cooking needed.</li></ul><h3 class=\"art-h\">What to expect</h3><p class=\"art-p\">Notice how fullness and sugar cravings between meals change. Log your energy and how you feel in VIA-L.</p><h3 class=\"art-h\">Who this step helps</h3><p class=\"art-p\">Those with tiredness, a growing waist, muscle weakness and aching joints. It works well together with strength training.</p><!--EV--><p class=\"art-p art-note\"><i>This is general information, not a prescription.</i></p>","codes":["P-F12","P-F7","P-F4"]},"cool":{"t":"A cool bedroom: a simple way to sleep better with hot flashes","min":"3 min read","h":"<p class=\"art-p\">At night you are thrown into a heat, you kick off the duvet, then you get cold, then hot again — and so on until morning. If this sounds familiar, a cool bedroom is one of the simplest steps you can take today.</p><h3 class=\"art-h\">Why it works</h3><p class=\"art-p\">In the transition the \"thermal comfort zone\" narrows: a very small amount of heat is enough to trigger a hot flash. And most night-time hot flashes coincide with waking up. A cool bedroom keeps your body further from that threshold.</p><p class=\"art-p\">To be honest: cooling does not restore the comfort zone and does not \"cancel\" hot flashes. But it noticeably reduces night-time awakenings and discomfort — and adds deep sleep.</p><h3 class=\"art-h\">How to do it</h3><ul class=\"art-ul\"><li><b>Bedroom temperature around 16–19 °C.</b> Air the room before bed, turn the heating down.</li><li><b>Darkness.</b> Blackout curtains or a sleep mask.</li><li><b>Breathable fabrics.</b> Bedding and nightwear in cotton, linen or other breathable fabrics.</li><li><b>Layers instead of one warm duvet.</b> A light duvet plus a throw — so you can easily take something off at night without fully waking.</li><li><b>A cooling mattress topper or pillow</b> — if your hot flashes are severe.</li><li><b>Water by the bed</b> and a spare T-shirt — in case of night sweats.</li></ul><h3 class=\"art-h\">What can get in the way</h3><ul class=\"art-ul\"><li>Your partner gets cold. Separate duvets help: one each.</li><li>A hot summer. A fan, airing the room at night, a cool shower before bed.</li><li>The habit of warm pyjamas. Switch to light ones, and keep warm socks — if your feet get cold.</li></ul><h3 class=\"art-h\">What to expect</h3><p class=\"art-p\">Look first of all at how many times you wake in the night. Log your sleep and hot flashes in VIA-L to compare the week before and the week after.</p><h3 class=\"art-h\">If it doesn't help</h3><p class=\"art-p\">If severe hot flashes still break up the night, that is a reason to see a doctor. Treating the hot flashes themselves improves sleep too. More in the article \"Hot flashes: why they happen and what really helps\".</p><h3 class=\"art-h\">Who this step helps</h3><p class=\"art-p\">Those with night-time hot flashes, night sweats and waking in the night.</p><!--EV--><p class=\"art-p art-note\"><i>This is general information, not a prescription.</i></p>","codes":["P-F17","P-F1"]},"walk":{"t":"A walk after meals: 10 minutes that change the whole day","min":"3 min read","h":"<p class=\"art-p\">After lunch you feel sleepy, a couple of hours later you crave something sweet, and by evening you have no energy. This is often not \"character\" but the sugar rollercoaster after meals. And one of the simplest remedies is a short walk straight after eating.</p><h3 class=\"art-h\">Why it works</h3><p class=\"art-p\">After a meal, blood sugar rises. When muscles move, they take up sugar — this is a separate route for using it, in addition to the usual one. The peak is lower, and so the slump that follows is smaller too: less drowsiness and fewer sugar cravings.</p><p class=\"art-p\">Walking works especially well together with another step — \"Vegetables and protein before carbs\": the effects add up.</p><h3 class=\"art-h\">How to do it</h3><ul class=\"art-ul\"><li><b>10–15 minutes of walking after your main meals.</b> Ideally straight after eating, not an hour later.</li><li><b>At a normal pace,</b> one where you can still talk. This is not a workout, just movement.</li><li><b>If you can't go out</b> — walk around the house, use the stairs, tidy up, wash the dishes standing.</li></ul><h3 class=\"art-h\">Who should take more care</h3><ul class=\"art-ul\"><li><b>Diabetes medication:</b> with new exercise, blood sugar can drop more than usual. Keep a quick snack to hand, and stop if you feel weak or shaky.</li><li><b>An injury, illness or fever</b> — recover first; this step can wait.</li></ul><h3 class=\"art-h\">What can get in the way</h3><ul class=\"art-ul\"><li>A desk job. A short walk after lunch, taking a call on the move, the stairs instead of the lift.</li><li>The weather. Walking around the house or a shopping centre counts too.</li><li>The evening. Even 10 minutes after dinner is better than going straight to the sofa.</li></ul><h3 class=\"art-h\">What to expect</h3><p class=\"art-p\">Notice your after-lunch drowsiness and sugar cravings. Log your energy and how you feel in VIA-L.</p><h3 class=\"art-h\">Who this step helps</h3><p class=\"art-p\">Those with energy slumps after meals, sugar cravings and a growing waist.</p><!--EV--><p class=\"art-p art-note\"><i>This is general information, not a prescription.</i></p>","codes":["P-F7","P-F1"]},"breath":{"t":"Slow breathing: calm in five minutes","min":"3 min read","h":"<p class=\"art-p\">Anxiety washes over you for no reason, irritation flares over little things, and in the evening your thoughts won't let you sleep. Slow breathing is one of the simplest ways to calm the nervous system. It works without willpower and without special conditions.</p><h3 class=\"art-h\">Why it works</h3><p class=\"art-p\">A slow in-breath and especially a long out-breath directly switch the nervous system from \"alarm\" mode to \"rest\" mode. It is a reflex — you don't need to talk yourself into it. In studies, slow breathing and meditation are comparable to medication in their effect on anxiety.</p><h3 class=\"art-h\">What breathing doesn't do</h3><p class=\"art-p\">To be honest: slow breathing does not reduce hot flashes themselves — in studies it is no better than a placebo. Nor do yoga and meditation. For hot flashes, strength training, a cool bedroom and, without medication, cognitive behavioural therapy and clinical hypnosis work better. More in the article \"Hot flashes: why they happen and what really helps\".</p><p class=\"art-p\">Breathing is for calm, anxiety and irritation. That is the reason to do it.</p><h3 class=\"art-h\">How to do it</h3><ul class=\"art-ul\"><li><b>Breathe in through your nose for a count of four, out slowly for a count of six.</b> That comes to about six breaths a minute.</li><li><b>5–10 minutes a day.</b> Even five minutes has an effect.</li><li><b>The evening is most convenient</b> — it helps you move towards sleep. But you can also do it during the day, in any pause: before a meeting, in the car before getting out, after work.</li><li><b>When anxiety hits</b> — switch straight away to slow, long out-breaths.</li></ul><p class=\"art-p\">Relax your shoulders and breathe with your belly. If you feel dizzy, breathe less deeply and a little faster.</p><h3 class=\"art-h\">Who should take more care</h3><p class=\"art-p\"><b>With asthma</b>, breathe calmly, without holding your breath or straining. If an attack starts, stop and use your usual treatment.</p><h3 class=\"art-h\">What can get in the way</h3><ul class=\"art-ul\"><li>\"My thoughts drift off.\" That is part of the practice: notice it and come back to counting.</li><li>\"I forget.\" Link breathing to something that happens every day anyway: brushing your teeth in the evening, the light going off.</li><li>\"Breathing alone won't fix my sleep.\" True: for sleep, a fixed wake-up time and the rule \"bed is for sleep only\" are stronger. Breathing is an addition to them.</li></ul><h3 class=\"art-h\">What to expect</h3><p class=\"art-p\">Notice how often anxiety and irritation hit and how you fall asleep. If you wear a ring or watch, you can compare heart rate variability on evenings with and without breathing. Log how you feel in VIA-L.</p><h3 class=\"art-h\">If it doesn't help</h3><p class=\"art-p\">If anxiety or low mood lasts more than two weeks and gets in the way of life, that is a reason to see a doctor. More in the article \"Mood swings, anxiety and irritability\".</p><!--EV--><p class=\"art-p art-note\"><i>This is general information, not a prescription.</i></p>","codes":["P-F4","P-F9","P-F1"]},"bed":{"t":"Bed is for sleep only: how to help your body relearn falling asleep","min":"3 min read","h":"<p class=\"art-p\">You go to bed tired — and sleep vanishes. You lie there for an hour, scroll your phone, count how long until the alarm. The longer this goes on, the more firmly the brain links the bed not with sleep but with being awake and anxious. This step restores the right link.</p><h3 class=\"art-h\">Why it works</h3><p class=\"art-p\">This is the core of the behavioural approach to sleep — according to studies, it is more effective than both sleeping pills and a simple list of \"sleep hygiene\" rules. The idea is simple: the bed should mean sleep again. When you only sleep in it, the brain relearns to fall asleep as soon as your head touches the pillow.</p><h3 class=\"art-h\">How to do it</h3><ul class=\"art-ul\"><li><b>Don't lie awake.</b> If you can't sleep for more than 15–20 minutes, get up, go somewhere else with dim light and do something calm. Come back when you start to feel sleepy.</li><li><b>Don't work or scroll your phone in bed.</b> Charge your phone away from the bed.</li><li><b>Don't look at the clock at night.</b> Counting the hours left only adds to the anxiety.</li><li><b>Go to bed when you feel sleepy, and get up at the same time.</b> Going to bed early \"just in case\" often means lying awake for longer.</li><li><b>No screens for 30–60 minutes before bed.</b></li></ul><h3 class=\"art-h\">Who should take more care</h3><p class=\"art-p\"><b>If you take blood pressure medication or are over 70:</b> don't get up suddenly at night — sit on the edge of the bed for a minute first. Keep the hallway light dim but bright enough not to trip.</p><p class=\"art-p\">If daytime sleepiness makes driving difficult, don't drive when you are tired.</p><h3 class=\"art-h\">What can get in the way</h3><ul class=\"art-ul\"><li>\"My phone is my alarm.\" Use an ordinary alarm clock, or put the phone where you have to get up to reach it.</li><li>\"Getting up at night is hard.\" It may feel unusual for the first few days. The main thing is not to lie awake for hours.</li><li>\"There's nowhere to go in my flat.\" An armchair in the same room with a dim lamp will do.</li></ul><h3 class=\"art-h\">What to expect</h3><p class=\"art-p\">Notice how long you lie awake and how many times you wake. Log your sleep in VIA-L to see the difference week by week.</p><h3 class=\"art-h\">When to see a doctor</h3><p class=\"art-p\">If poor sleep lasts more than three months despite these steps, or if you snore with pauses, have unrefreshing sleep or fall asleep during the day — it is worth seeing a doctor or sleep specialist. More in the article \"Why sleep gets worse after 40\".</p><!--EV--><p class=\"art-p art-note\"><i>This is general information, not a prescription.</i></p>","codes":["P-F17","P-F3","P-F4"]},"order":{"t":"Vegetables and protein before carbs: the same lunch, gentler on blood sugar","min":"3 min read","h":"<p class=\"art-p\">This step is not about eating less or giving up foods you love. It is about order: what to eat first. A simple rearrangement on your plate noticeably changes how your body copes with food.</p><h3 class=\"art-h\">Why it works</h3><p class=\"art-p\">If you start a meal with vegetables and protein, and eat bread, grains, potatoes or pasta afterwards, the sugar spike after the meal is gentler — by about a third. A smaller spike means a smaller slump afterwards: less drowsiness after lunch and fewer sugar cravings.</p><p class=\"art-p\">In the transition the body responds less well to sugar, so simple techniques like this are especially useful. And together with a walk after meals, the effects add up.</p><h3 class=\"art-h\">How to do it</h3><ul class=\"art-ul\"><li><b>Vegetables first</b> — salad, cooked or raw vegetables.</li><li><b>Then protein</b> — meat, fish, eggs, tofu, pulses.</li><li><b>Carbohydrates last:</b> the side dish, the bread.</li></ul><p class=\"art-p\">All on one plate, simply in this order. You don't need to eat less.</p><h3 class=\"art-h\">Who should take more care</h3><ul class=\"art-ul\"><li><b>If you have had difficulties with food</b> — an eating disorder now or in the past — food rules are better discussed with a specialist than introduced on your own.</li><li><b>If you take warfarin:</b> don't change the amount of green vegetables suddenly — it affects how the medicine works. Discuss any changes in your diet with your doctor.</li></ul><h3 class=\"art-h\">What can get in the way</h3><ul class=\"art-ul\"><li>\"I have no vegetables.\" Frozen ones or a simple plate of cucumber, tomato and pepper will do.</li><li>\"Eating out or at friends'.\" Start with a salad or a vegetable starter, bread afterwards.</li><li>\"Breakfast is porridge or a sandwich.\" Add an egg, cottage cheese or vegetables to it first.</li></ul><h3 class=\"art-h\">What to expect</h3><p class=\"art-p\">Notice how full you feel after meals, your after-lunch drowsiness and sugar cravings. Weight changes more slowly, so go by how you feel. Log it in VIA-L.</p><h3 class=\"art-h\">Who this step helps</h3><p class=\"art-p\">Those with a growing waist, energy slumps after meals and sugar cravings. It works well together with a walk after meals and protein at every meal.</p><!--EV--><p class=\"art-p art-note\"><i>This is general information, not a prescription.</i></p>","codes":["P-F7","P-F1"]}},"es":{"start-peri":{"t":"Qué es la perimenopausia y cómo reconocerla","min":"4 minutos de lectura","h":"<p class=\"art-p\">Duermes peor, la regla es menos predecible, tu ánimo sube y baja, y los análisis salen «bien». ¿Te suena? Muy a menudo detrás de todo esto está la perimenopausia: los años de transición antes de la última regla. No es una enfermedad, sino una etapa por la que pasa cada mujer. Pero apenas se habla de ella, y por eso muchas mujeres pasan años sin entender qué les ocurre.</p><h3 class=\"art-h\">Qué pasa en el cuerpo</h3><p class=\"art-p\">En la transición, las hormonas no cambian de forma suave ni todas a la vez.</p><p class=\"art-p\"><b>La progesterona baja primero, y de forma constante.</b> Después de los 40, cada vez más ciclos ocurren sin ovulación, y esto es una parte normal de la transición. La progesterona alimenta el «calmante» natural del cerebro, por eso su descenso suele notarse como dificultad para conciliar el sueño.</p><p class=\"art-p\"><b>El estrógeno, mientras tanto, no baja: oscila.</b> Unas veces baja, otras sube por encima de lo habitual, y solo después desciende de forma definitiva. Lo que más altera cómo te sientes en estos años es la amplitud de esas oscilaciones, no el nivel en sí. De ahí la sensación de que «nada tiene sentido»: una semana va bien y la siguiente es difícil.</p><h3 class=\"art-h\">Cómo reconocerla</h3><p class=\"art-p\">La perimenopausia se reconoce por un cuadro que se va formando con el tiempo, no por un solo análisis. Señales típicas:</p><ul class=\"art-ul\"><li><b>El ciclo cambia.</b> Entre los 35 y los 50, la regla a menudo se vuelve más abundante, más larga o más irregular.</li><li><b>El sueño.</b> Cuesta más dormirse, te despiertas más por la noche, la mente «no se apaga».</li><li><b>El ánimo.</b> Altibajos, irritabilidad; los días antes de la regla se notan más que antes.</li><li><b>Pecho y líquidos.</b> Pecho hinchado y sensible, hinchazón.</li><li><b>La cabeza.</b> Migrañas, «niebla mental», peor concentración.</li><li><b>Sofocos y sudores nocturnos.</b> Pueden empezar ya en estos años.</li></ul><p class=\"art-p\">No hace falta tenerlo todo a la vez. Importa más el patrón: qué se repite y cómo se relaciona con el ciclo.</p><h3 class=\"art-h\">Qué hacer primero</h3><p class=\"art-p\"><b>Empieza a registrar.</b> El primer día de la regla, el sueño, los sofocos, el ánimo: cada día, brevemente. En unas semanas verás relaciones que la memoria no retiene. Ese es el mejor «análisis» de la transición.</p><p class=\"art-p\"><b>Pon un ancla al sueño.</b> Levántate a la misma hora los siete días de la semana, fines de semana incluidos, y toma 10–15 minutos de luz natural en la primera hora tras levantarte. Es la palanca de conducta más fuerte para el sueño, más que cualquier suplemento.</p><p class=\"art-p\"><b>Quita lo que altera la noche.</b> Café y té fuerte, antes de las 14:00; por la noche, sin alcohol: da sueño, pero corta la segunda mitad de la noche.</p><p class=\"art-p\"><b>Revisa el hierro si tus reglas son abundantes.</b> Las reglas abundantes son la causa más frecuente de falta de hierro en las mujeres, y sus reservas bajan antes de que cambien los análisis de sangre habituales. Cansancio, falta de aire al subir escaleras, caída del pelo: motivo para pedir a tu médico un análisis de ferritina. El hierro, según el análisis, no a ciegas.</p><h3 class=\"art-h\">Cuándo ir al médico sin esperar</h3><ul class=\"art-ul\"><li>Tienes que cambiar la compresa o el tampón cada hora durante varias horas seguidas.</li><li>La regla dura más de 8 días.</li><li>Sangrado entre reglas.</li><li>Sangrado junto con mucho cansancio o mareo.</li></ul><p class=\"art-p\">No es «solo la transición»: estas señales hay que enseñárselas al ginecólogo.</p><h3 class=\"art-h\">Qué probar esta semana</h3><ul class=\"art-ul\"><li>Anotar en VIA-L el primer día de la regla y el sueño.</li><li>Levantarte a la misma hora los siete días.</li><li>Café antes de las 14:00, noche sin alcohol.</li></ul><!--EV--><p class=\"art-p art-note\"><i>Esto es información general, no una prescripción. Las pruebas y el tratamiento los decide un médico.</i></p>","codes":["P-F1","P-F3","P-F17","P-F22"]},"start-meno":{"t":"Menopausia: qué cambia después de la última regla","min":"5 minutos de lectura","h":"<p class=\"art-p\">La menopausia es el momento en que llevas doce meses seguidos sin regla. Todo lo que viene después es la posmenopausia. El estrógeno ahora es bajo de forma estable, y el cuerpo se adapta a esta nueva realidad. Algunos cambios se notan enseguida; otros son «silenciosos» y solo aparecerán con los años. Conviene conocer estos últimos de antemano: precisamente en los primeros años tras la menopausia es cuando más puedes hacer para las décadas siguientes.</p><h3 class=\"art-h\">Lo que se nota</h3><p class=\"art-p\">Cuando hay poco estrógeno, se forma un cuadro reconocible: sofocos, sudores nocturnos, sueño entrecortado, sequedad y molestias en las relaciones íntimas, dolor en articulaciones y músculos, «niebla mental». Es una sola historia, no un conjunto de problemas separados, y conviene abordarla en conjunto.</p><p class=\"art-p\">Un apunte aparte sobre la sequedad y las molestias en las relaciones íntimas. Es un cambio muy frecuente —en la mitad de las mujeres o más—, pero casi no se habla de él. A diferencia de los sofocos, no desaparece solo y con el tiempo tiende a empeorar. La buena noticia es que responde bien a la ayuda: un hidratante habitual, un lubricante para las relaciones, ejercicios de suelo pélvico y una conversación con el médico. No hace falta aguantarlo.</p><h3 class=\"art-h\">Lo que no se nota, pero importa</h3><p class=\"art-p\"><b>Corazón y vasos sanguíneos.</b> Antes de la menopausia, el riesgo de enfermedad cardíaca de las mujeres es aproximadamente la mitad que el de los hombres; con la caída del estrógeno, la diferencia se cierra rápido. La aceleración más brusca ocurre en el año o dos alrededor de la última regla: sube el colesterol «malo» y los vasos se vuelven más rígidos. No es un veredicto, sino una ventana para la prevención.</p><p class=\"art-p\"><b>Huesos.</b> El hueso se pierde más rápido desde aproximadamente un año antes de la última regla hasta dos años después: hasta un 2% al año en la columna. No hay síntomas hasta que llega una fractura. Si tuviste una menopausia temprana antes de los 45, una fractura por un golpe leve, tomaste corticoides mucho tiempo o tu padre o tu madre tuvo una fractura de cadera, conviene hablar con tu médico de una densitometría ya, sin esperar a los 65.</p><p class=\"art-p\"><b>Músculos y metabolismo.</b> La grasa se desplaza hacia la barriga, el cuerpo responde peor al azúcar, y el músculo, a la proteína y al ejercicio. Los antojos de dulce, la «niebla» y el cambio de figura son una misma cadena.</p><h3 class=\"art-h\">Qué hacer</h3><p class=\"art-p\"><b>Entrenamiento de fuerza dos veces por semana.</b> Es una palanca para todo a la vez: sofocos, ánimo, huesos, músculos y metabolismo. La base son sentadillas, tirones y empujes, sin dolor.</p><p class=\"art-p\"><b>Proteína en cada comida, empezando por el desayuno.</b> Después de los 40, el músculo necesita más proteína que antes, y el desayuno suele ser donde menos hay.</p><p class=\"art-p\"><b>Caminar después de comer.</b> 10–15 minutos después de comer ayudan al cuerpo a manejar el azúcar.</p><p class=\"art-p\"><b>Un estilo de alimentación mediterráneo.</b> Aceite de oliva, pescado, frutos secos, verduras y fibra: la forma mejor estudiada de cuidar el corazón y los vasos.</p><p class=\"art-p\"><b>Conoce tus números.</b> Tensión, azúcar, colesterol y, si es posible, pide a tu médico ApoB y Lp(a): muestran con más precisión el riesgo para los vasos, y la Lp(a) basta con medirla una vez en la vida.</p><h3 class=\"art-h\">Cuándo ir al médico sin esperar</h3><p class=\"art-p\">Cualquier sangrado después de doce meses sin regla es siempre motivo para ir pronto al ginecólogo.</p><h3 class=\"art-h\">Qué probar esta semana</h3><ul class=\"art-ul\"><li>Dos sesiones de fuerza de 30–40 minutos en días distintos.</li><li>Una fuente de proteína en cada comida; empieza por el desayuno.</li><li>10–15 minutos de paseo después de la comida principal.</li></ul><!--EV--><p class=\"art-p art-note\"><i>Esto es información general, no una prescripción. Las pruebas y el tratamiento los decide un médico.</i></p>","codes":["P-F1","P-F12","P-F13","P-F15"]},"start-tests":{"t":"Por qué los análisis hormonales después de los 40 dicen tan poco","min":"4 minutos de lectura","h":"<p class=\"art-p\">Cuando empiezas a sentirte distinta, lo primero que apetece es «hacerse las hormonas» y ver la respuesta en números. Pero en los años de transición son precisamente estos análisis los que más a menudo fallan. Veamos por qué, y qué análisis sí merecen la pena.</p><h3 class=\"art-h\">Por qué las hormonas no se dejan atrapar en un análisis</h3><p class=\"art-p\"><b>Saltan.</b> En la perimenopausia el estrógeno oscila arriba y abajo, y la FSH, el estradiol y la progesterona cambian tanto después de los 40 que un análisis es una foto de un día cualquiera. Mañana los números serán otros.</p><p class=\"art-p\"><b>La progesterona va a pulsos.</b> Su nivel en sangre puede multiplicarse o dividirse en cuestión de minutos. Incluso un análisis de sangre solo muestra un instante, y los tests caseros ni siquiera la miden.</p><p class=\"art-p\"><b>Tu dispositivo no mide hormonas.</b> Un anillo o un reloj detectan la subida de temperatura tras la ovulación, pero a posteriori y solo como una marca. Si no hubo subida, no significa «poca progesterona»: después de los 40 algunos ciclos ocurren sin ovulación, y también influyen el ruido del sensor, un sofoco o un resfriado.</p><p class=\"art-p\">Por eso la perimenopausia no se reconoce por un análisis, sino por el cuadro a lo largo del tiempo: cómo cambian el ciclo, el sueño, el ánimo, los sofocos. Un diario de unas semanas dice más que un informe de laboratorio.</p><h3 class=\"art-h\">Qué es importante descartar</h3><p class=\"art-p\">Algunos síntomas de la transición se parecen a otros problemas fáciles de comprobar y que se pueden tratar. Conviene descartarlos primero:</p><ul class=\"art-ul\"><li><b>Tiroides</b> — si tienes más frío de lo normal, estreñimiento o el pulso lento: análisis de TSH.</li><li><b>Reservas de hierro</b> — si tus reglas son abundantes, estás cansada, te falta el aire al subir escaleras, te apetece masticar hielo o por la noche te molestan las piernas: análisis de ferritina. El hierro baja antes de que cambie un análisis de sangre habitual.</li><li><b>Ánimo</b> — si el bajón o la ansiedad duran todo el mes, no solo antes de la regla, es motivo para hablarlo aparte con tu médico.</li><li><b>Respiración durante el sueño</b> — ronquidos con pausas, sueño que no descansa, somnolencia de día: después de la menopausia es una causa de cansancio frecuente y a menudo pasada por alto.</li></ul><h3 class=\"art-h\">Qué análisis sí son útiles después de los 40</h3><ul class=\"art-ul\"><li><b>Tensión y azúcar</b> — con regularidad.</li><li><b>ApoB</b> — muestra con más precisión que el «colesterol malo» habitual las partículas peligrosas para los vasos.</li><li><b>Lp(a)</b> — basta con medirla una vez en la vida: es hereditaria y sube después de la menopausia.</li><li><b>PCR ultrasensible (hs-CRP)</b> — un indicador de inflamación de fondo; en las mujeres predice bien el riesgo cardíaco.</li><li><b>Ferritina y TSH</b> — según las señales de arriba.</li><li><b>Densitometría</b> — ya en la menopausia si hay factores de riesgo: menopausia antes de los 45, fractura por un golpe leve, corticoides durante mucho tiempo, fractura de cadera en tu padre o tu madre.</li></ul><p class=\"art-p\">Pide a tu médico algo más que «el colesterol»: si es posible, ApoB y Lp(a).</p><h3 class=\"art-h\">Qué probar esta semana</h3><ul class=\"art-ul\"><li>Empezar un diario en VIA-L: primer día de la regla, sueño, sofocos, ánimo.</li><li>Anotar qué puntos de la lista «importante descartar» van contigo.</li><li>Preparar para tu médico una lista de los análisis que quieres comentar.</li></ul><!--EV--><p class=\"art-p art-note\"><i>Esto es información general, no una prescripción. Qué análisis hacer lo decide un médico.</i></p>","codes":["P-F3","P-F6","P-F13","P-F22"]},"hf":{"t":"Sofocos: por qué aparecen y qué ayuda de verdad","min":"4 minutos de lectura","h":"<p class=\"art-p\">El calor te sube a la cara y al cuello, rompes a sudar y luego quizá tengas escalofríos. Por la noche lo mismo te despierta, y por la mañana parece que no has dormido nada. Los sofocos son una de las señales más frecuentes de la perimenopausia y la menopausia. La buena noticia: se sabe mucho de ellos, y algunos consejos habituales funcionan y otros no. Veamos cuáles son cuáles.</p><h3 class=\"art-h\">Por qué el cuerpo se sobrecalienta de repente</h3><p class=\"art-p\">Todos tenemos una «zona de confort térmico»: un margen en el que el cuerpo no intenta ni enfriarse ni calentarse. Cuando en la transición baja el estrógeno, esa zona se estrecha. Ahora basta una subida de temperatura muy pequeña para que el cuerpo decida que tiene que enfriarse con urgencia: los vasos se dilatan, la piel se enrojece, aparece el sudor.</p><p class=\"art-p\">Junto con los sofocos suelen venir los sudores nocturnos, el sueño entrecortado, la sequedad, el dolor de articulaciones y la «niebla mental». Es un solo cuadro, no un conjunto de problemas separados. Si llevas un anillo o un reloj, por la noche a menudo se ven saltos bruscos de la temperatura de la piel junto con los despertares.</p><h3 class=\"art-h\">Por qué la noche es lo peor</h3><p class=\"art-p\">La mayoría de los sofocos nocturnos coincide con un despertar. La noche se rompe en trozos, y por la mañana no hay energía, el ánimo está peor y apetece más lo dulce. Por eso todo lo que reduce los despertares nocturnos ayuda no solo con los sofocos, sino con todo el día.</p><h3 class=\"art-h\">Qué ayuda, según la fuerza de la evidencia</h3><p class=\"art-p\"><b>Entrenamiento de fuerza dos veces por semana.</b> Es la palanca más fuerte sin medicamentos. En el mejor estudio, los sofocos se redujeron aproximadamente a la mitad, y el ánimo mejoró incluso antes de que cambiaran la fuerza y el peso. Conviene empezar por aquí, no dejarlo «para más tarde».</p><p class=\"art-p\"><b>Terapia cognitivo-conductual e hipnosis clínica.</b> Son los únicos métodos sin medicamentos con una evidencia sólida específicamente para los sofocos. Tras la TCC, los sofocos molestan menos e interfieren menos en la vida; la hipnosis también reduce su frecuencia. Hay formatos en grupo, en línea y con libros; los dirige un psicólogo o psicoterapeuta con esa experiencia.</p><p class=\"art-p\"><b>Un dormitorio fresco y oscuro.</b> Alrededor de 16–19 °C, tejidos transpirables, ropa y ropa de cama por capas para quitarte algo fácilmente por la noche. Siendo sinceros: enfriar no recupera la «zona de confort», pero reduce mucho los despertares y las molestias.</p><p class=\"art-p\"><b>Menos alcohol y cafeína.</b> El alcohol empeora los sofocos incluso en pequeñas cantidades y corta la segunda mitad de la noche. Café y té fuerte, antes de las 14:00.</p><h3 class=\"art-h\">Lo que no ayuda con los sofocos, aunque se recomiende a menudo</h3><ul class=\"art-ul\"><li><b>Las prácticas de respiración, el yoga y la meditación</b> no reducen los sofocos más que un placebo. Pero ayudan a la calma y al sueño, y por eso vale la pena hacerlos.</li><li><b>La soja, el tofu y la linaza molida</b> no redujeron los sofocos en los estudios. Como alimento están bien —proteína y fibra—, pero no como «remedio para los sofocos».</li><li><b>Las plantas</b> —cimicífuga, trébol rojo, dong quai, sauzgatillo— no son mejores que un placebo para los sofocos en estudios de calidad, y pueden interactuar con medicamentos. Si quieres probarlas, coméntalo antes con un especialista.</li><li><b>El omega-3</b> es bueno para el corazón y los vasos, pero en los estudios no ayuda con los sofocos.</li></ul><p class=\"art-p\">Ningún suplemento sin receta tiene una evidencia convincente para los sofocos.</p><h3 class=\"art-h\">Cuándo ir al médico</h3><p class=\"art-p\">Si los sofocos te despiertan a menudo por la noche o te impiden trabajar y vivir, es motivo para ir al médico, no para aguantar. Lo más eficaz aquí es con receta: hay opciones hormonales y no hormonales. Es una opción plenamente válida, no un «fracaso del camino natural»; la alimentación y los hábitos siguen siendo un apoyo, no un sustituto.</p><p class=\"art-p\">Y otra razón para contarle a tu médico lo de los sofocos: los sofocos y sudores nocturnos intensos y duraderos no son solo una molestia. Los médicos los tienen en cuenta al valorar el corazón y los vasos, y después de la menopausia esto es especialmente importante.</p><h3 class=\"art-h\">Qué probar esta semana</h3><ul class=\"art-ul\"><li>Dormitorio fresco y oscuro; ropa de cama y pijama de tejidos transpirables, por capas.</li><li>Dos sesiones de fuerza de 30–40 minutos en días distintos; la base son sentadillas, tirones y empujes, sin dolor.</li><li>Café y té fuerte solo antes de las 14:00; por la noche, sin alcohol.</li></ul><p class=\"art-p\">Anota tus sofocos cada día en VIA-L: en dos o tres semanas verás qué funciona en tu caso.</p><!--EV--><p class=\"art-p art-note\"><i>Esto es información general, no una prescripción. La dosis y la pauta de tratamiento las decide un médico.</i></p>","codes":["P-F1","P-F17","P-F13"]},"sleep":{"t":"Por qué empeora el sueño después de los 40 y qué hacer","min":"5 minutos de lectura","h":"<p class=\"art-p\">Antes te dormías en diez minutos y ahora pasas una hora despierta. O te duermes con facilidad, pero a las tres de la madrugada tienes los ojos abiertos y los pensamientos no te dejan volver a dormir. El sueño es una de las primeras cosas que cambian en la transición. Y una de las más agradecidas: aquí los hábitos funcionan mejor que las pastillas.</p><h3 class=\"art-h\">Qué cambia de verdad</h3><p class=\"art-p\">Siendo sinceros: parte del empeoramiento del sueño con los años es simplemente la edad. Pero la transición tiene sus propias señales.</p><p class=\"art-p\"><b>Cuesta más dormirse.</b> La progesterona alimenta el «calmante» natural del cerebro. Cuando hay menos, conciliar el sueño se hace más difícil.</p><p class=\"art-p\"><b>La mente no se apaga.</b> Por la noche es como si alguien mantuviera el dedo en el botón: los pensamientos dan vueltas, el cuerpo está cansado, pero el sueño no llega. Esto pasa incluso sin sofocos.</p><p class=\"art-p\"><b>Los sofocos rompen la noche.</b> La mayoría de los sofocos nocturnos coincide con un despertar.</p><p class=\"art-p\"><b>La noche no suelta.</b> Un ritmo diario del estrés alterado no deja que el cuerpo «desconecte» al llegar la noche; de ahí los despertares a las 3–4 de la madrugada.</p><p class=\"art-p\">Si llevas un anillo o un reloj: el sueño total, el tiempo en dormirte y el número de despertares los muestran de forma fiable. El sueño «profundo» y el «REM», en cambio, son aproximados; tómalos como una pista, no como un hecho.</p><h3 class=\"art-h\">Lo que mejor funciona</h3><p class=\"art-p\"><b>Un ancla para levantarte.</b> Levántate a la misma hora los siete días, fines de semana incluidos, con media hora de margen como mucho. La regularidad importa más que lo que duermes. Y 10–15 minutos de luz natural en la primera hora tras levantarte: al aire libre, incluso si está nublado.</p><p class=\"art-p\"><b>La cama, solo para dormir.</b> No te quedes en la cama sin dormir: si no te duermes en más de 15–20 minutos, levántate y vuelve cuando te entre el sueño. En la cama no trabajes ni mires el móvil, y por la noche no mires el reloj.</p><p class=\"art-p\"><b>Un dormitorio fresco y oscuro.</b> Alrededor de 16–19 °C, tejidos transpirables, ropa por capas. Esto reduce los despertares por sofocos.</p><p class=\"art-p\"><b>Una noche cálida y tenue.</b> Entre 30 y 60 minutos antes de dormir: luz cálida y suave, y sin pantallas.</p><h3 class=\"art-h\">Qué quitar: importa más que qué añadir</h3><ul class=\"art-ul\"><li><b>El alcohol por la noche.</b> Es un «falso amigo»: ayuda a dormirte, pero corta la segunda mitad de la noche y empeora los sofocos, incluso en pequeñas cantidades.</li><li><b>El café tarde.</b> Café y té fuerte, solo antes de las 14:00.</li><li><b>La cena tardía.</b> La última comida copiosa, tres horas antes de acostarte.</li></ul><p class=\"art-p\">Moverte durante el día ayuda al sueño, pero el alcohol de la noche borra ese beneficio.</p><h3 class=\"art-h\">¿Y los suplementos?</h3><p class=\"art-p\">Su efecto es modesto. El <b>magnesio</b> por la noche tiene un respaldo débil; tiene sentido si tomas poco con la comida (pipas de calabaza, verduras de hoja, legumbres). La <b>melatonina</b> ayuda sobre todo a quienes ya tienen el sueño alterado y depende de la hora en que se toma: coméntalo con un especialista. La valeriana no está respaldada por la evidencia, y no recomendamos adaptógenos como la ashwagandha: tienen riesgos para el hígado y la tiroides.</p><h3 class=\"art-h\">Cuándo ir al médico</h3><ul class=\"art-ul\"><li>Ronquidos con pausas o sensación de ahogo durante el sueño, sueño que no descansa pese a dormir suficientes horas, quedarte dormida de día, sobre todo al volante. Después de la menopausia, los problemas de respiración durante el sueño son frecuentes y a menudo pasan desapercibidos.</li><li>Por la noche sientes una necesidad irresistible de mover las piernas que se alivia al moverte: conviene revisar tus reservas de hierro (ferritina).</li><li>Mal sueño durante más de tres meses pese a todo lo anterior.</li><li>Sofocos intensos te rompen la noche: tratarlos mejora también el sueño.</li></ul><h3 class=\"art-h\">Qué probar esta semana</h3><ul class=\"art-ul\"><li>Levantarte a la misma hora los siete días.</li><li>No quedarte en la cama sin dormir: si no te duermes, levántate y vuelve cuando te entre el sueño.</li><li>Café antes de las 14:00, noche sin alcohol.</li></ul><!--EV--><p class=\"art-p art-note\"><i>Esto es información general, no una prescripción. Las pruebas y el tratamiento los decide un médico.</i></p>","codes":["P-F17","P-F3","P-F4"]},"energy":{"t":"De dónde viene el cansancio después de los 40 y cómo recuperar la energía","min":"5 minutos de lectura","h":"<p class=\"art-p\">Parece que duermes, parece que comes como siempre, y sin embargo no tienes energía desde primera hora. A mediodía quieres tumbarte; por la noche no te apetece nada. Lo primero que se piensa es «me faltan vitaminas». Pero casi siempre el problema no está ahí.</p><h3 class=\"art-h\">Qué suele haber detrás del cansancio</h3><p class=\"art-p\">La bajada del estrógeno sí afecta a la resistencia. Pero el cansancio a esta edad viene mucho más a menudo de otras cosas, y casi todas se pueden comprobar y corregir:</p><ul class=\"art-ul\"><li><b>El sueño.</b> Las noches rotas se acumulan, y ningún café lo compensa.</li><li><b>Las reservas de hierro.</b> Las reglas abundantes de la transición agotan las reservas, y el cansancio aparece mucho antes de que cambie un análisis de sangre habitual.</li><li><b>La tiroides.</b> Lo que la distingue es tener frío; en la menopausia suele ser al revés, se tiene calor.</li><li><b>El ánimo.</b> Cuando nada te alegra desde hace más de dos semanas, no es «solo cansancio».</li></ul><p class=\"art-p\">Por eso hay que empezar no por los botes «para la energía», sino por comprobar.</p><h3 class=\"art-h\">Señales que piden un análisis, no «aguantar»</h3><ul class=\"art-ul\"><li><b>Hierro:</b> reglas abundantes, falta de aire o palpitaciones al subir escaleras, caída del pelo, palidez, ganas de masticar hielo, piernas inquietas por la noche → ferritina y hemograma.</li><li><b>Tiroides:</b> frío, estreñimiento, pulso lento, piel seca, párpados hinchados, ronquera → TSH.</li><li><b>Vitamina B12:</b> entumecimiento u hormigueo en manos y pies, piernas «de algodón»; el riesgo es mayor con metformina, con medicamentos para el ardor de estómago y en veganas → análisis de B12.</li><li><b>Respiración durante el sueño:</b> el sueño no descansa pese a dormir suficientes horas, ronquidos con pausas → al especialista en sueño.</li></ul><p class=\"art-p\">⚠️ Un caso aparte: si después de un esfuerzo al día siguiente te sientes mucho peor —durante horas o un día entero—, no aumentes la carga a la fuerza. Consúltalo con un médico.</p><h3 class=\"art-h\">Qué te devuelve la energía</h3><p class=\"art-p\"><b>El movimiento.</b> La palanca de energía más fuerte que se conoce. Funciona mejor la combinación: entrenamiento de fuerza, tramos cortos e intensos con descanso completo entre ellos y cardio suave. Lo peor es «todo el tiempo a intensidad media-alta». La buena noticia: en los primeros años tras la menopausia el cuerpo responde especialmente bien al entrenamiento.</p><p class=\"art-p\"><b>Proteína por la mañana.</b> Un desayuno con proteína en la primera hora o dos tras levantarte. Saltarse el desayuno y los picos de azúcar disparan por sí mismos las hormonas del estrés, y durante el día llega el bajón.</p><p class=\"art-p\"><b>Caminar después de comer.</b> 10–15 minutos después de las comidas principales suavizan la «montaña rusa del azúcar» y la somnolencia de después de comer.</p><p class=\"art-p\"><b>Un ancla para el sueño.</b> Levantarte a la misma hora los siete días y luz natural por la mañana. A veces lo más sencillo es acostarte media hora antes.</p><h3 class=\"art-h\">Qué quitar</h3><p class=\"art-p\">El alcohol, los dulces refinados y los ultraprocesados, la falta crónica de sueño, los entrenamientos intensos sin recuperación: quitar estas «fugas de energía» importa más que añadir algo.</p><h3 class=\"art-h\">¿Y los suplementos?</h3><p class=\"art-p\">La comida y el movimiento son más fuertes que cualquiera de ellos. El <b>hierro</b>, solo según el análisis de ferritina, no a ciegas. La <b>vitamina D</b> se puede tomar incluso sin análisis. El magnesio y las vitaminas del grupo B aportan energía solo si te faltan. Los «potenciadores de juventud» de moda (NMN, NR y similares) no mejoraron la energía en estudios en personas: no los recomendamos.</p><h3 class=\"art-h\">Cuándo ir al médico</h3><ul class=\"art-ul\"><li>Cansancio durante más de cuatro semanas pese al sueño y al movimiento.</li><li>Cansancio junto con pérdida de peso sin explicación, sudores nocturnos intensos o ganglios inflamados.</li><li>Falta de aire, dolor en el pecho o palpitaciones: urgente.</li></ul><h3 class=\"art-h\">Qué probar esta semana</h3><ul class=\"art-ul\"><li>Una fuente de proteína en cada comida, empezando por el desayuno.</li><li>10–15 minutos de paseo después de las comidas principales.</li><li>Dos sesiones de fuerza de 30–40 minutos en días distintos.</li></ul><!--EV--><p class=\"art-p art-note\"><i>Esto es información general, no una prescripción. Las pruebas y el tratamiento los decide un médico.</i></p>","codes":["P-F5","P-F22","P-F4","P-F17"]},"mood":{"t":"Cambios de humor, ansiedad e irritabilidad: qué está pasando","min":"5 minutos de lectura","h":"<p class=\"art-p\">«No me reconozco». Saltas por cualquier cosa, lloras sin motivo, la ansiedad aparece de la nada, y lo que antes te alegraba ahora te deja indiferente. No es que tu carácter haya empeorado. En la transición esto les pasa a muchísimas mujeres, y tiene una explicación.</p><h3 class=\"art-h\">Por qué oscila</h3><p class=\"art-p\">El estrógeno sostiene las sustancias del cerebro responsables del ánimo y del placer. En la perimenopausia no solo baja: oscila, y es la amplitud de esas oscilaciones la que altera el ánimo. Además baja la progesterona, y con ella el «calmante» natural del cerebro. De ahí la ansiedad, la irritabilidad, los arrebatos de ira, las lágrimas y la sensación de que cuesta más soportar la presión.</p><p class=\"art-p\">La irritabilidad y la ira suelen ser más intensas que la tristeza. Es un cuadro hormonal, no «mal carácter».</p><p class=\"art-p\">Y algo importante para no asustarte: en la mayoría de las mujeres es una reacción pasajera. Suele alcanzar su punto máximo en la perimenopausia y después se calma. Deben estar más atentas quienes ya han pasado antes por épocas de bajón intenso.</p><h3 class=\"art-h\">Cómo saber qué está pasando exactamente</h3><p class=\"art-p\">La clave está en <b>cuándo</b> te sientes mal:</p><ul class=\"art-ul\"><li><b>solo en la última semana antes de la regla</b>, y se pasa en los primeros días después de que empiece;</li><li><b>todo el mes</b>, pero peor antes de la regla;</li><li><b>todo el mes</b>, sin relación con el ciclo.</li></ul><p class=\"art-p\">De eso depende qué te ayudará. Y solo se puede distinguir con un diario de al menos dos ciclos: la memoria, a posteriori, se lo atribuye todo al «antes de la regla». Anota tu ánimo y el primer día de la regla en VIA-L: en un par de meses se verá el patrón.</p><h3 class=\"art-h\">Qué ayuda</h3><p class=\"art-p\"><b>El sueño.</b> El sueño roto y el cansancio acumulado intensifican los altibajos hormonales del ánimo. Si tu sueño está roto, empieza por ahí.</p><p class=\"art-p\"><b>El movimiento.</b> La palanca mejor demostrada, para muchas comparable en fuerza a un medicamento. Unos 150 minutos a la semana: caminar, fuerza; y las prácticas suaves como el yoga y el taichí son las que más alivian la ansiedad. La fuerza ayuda especialmente a las mujeres.</p><p class=\"art-p\"><b>La luz de la mañana.</b> La luz natural intensa justo al levantarte mejora claramente el ánimo en la perimenopausia. Un paseo con luz de día es un paso sencillo de cada día.</p><p class=\"art-p\"><b>La respiración lenta.</b> 5–10 minutos al día alargando la espiración: unas seis respiraciones por minuto. Actúa directamente sobre la ansiedad, sin necesidad de «fuerza de voluntad».</p><p class=\"art-p\"><b>La comida.</b> Estilo mediterráneo, fibra, alimentos fermentados, desayuno con proteína. El magnesio es mejor tomarlo de la comida —verduras de hoja oscura, pipas de calabaza, legumbres—; un suplemento tiene sentido si tu dieta aporta poco.</p><h3 class=\"art-h\">Qué quitar</h3><ul class=\"art-ul\"><li><b>El alcohol.</b> Calma durante una hora y luego la ansiedad vuelve más fuerte, sobre todo en la perimenopausia.</li><li><b>Mucho café.</b> La cafeína dispara la ansiedad y empeora los sofocos: solo antes del mediodía.</li><li><b>Las «fórmulas antiestrés» con vitamina B6</b> no son seguras si se toman mucho tiempo.</li></ul><h3 class=\"art-h\">Qué puede ofrecerte el médico</h3><p class=\"art-p\">Si el bajón o la ansiedad te impiden vivir con normalidad, la base de la ayuda es la psicoterapia (incluidos programas específicos para la menopausia) y, si hace falta, medicación. En la perimenopausia, sobre todo junto con sofocos, la terapia hormonal también puede ayudar al ánimo: eso lo decide el médico.</p><h3 class=\"art-h\">Cuándo pedir ayuda enseguida</h3><ul class=\"art-ul\"><li>Cualquier pensamiento de hacerte daño, o de que «sería mejor no vivir»: acude de inmediato a un especialista o llama a una línea de ayuda en crisis. No es algo que se pueda esperar a que pase.</li><li>Bajón o pérdida de interés casi a diario durante más de dos semanas, o ansiedad que te impide vivir y trabajar: al médico en los próximos días.</li><li>Duermes mucho menos pero tienes mucha energía, hablas más deprisa, te apetecen gastos y decisiones impulsivas: al médico.</li></ul><h3 class=\"art-h\">Qué probar esta semana</h3><ul class=\"art-ul\"><li>Un paseo con luz de día en la primera hora tras levantarte.</li><li>Levantarte a la misma hora los siete días.</li><li>Anotar en VIA-L tu ánimo y el primer día de la regla.</li></ul><!--EV--><p class=\"art-p art-note\"><i>Esto es información general, no una prescripción. Las pruebas y el tratamiento los decide un médico.</i></p>","codes":["P-F9","P-F4","P-F17"]},"fog":{"t":"«Niebla mental»: se me olvidan las palabras, pierdo el hilo — ¿qué me pasa?","min":"4 minutos de lectura","h":"<p class=\"art-p\">Entras en una habitación y no recuerdas a qué. El nombre de alguien conocido lo tienes «en la punta de la lengua». Una idea se te escapa a mitad de frase. Muchas mujeres en la transición se asustan: «¿Será que la memoria empieza a fallar?». Veámoslo con calma.</p><h3 class=\"art-h\">Es real, y se pasa</h3><p class=\"art-p\">El estrógeno nutre el cerebro: las zonas responsables de la memoria y el lenguaje, y la forma en que el cerebro obtiene energía. Por eso la «niebla» en la transición no es imaginación. Lo que más suele afectar es encontrar las palabras, la rapidez y recordar lo que oyes.</p><p class=\"art-p\">Pero esto es lo importante:</p><ul class=\"art-ul\"><li>según los grandes estudios, esta niebla es <b>leve</b> y suele <b>pasar</b> después de la menopausia;</li><li><b>no es el inicio de una enfermedad de la memoria</b>: a esta edad esas enfermedades son muy raras;</li><li>la sensación de niebla suele ser <b>más fuerte</b> que lo que muestran las pruebas.</li></ul><h3 class=\"art-h\">Lo que más agrava la niebla</h3><p class=\"art-p\"><b>La ansiedad y el ánimo.</b> El simple pensamiento «¿me estaré volviendo loca?» empeora la concentración, y el círculo se cierra. A menudo la niebla viene de la ansiedad, no de una «memoria débil».</p><p class=\"art-p\"><b>La falta de sueño.</b> Las noches rotas golpean la atención más de lo que parece.</p><p class=\"art-p\"><b>La sobrecarga.</b> Diez cosas a la vez, y el cerebro pierde el hilo. Una tarea cada vez: un truco sencillo que funciona.</p><h3 class=\"art-h\">Qué conviene revisar</h3><p class=\"art-p\">No todo hay que achacarlo a la menopausia. Con estas señales, al médico para revisarlo:</p><ul class=\"art-ul\"><li><b>Tiroides</b> — frío, estreñimiento, pulso lento → TSH.</li><li><b>Vitamina B12</b> — entumecimiento u hormigueo en manos y pies; el riesgo es mayor con metformina, con medicamentos para el ardor de estómago y en veganas.</li><li><b>Reservas de hierro</b> — si tus reglas son abundantes → ferritina.</li><li><b>Respiración durante el sueño</b> — el sueño no descansa, roncas.</li><li><b>Medicamentos.</b> Algunos antihistamínicos «para dormir», los somníferos y los fármacos para las ganas frecuentes de orinar embotan la memoria y la atención. No los dejes por tu cuenta: habla con tu médico de una alternativa.</li><li><b>Audición.</b> La pérdida de audición es un factor importante para el cerebro, y se puede corregir.</li></ul><h3 class=\"art-h\">Qué ayuda al cerebro</h3><p class=\"art-p\"><b>El movimiento.</b> La palanca más fuerte: tanto caminar como el entrenamiento de fuerza mejoran la atención y la capacidad de tener varias tareas en la cabeza.</p><p class=\"art-p\"><b>El sueño.</b> Empieza por él: la niebla viene más a menudo de la falta de sueño.</p><p class=\"art-p\"><b>La comida.</b> Estilo mediterráneo, pescado azul (pescado de verdad, no cápsulas), huevos, frutos rojos.</p><p class=\"art-p\"><b>Corazón y vasos.</b> Tensión, azúcar, cintura: lo que es bueno para el corazón es bueno para el cerebro. Menos alcohol.</p><p class=\"art-p\"><b>Gente y cosas nuevas.</b> La actividad social y mental cuida el cerebro.</p><h3 class=\"art-h\">¿Y los suplementos «para la memoria»?</h3><p class=\"art-p\">Los suplementos «para la memoria» ya preparados no han mostrado beneficio: ni el ginkgo ni los «nootrópicos» de moda. La <b>creatina</b> da en los estudios una pequeña mejora de la memoria, más notable con falta de sueño y en mayores de 65; en mujeres en la peri- y posmenopausia hay un primer estudio pequeño en el que el tiempo de reacción fue más rápido, pero el resultado aún no se ha repetido. Con enfermedad renal, solo después de hablarlo con un médico.</p><h3 class=\"art-h\">Cuándo ir al médico sin esperar</h3><p class=\"art-p\">Ya no es una niebla normal si:</p><ul class=\"art-ul\"><li>te cuesta manejar lo de siempre: el dinero, los medicamentos, orientarte en lugares conocidos;</li><li>las personas cercanas notan el empeoramiento más que tú;</li><li>va a peor mes tras mes, sin «días buenos»;</li><li>repites la misma pregunta sin darte cuenta o confundes el significado de las palabras.</li></ul><h3 class=\"art-h\">Qué probar esta semana</h3><ul class=\"art-ul\"><li>Levantarte a la misma hora los siete días: primero el sueño.</li><li>Dos sesiones de fuerza de 30–40 minutos en días distintos.</li><li>Una tarea cada vez: las cosas importantes, de una en una, sin saltar de una a otra.</li></ul><!--EV--><p class=\"art-p art-note\"><i>Esto es información general, no una prescripción. Las pruebas y el tratamiento los decide un médico.</i></p>","codes":["P-F10","P-F9","P-F17"]},"weight":{"t":"Por qué crece la cintura aunque el peso apenas cambie","min":"5 minutos de lectura","h":"<p class=\"art-p\">Comes como antes, pero los vaqueros no abrochan. La báscula marca casi lo mismo, pero la barriga es otra. Les pasa a muchas mujeres en la transición. Y no es «falta de voluntad»: el cuerpo tiene aquí su propia lógica.</p><h3 class=\"art-h\">Qué está pasando</h3><p class=\"art-p\">Cuando baja el estrógeno, el cuerpo responde peor al azúcar, y la grasa empieza a acumularse no en las caderas, sino alrededor de la cintura: en la transición, aproximadamente un 6% más cada año. De ahí tres cosas que parecen separadas pero en realidad son una misma cadena:</p><ul class=\"art-ul\"><li>antojos de dulce y bajones de energía después de comer;</li><li>«niebla» después de comer;</li><li>la cintura que crece con el mismo peso.</li></ul><p class=\"art-p\">El bajón después de comer y los antojos de dulce son la reacción del cuerpo a una subida y bajada del azúcar, no una cuestión de carácter.</p><h3 class=\"art-h\">Mide la cintura, no el peso</h3><p class=\"art-p\">En la transición el peso puede apenas cambiar mientras la grasa alrededor de la cintura aumenta. Por eso la báscula dice poco. La referencia casera más fiable es <b>una cintura menor que la mitad de tu altura</b>: por ejemplo, con 166 cm de altura, menos de 83 cm. Una cintura de unos 88 cm es una señal para prestar atención (en complexión asiática, unos 80 cm). Es una referencia, no un veredicto.</p><h3 class=\"art-h\">Lo que más influye</h3><p class=\"art-p\"><b>Dormir poco.</b> Incluso una o dos horas menos de sueño empeoran claramente cómo el cuerpo maneja el azúcar, sobre todo en las mujeres en la menopausia. El sueño es una palanca del metabolismo, no solo descanso.</p><p class=\"art-p\"><b>Poco trabajo muscular.</b> El músculo es el principal «consumidor» de azúcar. Cuanto menos músculo, más le cuesta al cuerpo.</p><p class=\"art-p\"><b>Los picos de azúcar después de comer.</b> Se pueden suavizar bastante, con el orden de la comida y con movimiento.</p><h3 class=\"art-h\">Qué hacer</h3><p class=\"art-p\"><b>Verduras y proteína antes que los carbohidratos.</b> Empieza la comida con verduras y proteína, y el pan, los cereales o el dulce, después. Esto suaviza el pico de azúcar aproximadamente en un tercio.</p><p class=\"art-p\"><b>Caminar después de comer.</b> 10–15 minutos justo después de comer son una vía aparte por la que los músculos captan el azúcar. Funciona junto con el orden de la comida.</p><p class=\"art-p\"><b>Entrenamiento de fuerza.</b> La palanca principal en la menopausia: el músculo capta el azúcar y no se deja perder con la edad.</p><p class=\"art-p\"><b>Proteína en cada comida y fibra.</b> La proteína sacia y mantiene el músculo; la fibra de verduras, legumbres y cereales integrales suaviza el azúcar.</p><p class=\"art-p\"><b>Cenar pronto.</b> Por la noche el azúcar se mantiene más alto, así que es mejor hacer la comida principal antes. Pero los ayunos estrictos no les sientan bien a las mujeres en la transición.</p><p class=\"art-p\"><b>Menos azúcar refinado, menos bebidas azucaradas y menos alcohol.</b></p><h3 class=\"art-h\">Sobre el hígado</h3><p class=\"art-p\">Un acompañante silencioso frecuente de la cintura que crece es la grasa en el hígado. Normalmente no da síntomas, y los análisis hepáticos habituales pueden salir bien. No hacen falta «limpiezas» ni «détox»: funcionan los mismos pasos: cintura, comida natural, fuerza, menos azúcar y alcohol. Un médico puede valorar el riesgo.</p><h3 class=\"art-h\">¿Y los suplementos para adelgazar?</h3><p class=\"art-p\">Los suplementos «para adelgazar» no tienen respaldo, y las mezclas con extracto de té verde pueden dañar el hígado. Lo que funciona es la proteína en cada comida y la fibra de los alimentos.</p><h3 class=\"art-h\">Cuándo ir al médico</h3><p class=\"art-p\">Mucha sed, orinar a menudo, pérdida de peso brusca sin motivo, episodios de mareo: son motivos para ir al médico y revisar el azúcar.</p><h3 class=\"art-h\">Qué probar esta semana</h3><ul class=\"art-ul\"><li>Empezar las comidas con verduras y proteína, y los carbohidratos, después.</li><li>10–15 minutos de paseo después de las comidas principales.</li><li>Una sesión de fuerza esta semana, o mejor, dos.</li></ul><!--EV--><p class=\"art-p art-note\"><i>Esto es información general, no una prescripción. Las pruebas y el tratamiento los decide un médico.</i></p>","codes":["P-F7","P-F1","P-F8"]},"pain":{"t":"Duelen las articulaciones y por la mañana hay rigidez: qué es y cómo ayudar al cuerpo","min":"5 minutos de lectura","h":"<p class=\"art-p\">Te levantas por la mañana y el cuerpo parece de madera. Te duelen las rodillas, los dedos, los hombros, aunque no ha pasado nada. A menudo se achaca a «la edad». Pero este dolor en la transición tiene una causa clara, y pasos claros.</p><h3 class=\"art-h\">Por qué duele</h3><p class=\"art-p\">El estrógeno actúa en todo el aparato locomotor: en huesos, articulaciones, ligamentos y músculos. Cuando hay menos, se nota en todas partes a la vez. El dolor y la rigidez en las articulaciones <b>sin hinchazón</b> afectan a más de la mitad de las mujeres en la transición. Es parte de la transición, no «solo la edad».</p><p class=\"art-p\">Además, la bajada del estrógeno quita el «freno» natural de la inflamación de fondo; por eso articulaciones, sueño, cansancio y ánimo a menudo se arrastran unos a otros.</p><p class=\"art-p\">Otra historia frecuente entre los 50 y los 60 es el «hombro congelado»: cuesta levantar el brazo tanto sola como con ayuda de otra persona. Para esto, al fisioterapeuta o al traumatólogo.</p><h3 class=\"art-h\">¿Reposar o moverse?</h3><p class=\"art-p\">Moverse. El entrenamiento de fuerza y el movimiento regular son la base para articulaciones, músculos y huesos.</p><h3 class=\"art-h\">Qué ayuda</h3><p class=\"art-p\"><b>Entrenamiento de fuerza 2–3 veces por semana, sin dolor.</b> Es la base tanto para las articulaciones como para los músculos y los huesos. Lo mejor es combinar fuerza con caminar u otro cardio. Con un entrenador, la protección de los huesos es claramente mayor, y con supervisión incluso la fuerza intensa es segura.</p><p class=\"art-p\"><b>Un poco de saltos e impacto</b>, si las articulaciones lo permiten. Es precisamente este tipo de carga el que mejor sostiene los huesos de la cadera y la columna.</p><p class=\"art-p\"><b>Equilibrio y movilidad.</b> Los ejercicios de equilibrio previenen caídas y, por tanto, fracturas.</p><p class=\"art-p\"><b>Proteína en cada comida.</b> Después de los 40, el músculo responde peor a la proteína y al ejercicio: hace falta más de ambos.</p><p class=\"art-p\"><b>Estilo mediterráneo.</b> El pescado azul, el aceite de oliva, los frutos rojos, las verduras y los cereales integrales reducen la inflamación de fondo; la carne procesada, las bebidas azucaradas y los ultraprocesados la aumentan.</p><h3 class=\"art-h\">Sobre los huesos: lo que no duele</h3><p class=\"art-p\">El hueso se pierde más rápido desde aproximadamente un año antes de la última regla hasta dos años después, y no hay síntomas hasta que llega una fractura. Señales indirectas: has perdido más de 4 cm de altura respecto a tu juventud, has empezado a encorvarte, tienes menos fuerza al agarrar. Si hay factores de riesgo —menopausia antes de los 45, fractura por un golpe leve, corticoides durante mucho tiempo, fractura de cadera en tu padre o tu madre—, conviene hablar ya con tu médico de una densitometría. Si el riesgo es alto, los médicos tienen tratamientos que reducen claramente el riesgo de fracturas.</p><h3 class=\"art-h\">¿Y los suplementos?</h3><ul class=\"art-ul\"><li><b>Calcio</b>: mejor con la comida: yogur, queso, sardinas con espinas, tofu. El calcio de los alimentos es seguro, mientras que las dosis altas de suplementos son discutidas.</li><li><b>Vitamina D</b>: se puede tomar incluso sin análisis.</li><li><b>Colágeno</b>: no ayuda a los músculos.</li></ul><h3 class=\"art-h\">Cuándo ir al médico sin esperar</h3><ul class=\"art-ul\"><li>Una articulación está hinchada, caliente o enrojecida; duelen de forma simétrica las pequeñas articulaciones de las manos; la rigidez matutina dura más de media hora o una hora y mejora con el movimiento: al reumatólogo, aquí es importante no perder los primeros meses.</li><li>Dolor de espalda repentino por un movimiento normal —toser, darte la vuelta en la cama— junto con pérdida de altura.</li><li>Cualquier fractura por un golpe leve.</li><li>Dolor de espalda que te despierta por la noche, junto con fiebre o pérdida de peso sin explicación.</li><li>Entumecimiento en la zona genital, debilidad en ambas piernas, problemas para orinar: urgente.</li></ul><h3 class=\"art-h\">Qué probar esta semana</h3><ul class=\"art-ul\"><li>Dos sesiones de fuerza de 30–40 minutos en días distintos; la base son sentadillas, tirones y empujes, sin dolor.</li><li>Una fuente de proteína en cada comida.</li><li>Calcio con la comida: yogur, queso, sardinas con espinas o tofu cada día.</li></ul><!--EV--><p class=\"art-p art-note\"><i>Esto es información general, no una prescripción. Las pruebas y el tratamiento los decide un médico.</i></p>","codes":["P-F12","P-F8"]},"muscle":{"t":"Los músculos después de los 40: por qué se debilitan y cómo conservarlos","min":"4 minutos de lectura","h":"<p class=\"art-p\">Cuesta más levantar una bolsa, cuesta más levantarse de un sofá bajo, y subir escaleras te deja sin aliento. Con la edad el músculo se va perdiendo sin que lo notes, y en la transición este proceso se acelera. La buena noticia: el músculo responde a cualquier edad, y recuperar la fuerza es posible.</p><h3 class=\"art-h\">Qué está pasando</h3><p class=\"art-p\">El estrógeno ayuda a los músculos, y cuando hay menos, el músculo responde peor tanto a la proteína como al ejercicio. Dicho de forma sencilla, después de los 40 hace falta <b>más</b> de ambos para conseguir el mismo resultado.</p><p class=\"art-p\">Por qué esto importa más allá de la figura:</p><ul class=\"art-ul\"><li>el músculo es el principal «consumidor» de azúcar, y cuanto más tienes, más fácil lo tiene el metabolismo;</li><li>el músculo es una «fábrica de energía»: con él te cansas menos;</li><li>la debilidad lleva a caídas, y las caídas, a fracturas.</li></ul><h3 class=\"art-h\">Qué funciona</h3><p class=\"art-p\"><b>Entrenamiento de fuerza 2–3 veces por semana.</b> Es lo principal. La base son sentadillas, tirones y empujes, sin dolor. La carga tiene que notarse: las últimas repeticiones cuestan esfuerzo. Con un entrenador, el resultado y la seguridad son mayores.</p><p class=\"art-p\"><b>Proteína: más de lo que crees.</b> La referencia es 30–40 g de proteína en cada comida, empezando por el desayuno: normalmente es donde menos hay. Por ejemplo, una ración de requesón o yogur griego con huevos, un trozo de pescado o pollo, un plato de lentejas con tofu. En total al día, conviene llegar al menos a 1–1,2 g de proteína por kilo de peso, y más si haces fuerza.</p><p class=\"art-p\"><b>Movimiento cada día.</b> Caminar, escaleras, tareas de casa: además de la fuerza, no en su lugar.</p><p class=\"art-p\"><b>Equilibrio.</b> Los ejercicios de equilibrio protegen de las caídas.</p><h3 class=\"art-h\">¿Y los suplementos?</h3><ul class=\"art-ul\"><li><b>La proteína en polvo</b> es práctica si con la comida no llegas a la proteína necesaria. Es comida, no un medicamento.</li><li><b>La creatina</b> está mejor estudiada junto con el entrenamiento de fuerza: un aumento pequeño pero real de fuerza y músculo, también en mujeres posmenopáusicas. Sin entrenamiento, los datos son contradictorios. Con enfermedad renal, solo después de hablarlo con un médico. La creatinina en los análisis sube un poco mientras se toma: no es daño renal.</li><li><b>El colágeno</b> no ayuda a los músculos.</li></ul><h3 class=\"art-h\">Cuándo ir al médico</h3><ul class=\"art-ul\"><li>La debilidad aumenta rápido, sin una causa clara.</li><li>Has tenido una caída o una fractura por un golpe leve.</li><li>Te cuesta levantarte de la silla sin apoyar las manos, cuando antes podías.</li></ul><h3 class=\"art-h\">Qué probar esta semana</h3><ul class=\"art-ul\"><li>Dos sesiones de fuerza de 30–40 minutos en días distintos.</li><li>Una fuente de proteína en cada comida: empieza por el desayuno.</li><li>Cada día, al menos una vez, las escaleras en lugar del ascensor.</li></ul><!--EV--><p class=\"art-p art-note\"><i>Esto es información general, no una prescripción. Las pruebas y el tratamiento los decide un médico.</i></p>","codes":["P-F12","P-F5"]},"libido_f":{"t":"El deseo y la intimidad en la transición: qué cambia y cómo recuperar el bienestar","min":"5 minutos de lectura","h":"<p class=\"art-p\">El deseo llega con menos frecuencia, las relaciones a veces resultan desagradables o dolorosas, y da apuro hablarlo incluso con el médico. No estás sola: es uno de los cambios más frecuentes de la transición, y de los que mejor se pueden resolver.</p><h3 class=\"art-h\">Qué cambia en el deseo</h3><p class=\"art-p\">En la transición a menudo desaparece el deseo <b>espontáneo</b>, el que surge «solo». No es una avería. En muchas mujeres el deseo es <b>reactivo</b>: llega ya durante la intimidad, no antes, y es una forma sana de deseo.</p><p class=\"art-p\">En el deseo influyen más cosas que las hormonas. Lo que más lo frena es:</p><ul class=\"art-ul\"><li><b>el cansancio y la falta de sueño</b>: cuando no hay energía, tampoco hay deseo;</li><li><b>el ánimo y el estrés</b>;</li><li><b>la relación</b>: lo que pasa entre las personas, no solo en el cuerpo;</li><li><b>los medicamentos</b>: por ejemplo, algunos antidepresivos reducen el deseo; si lo sospechas, coméntalo con tu médico;</li><li><b>la sequedad y las molestias</b>: de eso hablamos aparte.</li></ul><h3 class=\"art-h\">Sequedad y molestias: no hay que aguantarlas</h3><p class=\"art-p\">La sequedad, el escozor, el dolor en las relaciones, las ganas frecuentes de orinar o las cistitis repetidas afectan a la mitad de las mujeres después de la menopausia o más. Pero apenas se habla de ello: solo aproximadamente la mitad se lo cuenta al médico, y la mayoría no sabe que tiene solución.</p><p class=\"art-p\">Es importante saber que, a diferencia de los sofocos, esto <b>no se pasa solo</b> y con el tiempo tiende a empeorar. Pero responde bien a la ayuda. Y otra cosa: el dolor lleva a evitar la intimidad, y evitarla, a que baje el deseo. Quitar las molestias a menudo significa recuperar también el deseo.</p><h3 class=\"art-h\">Lo que puedes empezar ya, sin receta</h3><p class=\"art-p\"><b>El hidratante y el lubricante son cosas distintas.</b> Se confunden a menudo:</p><ul class=\"art-ul\"><li>el <b>hidratante vaginal</b> se usa con regularidad, 2–3 veces por semana, haya o no relaciones: retiene la humedad en los tejidos;</li><li>el <b>lubricante</b>, solo en el momento de la relación, para reducir el roce. De base acuosa o de silicona, sin perfume ni aditivos «de efecto calor».</li></ul><p class=\"art-p\">La regularidad importa tanto como el producto: «caro» no significa «eficaz».</p><p class=\"art-p\"><b>Los ejercicios de suelo pélvico</b> y la intimidad o estimulación regulares mantienen el flujo sanguíneo y el bienestar.</p><p class=\"art-p\"><b>Quita los irritantes:</b> jabones y geles íntimos, duchas vaginales, productos perfumados, ropa interior sintética ajustada. Bebe suficiente agua, no fumes.</p><h3 class=\"art-h\">Qué puede ofrecerte el médico</h3><p class=\"art-p\">Si el hidratante y el lubricante no bastan, conviene hablar con el ginecólogo. Hay tratamientos locales, también con dosis bajas de estrógeno: actúan en la zona, apenas pasan a la sangre y, según muchos estudios, reducen claramente tanto la sequedad como los síntomas urinarios. También hay opciones no hormonales. Cuál te conviene lo decide el médico.</p><h3 class=\"art-h\">Lo que no ayuda</h3><ul class=\"art-ul\"><li><b>Los suplementos «para la libido»</b> y «para la hidratación desde dentro»: no tienen respaldo.</li><li><b>El «rejuvenecimiento láser»</b> y los procedimientos de radiofrecuencia que tanto promocionan las clínicas: en los estudios que los compararon con un procedimiento simulado, no hubo diferencia. Son caros y no están demostrados.</li></ul><h3 class=\"art-h\">Cuándo ir al médico</h3><ul class=\"art-ul\"><li><b>Cualquier sangrado o manchado después de la menopausia</b>, aunque sea una gota, aunque sea después de una relación. Lo más frecuente es que la causa no sea grave, pero siempre hay que revisarlo.</li><li>Picor intenso, manchas blancas, grietas o pequeñas llagas que no mejoran con el hidratante: al ginecólogo.</li><li>Las cistitis se repiten, o hay fiebre con dolor en la zona lumbar.</li></ul><h3 class=\"art-h\">Qué probar esta semana</h3><ul class=\"art-ul\"><li>Primero, sueño y descanso: acostarte media hora antes al menos tres noches.</li><li>Si hay sequedad, empezar con un hidratante vaginal 2–3 veces por semana y, para las relaciones, un lubricante.</li><li>Unos minutos de ejercicios de suelo pélvico cada día.</li></ul><!--EV--><p class=\"art-p art-note\"><i>Esto es información general, no una prescripción. Las pruebas y el tratamiento los decide un médico.</i></p>","codes":["P-F15","P-F9","P-F20"]},"cycle":{"t":"El ciclo después de los 35: más abundante, más espaciado, menos predecible — qué pasa","min":"5 minutos de lectura","h":"<p class=\"art-p\">La regla viene a las tres semanas y luego desaparece dos meses. Se ha vuelto más abundante y más larga, con coágulos. La compresa no aguanta toda la noche. Entre los 35 y los 50 estos cambios son muy frecuentes: son una de las primeras señales de la transición. Pero «frecuente» no significa «aguantar».</p><h3 class=\"art-h\">Por qué cambia el ciclo</h3><p class=\"art-p\">En la transición cada vez más ciclos ocurren sin ovulación, y hay menos progesterona. El estrógeno, mientras tanto, no baja: oscila, a veces por encima de lo habitual. De ahí la falta de previsibilidad y las reglas más abundantes.</p><p class=\"art-p\">Si llevas un anillo o un reloj: la subida de la temperatura nocturna tras la ovulación la detectan a posteriori. Si en un ciclo no hubo subida, no significa «poca progesterona»: después de los 40 algunos ciclos simplemente ocurren sin ovulación.</p><h3 class=\"art-h\">Qué se considera abundante</h3><p class=\"art-p\">Las reglas abundantes a menudo se ven como «algo mío» y pasan años sin revisarse. Referencias:</p><ul class=\"art-ul\"><li>tienes que cambiar la compresa o el tampón <b>cada hora durante varias horas seguidas</b>;</li><li>coágulos más grandes que una moneda;</li><li>manchas en la ropa, necesitas «doble protección»;</li><li>reglas de más de 7 días;</li><li>el sangrado limita tu día normal.</li></ul><h3 class=\"art-h\">Reglas abundantes y hierro</h3><p class=\"art-p\">Las reglas abundantes son la causa más frecuente de falta de hierro en las mujeres. Las reservas de hierro bajan antes de que cambie un análisis de sangre habitual, y el cansancio, la falta de aire al subir escaleras, la caída del pelo, las uñas frágiles y el frío aparecen ya entonces. Pistas especiales: ganas de masticar hielo y piernas inquietas por la noche.</p><p class=\"art-p\"><b>Qué hacer:</b></p><ul class=\"art-ul\"><li><b>Pedir un análisis de ferritina</b>: es el principal indicador de las reservas. El hierro, según el análisis, no a ciegas: el exceso de hierro también es perjudicial.</li><li><b>Comida con hierro.</b> El hierro que mejor se absorbe es el de la carne, las aves, el pescado y el marisco. El vegetal —lentejas, alubias, tofu, pipas de calabaza, verduras de hoja oscura— conviene combinarlo con vitamina C en la misma comida: pimiento, cítricos, kiwi.</li><li><b>Té, café y lácteos, por separado</b> de la comida con hierro, aproximadamente una hora después: dificultan su absorción.</li></ul><p class=\"art-p\">Y lo más importante: las reglas abundantes tienen solución. El ginecólogo tiene opciones que reducen mucho la pérdida de sangre. El hierro sin tratar la causa es un parche, no una solución.</p><h3 class=\"art-h\">Registrar es la mitad del trabajo</h3><p class=\"art-p\">Anota en VIA-L el primer día de la regla. En unos ciclos se ve cómo cambia la duración del ciclo, y con eso es más fácil ir al médico. Además, el diario ayuda a entender cómo se relaciona el ciclo con el sueño, el ánimo y los sofocos.</p><h3 class=\"art-h\">Lo que no hace falta</h3><ul class=\"art-ul\"><li><b>Los kits de suplementos «por fases del ciclo»</b> son marketing: tomarlos por fases no es mejor que a diario.</li><li><b>La «rotación de semillas»</b>: no hay datos clínicos. Las semillas son buenas como alimento, pero rotarlas por días no cambia nada.</li></ul><h3 class=\"art-h\">Cuándo ir al médico sin esperar</h3><ul class=\"art-ul\"><li>Tienes que cambiar la compresa o el tampón cada hora durante varias horas seguidas.</li><li>Reglas de más de 8 días.</li><li>Sangrado entre reglas o después de una relación.</li><li>Sangrado junto con mucho cansancio, falta de aire, mareo o desmayos.</li><li><b>Cualquier sangrado después de 12 meses sin regla</b>: siempre es motivo para ir pronto al ginecólogo.</li></ul><h3 class=\"art-h\">Qué probar esta semana</h3><ul class=\"art-ul\"><li>Anotar en VIA-L el primer día de la regla.</li><li>Con reglas abundantes, comida con hierro junto con vitamina C; té y café, una hora después.</li><li>Si te has reconocido en la lista de «abundantes», pide cita con el ginecólogo y un análisis de ferritina.</li></ul><!--EV--><p class=\"art-p art-note\"><i>Esto es información general, no una prescripción. Las pruebas y el tratamiento los decide un médico.</i></p>","codes":["P-F22","P-F3","P-F1"]},"evening":{"t":"Café antes de las 14:00, noche sin alcohol, cena temprana: por qué funciona","min":"3 minutos de lectura","h":"<p class=\"art-p\">Es uno de los pasos más sencillos del «Foco de la semana», y uno de los más eficaces para el sueño. No se trata de añadir nada, sino de quitar tres cosas que estropean la noche sin que te des cuenta.</p><h3 class=\"art-h\">Por qué funciona</h3><p class=\"art-p\"><b>El café mantiene el cuerpo «encendido».</b> La cafeína sube las hormonas del estrés y no deja que bajen al llegar la tarde. Actúa durante mucho tiempo, así que una taza a las cuatro de la tarde dificulta dormirse a medianoche. El límite está en torno a las 14:00, es decir, 8–9 horas antes de dormir.</p><p class=\"art-p\"><b>El alcohol es un «falso amigo».</b> Una copa por la noche ayuda a dormirse, pero corta la segunda mitad de la noche: más despertares, peor recuperación. Empeora los sofocos incluso en pequeñas cantidades, y en la perimenopausia descontrola la ansiedad: calma durante una hora y luego todo va a peor.</p><p class=\"art-p\"><b>Cenar tarde impide que el cuerpo se enfríe y se calme.</b> La última comida copiosa, tres horas antes de acostarte.</p><h3 class=\"art-h\">Cómo hacerlo</h3><ul class=\"art-ul\"><li><b>Café y té fuerte, solo antes de las 14:00.</b> Después, infusiones, agua, descafeinado.</li><li><b>Alcohol por la noche: una semana de pausa.</b> No para siempre, solo una semana, para ver la diferencia en ti misma.</li><li><b>Cena tres horas antes de dormir.</b> Si te acuestas a las 23:00, cena antes de las 20:00.</li></ul><h3 class=\"art-h\">Qué puede dificultarlo</h3><ul class=\"art-ul\"><li>La costumbre del «café después de comer para no dormirme». En su lugar, 10 minutos caminando al aire libre.</li><li>Una copa de vino «para relajarme». Prueba un ritual de sustitución: una ducha templada, un paseo, respiración lenta.</li><li>Volver tarde del trabajo. Entonces, una cena ligera, y la comida principal antes, durante el día.</li></ul><h3 class=\"art-h\">Qué esperar</h3><p class=\"art-p\">No te fijes en una sola noche, sino en una semana: cuánto tardas en dormirte, cuántas veces te despiertas, cómo te sientes por la mañana. Anota tu sueño y tus sofocos en VIA-L: así verás la diferencia en números, no solo en sensaciones.</p><h3 class=\"art-h\">A quién ayuda este paso</h3><p class=\"art-p\">A quienes duermen mal, tienen sofocos nocturnos y se levantan cansadas. A menudo va junto con el paso «Levantarse a la misma hora y luz por la mañana».</p><!--EV--><p class=\"art-p art-note\"><i>Esto es información general, no una prescripción.</i></p>","codes":["P-F17","P-F4","P-F9"]},"wake":{"t":"Levantarse a la misma hora y luz por la mañana: un ancla para todo el día","min":"3 minutos de lectura","h":"<p class=\"art-p\">Parece que el sueño empieza por la noche. En realidad empieza por la mañana: con la hora a la que te levantas y ves la luz. Es la palanca de conducta más fuerte para el sueño, el ánimo y la energía, y no cuesta nada.</p><h3 class=\"art-h\">Por qué funciona</h3><p class=\"art-p\">El cuerpo tiene un reloj interno. Decide cuándo estás despejada y cuándo te entra el sueño, y se ajusta sobre todo con dos señales: <b>la hora a la que te levantas</b> y <b>la luz natural de la mañana</b>. Cuando estas señales cambian cada día, el reloj se desajusta: por la noche la mente no se apaga y por la mañana no arranca. En la transición esto se nota especialmente.</p><p class=\"art-p\"><b>La regularidad al levantarte importa más que cuánto duermes.</b> Los fines de semana de «recuperar sueño» hasta mediodía vuelven a desajustar el reloj.</p><p class=\"art-p\"><b>La luz de la mañana es la señal más fuerte para el reloj.</b> 10–15 minutos al aire libre funcionan incluso con el cielo nublado: más que cualquier lámpara. Y la luz intensa de la mañana además mejora claramente el ánimo en la perimenopausia.</p><h3 class=\"art-h\">Cómo hacerlo</h3><ul class=\"art-ul\"><li><b>Levántate a la misma hora los siete días</b>, fines de semana incluidos, con media hora de margen como mucho.</li><li><b>En la primera hora tras levantarte, 10–15 minutos de luz natural.</b> Un paseo, el café en el balcón, ir andando.</li><li><b>Por la noche, lo contrario:</b> entre 30 y 60 minutos antes de dormir, luz cálida y tenue, y sin pantallas.</li></ul><h3 class=\"art-h\">Qué puede dificultarlo</h3><ul class=\"art-ul\"><li>Una mala noche. Incluso después, levántate a tu hora de siempre: así la noche siguiente será mejor.</li><li>Una mañana oscura de invierno. Sal en cuanto amanezca o pasa los primeros minutos junto a una ventana.</li><li>Los fines de semana. Puedes permitirte media hora, pero no tres horas.</li></ul><h3 class=\"art-h\">Qué esperar</h3><p class=\"art-p\">El reloj no se reajusta en una noche. Valóralo en una o dos semanas: cómo te duermes, cómo te despiertas, qué ánimo tienes por la mañana. Anota tu sueño y cómo te sientes en VIA-L.</p><h3 class=\"art-h\">A quién ayuda este paso</h3><p class=\"art-p\">A quienes les cuesta dormirse, se despiertan a mitad de la noche, se levantan agotadas, tienen altibajos de ánimo y «niebla». Funciona bien junto con el paso «Café antes de las 14:00, noche sin alcohol, cena temprana».</p><!--EV--><p class=\"art-p art-note\"><i>Esto es información general, no una prescripción.</i></p>","codes":["P-F4","P-F17","P-F9"]},"strength":{"t":"Fuerza dos veces por semana: un paso, beneficios para todo","min":"4 minutos de lectura","h":"<p class=\"art-p\">Si de todos los consejos para la transición pudieras elegir solo uno, sería el entrenamiento de fuerza. Actúa a la vez sobre los sofocos, el ánimo, los huesos, los músculos, el metabolismo y el sueño. Y no necesitas un gimnasio.</p><h3 class=\"art-h\">Por qué funciona</h3><ul class=\"art-ul\"><li><b>Sofocos.</b> La fuerza es la palanca más fuerte sin medicamentos: en el mejor estudio, los sofocos se redujeron aproximadamente a la mitad.</li><li><b>Ánimo.</b> Mejora incluso antes de que cambien la fuerza y el peso.</li><li><b>Huesos.</b> La carga es la principal señal para que el hueso se mantenga fuerte; lo que mejor funciona es la fuerza junto con pequeños saltos.</li><li><b>Músculos y energía.</b> Después de los 40, el músculo responde peor a la carga, por eso necesita más, no menos.</li><li><b>Metabolismo.</b> El músculo es el principal «consumidor» de azúcar; la fuerza también reduce la inflamación de fondo, incluso sin perder peso.</li><li><b>Cerebro.</b> El movimiento mejora la atención y la claridad.</li></ul><h3 class=\"art-h\">Cómo hacerlo</h3><ul class=\"art-ul\"><li><b>Dos sesiones de 30–40 minutos en días distintos.</b></li><li><b>La base son sentadillas, tirones y empujes.</b> Por ejemplo: sentadillas con silla, tirar de una banda elástica hacia la cintura, flexiones apoyada en la pared o en una mesa, subir a un escalón, press de mancuernas por encima de la cabeza.</li><li><b>Sin dolor.</b> La carga debe notarse, pero no doler.</li><li><b>Aumentar poco a poco.</b> Cuando resulte fácil, un poco más de peso o de repeticiones.</li></ul><p class=\"art-p\">Con un entrenador, el resultado y la seguridad son mayores. En VIA-L hay un «Entrenamiento del día» guiado por voz: puedes empezar por ahí.</p><h3 class=\"art-h\">Quién debe tener más cuidado</h3><ul class=\"art-ul\"><li><b>Tensión alta:</b> no aguantes la respiración durante el esfuerzo; suelta el aire al levantar el peso. Después de los ejercicios en el suelo, levántate despacio.</li><li><b>Medicamentos para la diabetes:</b> con un ejercicio nuevo, el azúcar puede bajar más de lo habitual. Ten a mano un tentempié rápido y, si notas debilidad o temblor, para.</li><li><b>Dolor en una articulación o en la espalda:</b> si un ejercicio provoca dolor, cámbialo por uno más fácil o reduce el peso.</li></ul><p class=\"art-p\">Si no tienes claro si el ejercicio es adecuado para ti, coméntalo con tu médico.</p><h3 class=\"art-h\">Qué puede dificultarlo</h3><ul class=\"art-ul\"><li>«No tengo tiempo». Dos sesiones de 30 minutos son una hora a la semana.</li><li>«Nunca lo he hecho». Empieza con tu propio peso y una silla. Importa la regularidad, no los récords.</li></ul><h3 class=\"art-h\">Qué esperar</h3><p class=\"art-p\">El ánimo y cómo te sientes suelen cambiar antes que la fuerza y la figura. Anota tus entrenamientos, sofocos y ánimo en VIA-L: en unas semanas verás qué cambia en tu caso.</p><h3 class=\"art-h\">A quién ayuda este paso</h3><p class=\"art-p\">A casi todas: con sofocos, cansancio, altibajos de ánimo, cintura que crece, dolor de articulaciones y debilidad muscular.</p><!--EV--><p class=\"art-p art-note\"><i>Esto es información general, no una prescripción.</i></p>","codes":["P-F1","P-F12","P-F7","P-F8"]},"protein":{"t":"Proteína en cada comida: por qué después de los 40 hace falta más","min":"3 minutos de lectura","h":"<p class=\"art-p\">Por la mañana, café con galletas; durante el día, algo rápido; por la noche, una cena completa. Así come muchísima gente. Y en este esquema casi no hay proteína hasta la noche. Después de los 40, esto se nota en la energía, en los músculos y en los antojos de dulce.</p><h3 class=\"art-h\">Por qué funciona</h3><p class=\"art-p\"><b>El músculo se ha vuelto «más exigente».</b> Después de los 40 responde peor a la proteína, así que para conservarlo hace falta más proteína que antes, y repartida a lo largo del día, no toda en la cena.</p><p class=\"art-p\"><b>La proteína sacia y estabiliza el azúcar.</b> Una comida con proteína sacia durante más tiempo y suaviza los picos de azúcar: menos bajones y menos antojos de dulce.</p><p class=\"art-p\"><b>Un desayuno con proteína equilibra el día.</b> Saltarse el desayuno o tomar uno «vacío» mantiene altas las hormonas del estrés, y durante el día llega el bajón. Mejor desayunar en la primera hora o dos tras levantarte.</p><h3 class=\"art-h\">Cómo hacerlo</h3><ul class=\"art-ul\"><li><b>En cada comida, una fuente de proteína.</b> La referencia: 30–40 g de proteína por comida.</li><li><b>Empieza por el desayuno:</b> suele ser donde menos proteína hay.</li><li><b>Al día</b>, al menos 1–1,2 g de proteína por kilo de peso, y más si haces fuerza.</li></ul><p class=\"art-p\">Cómo se ven 30–40 g de proteína en la práctica, aproximadamente:</p><ul class=\"art-ul\"><li>desayuno: tortilla de 2–3 huevos con requesón o yogur griego con frutos secos;</li><li>comida: una ración de pescado, pollo o carne del tamaño de la palma de la mano;</li><li>cena: lentejas o alubias con tofu, queso, marisco.</li></ul><p class=\"art-p\">La proteína en polvo es un recurso práctico si con la comida no llegas.</p><h3 class=\"art-h\">Quién debe tener más cuidado</h3><ul class=\"art-ul\"><li><b>Con enfermedad renal</b>, acuerda con tu médico la cantidad de proteína.</li><li><b>Si has tenido dificultades con la comida</b> —un trastorno de la conducta alimentaria ahora o en el pasado—, las normas sobre la comida es mejor hablarlas con un especialista que aplicarlas por tu cuenta.</li></ul><h3 class=\"art-h\">Qué puede dificultarlo</h3><ul class=\"art-ul\"><li>«Por la mañana no me entra». Empieza con poco: un yogur, un huevo, un vaso de kéfir.</li><li>«No tengo tiempo para cocinar». Huevos cocidos, requesón, pescado en conserva, lentejas cocidas de bote: sin cocinar.</li></ul><h3 class=\"art-h\">Qué esperar</h3><p class=\"art-p\">Fíjate en cómo cambian la saciedad y los antojos de dulce entre comidas. Anota tu energía y cómo te sientes en VIA-L.</p><h3 class=\"art-h\">A quién ayuda este paso</h3><p class=\"art-p\">A quienes tienen cansancio, una cintura que crece, debilidad muscular y dolor de articulaciones. Funciona bien junto con el entrenamiento de fuerza.</p><!--EV--><p class=\"art-p art-note\"><i>Esto es información general, no una prescripción.</i></p>","codes":["P-F12","P-F7","P-F4"]},"cool":{"t":"Dormitorio fresco: una forma sencilla de dormir mejor con sofocos","min":"3 minutos de lectura","h":"<p class=\"art-p\">Por la noche te da un golpe de calor, apartas el edredón, luego tienes frío, luego otra vez calor, y así hasta la mañana. Si te suena, un dormitorio fresco es uno de los pasos más sencillos que puedes dar hoy mismo.</p><h3 class=\"art-h\">Por qué funciona</h3><p class=\"art-p\">En la transición se estrecha la «zona de confort térmico»: basta muy poco calor para desencadenar un sofoco. Y la mayoría de los sofocos nocturnos coincide con un despertar. Un dormitorio fresco mantiene el cuerpo más lejos de ese límite.</p><p class=\"art-p\">Siendo sinceros: enfriar no recupera la zona de confort ni «anula» los sofocos. Pero reduce claramente los despertares nocturnos y las molestias, y añade sueño profundo.</p><h3 class=\"art-h\">Cómo hacerlo</h3><ul class=\"art-ul\"><li><b>Temperatura del dormitorio: alrededor de 16–19 °C.</b> Ventila antes de dormir, baja la calefacción.</li><li><b>Oscuridad.</b> Cortinas opacas o un antifaz.</li><li><b>Tejidos transpirables.</b> Sábanas y pijama de algodón, lino u otros tejidos que transpiren.</li><li><b>Capas en lugar de un solo edredón grueso.</b> Un edredón ligero más una manta, para quitarte algo fácilmente por la noche sin despertarte del todo.</li><li><b>Un cubrecolchón o una almohada refrescantes</b>, si los sofocos son intensos.</li><li><b>Agua junto a la cama</b> y una camiseta de repuesto, por si hay sudores nocturnos.</li></ul><h3 class=\"art-h\">Qué puede dificultarlo</h3><ul class=\"art-ul\"><li>Tu pareja tiene frío. Ayudan los edredones separados: uno para cada uno.</li><li>Un verano caluroso. Ventilador, ventilar por la noche, una ducha fresca antes de dormir.</li><li>La costumbre de un pijama abrigado. Cámbialo por uno ligero y quédate con los calcetines calentitos si se te enfrían los pies.</li></ul><h3 class=\"art-h\">Qué esperar</h3><p class=\"art-p\">Fíjate sobre todo en cuántas veces te despiertas por la noche. Anota tu sueño y tus sofocos en VIA-L para comparar la semana anterior y la siguiente.</p><h3 class=\"art-h\">Si no ayuda</h3><p class=\"art-p\">Si aun así los sofocos intensos te rompen la noche, es motivo para ir al médico. Tratar los propios sofocos mejora también el sueño. Más en el artículo «Sofocos: por qué aparecen y qué ayuda de verdad».</p><h3 class=\"art-h\">A quién ayuda este paso</h3><p class=\"art-p\">A quienes tienen sofocos nocturnos, sudores nocturnos y despertares a mitad de la noche.</p><!--EV--><p class=\"art-p art-note\"><i>Esto es información general, no una prescripción.</i></p>","codes":["P-F17","P-F1"]},"walk":{"t":"Caminar después de comer: 10 minutos que cambian todo el día","min":"3 minutos de lectura","h":"<p class=\"art-p\">Después de comer te entra sueño, un par de horas más tarde te apetece algo dulce, y por la noche no te queda energía. A menudo no es «el carácter», sino la montaña rusa del azúcar después de comer. Y uno de los remedios más sencillos es un paseo corto justo después de comer.</p><h3 class=\"art-h\">Por qué funciona</h3><p class=\"art-p\">Después de comer, el azúcar en sangre sube. Cuando los músculos se mueven, captan el azúcar: es una vía aparte para usarlo, además de la habitual. El pico queda más bajo, y por tanto también es menor el bajón que viene después: menos somnolencia y menos antojos de dulce.</p><p class=\"art-p\">Caminar funciona especialmente bien junto con otro paso, «Verduras y proteína antes que los carbohidratos»: los efectos se suman.</p><h3 class=\"art-h\">Cómo hacerlo</h3><ul class=\"art-ul\"><li><b>10–15 minutos caminando después de las comidas principales.</b> Mejor justo después de comer, no una hora más tarde.</li><li><b>A ritmo normal</b>, que puedas hablar. No es un entrenamiento, es movimiento.</li><li><b>Si no puedes salir</b>, camina por casa, sube escaleras, ordena, friega de pie.</li></ul><h3 class=\"art-h\">Quién debe tener más cuidado</h3><ul class=\"art-ul\"><li><b>Medicamentos para la diabetes:</b> con un ejercicio nuevo, el azúcar puede bajar más de lo habitual. Ten a mano un tentempié rápido y, si notas debilidad o temblor, para.</li><li><b>Una lesión, una enfermedad, fiebre:</b> primero recupérate; el paso puede esperar.</li></ul><h3 class=\"art-h\">Qué puede dificultarlo</h3><ul class=\"art-ul\"><li>Un trabajo de oficina. Un paseo corto después de comer, una llamada caminando, las escaleras en lugar del ascensor.</li><li>El tiempo. Caminar por casa o por un centro comercial también cuenta.</li><li>La noche. Incluso 10 minutos después de cenar es mejor que ir directa al sofá.</li></ul><h3 class=\"art-h\">Qué esperar</h3><p class=\"art-p\">Fíjate en la somnolencia de después de comer y en los antojos de dulce. Anota tu energía y cómo te sientes en VIA-L.</p><h3 class=\"art-h\">A quién ayuda este paso</h3><p class=\"art-p\">A quienes tienen bajones de energía después de comer, antojos de dulce y una cintura que crece.</p><!--EV--><p class=\"art-p art-note\"><i>Esto es información general, no una prescripción.</i></p>","codes":["P-F7","P-F1"]},"breath":{"t":"Respiración lenta: calma en cinco minutos","min":"3 minutos de lectura","h":"<p class=\"art-p\">La ansiedad llega sin motivo, la irritación salta por cualquier cosa, y por la noche los pensamientos no te dejan dormir. La respiración lenta es una de las formas más sencillas de calmar el sistema nervioso. Funciona sin fuerza de voluntad y sin condiciones especiales.</p><h3 class=\"art-h\">Por qué funciona</h3><p class=\"art-p\">Una inspiración lenta y, sobre todo, una espiración larga cambian directamente el sistema nervioso del modo «alarma» al modo «calma». Es un reflejo: no hace falta convencerte. En los estudios, la respiración lenta y la meditación son comparables a un medicamento en su efecto sobre la ansiedad.</p><h3 class=\"art-h\">Lo que la respiración no hace</h3><p class=\"art-p\">Siendo sinceros: la respiración lenta no reduce los sofocos en sí; en los estudios no es mejor que un placebo. El yoga y la meditación, tampoco. Para los sofocos funcionan mejor el entrenamiento de fuerza, un dormitorio fresco y, sin medicamentos, la terapia cognitivo-conductual y la hipnosis clínica. Más en el artículo «Sofocos: por qué aparecen y qué ayuda de verdad».</p><p class=\"art-p\">La respiración es para la calma, la ansiedad y la irritación. Por eso vale la pena practicarla.</p><h3 class=\"art-h\">Cómo hacerlo</h3><ul class=\"art-ul\"><li><b>Inspira por la nariz contando hasta cuatro, espira despacio contando hasta seis.</b> Salen unas seis respiraciones por minuto.</li><li><b>5–10 minutos al día.</b> Incluso cinco minutos tienen efecto.</li><li><b>Lo más cómodo es por la noche</b>: ayuda a pasar al sueño. Pero también puedes hacerlo de día, en cualquier pausa: antes de una reunión, en el coche antes de bajarte, después del trabajo.</li><li><b>Cuando aparezca la ansiedad</b>, pasa enseguida a espiraciones lentas y largas.</li></ul><p class=\"art-p\">Hombros relajados, respira con el abdomen. Si te mareas, respira de forma menos profunda y un poco más rápido.</p><h3 class=\"art-h\">Quién debe tener más cuidado</h3><p class=\"art-p\"><b>Con asma</b>, respira con calma, sin retener el aire ni hacer fuerza. Si empieza una crisis, para y usa tu tratamiento habitual.</p><h3 class=\"art-h\">Qué puede dificultarlo</h3><ul class=\"art-ul\"><li>«Los pensamientos se me van». Es parte del ejercicio: te das cuenta y vuelves a contar.</li><li>«Se me olvida». Une la respiración a algo que ya haces cada día: lavarte los dientes por la noche, apagar la luz.</li><li>«Solo con respirar no voy a arreglar el sueño». Cierto: para el sueño son más fuertes el ancla al levantarte y la regla «la cama, solo para dormir». La respiración es un complemento.</li></ul><h3 class=\"art-h\">Qué esperar</h3><p class=\"art-p\">Fíjate en con qué frecuencia aparecen la ansiedad y la irritación y en cómo te duermes. Si llevas un anillo o un reloj, puedes comparar la variabilidad de la frecuencia cardíaca en las noches con respiración y sin ella. Anota cómo te sientes en VIA-L.</p><h3 class=\"art-h\">Si no ayuda</h3><p class=\"art-p\">Si la ansiedad o el bajón duran más de dos semanas y te impiden vivir con normalidad, es motivo para ir al médico. Más en el artículo «Cambios de humor, ansiedad e irritabilidad».</p><!--EV--><p class=\"art-p art-note\"><i>Esto es información general, no una prescripción.</i></p>","codes":["P-F4","P-F9","P-F1"]},"bed":{"t":"La cama, solo para dormir: cómo ayudar al cuerpo a volver a dormirse","min":"3 minutos de lectura","h":"<p class=\"art-p\">Te acuestas cansada y el sueño desaparece. Pasas una hora en la cama, miras el móvil, cuentas cuánto falta para el despertador. Cuanto más dura esto, más asocia el cerebro la cama no con dormir, sino con estar despierta y con la ansiedad. Este paso recupera la asociación correcta.</p><h3 class=\"art-h\">Por qué funciona</h3><p class=\"art-p\">Es la base del enfoque conductual del sueño: según los estudios, es más eficaz que los somníferos y que una simple lista de normas de «higiene del sueño». La idea es sencilla: la cama tiene que volver a significar dormir. Cuando en ella solo duermes, el cerebro vuelve a aprender a dormirse en cuanto la cabeza toca la almohada.</p><h3 class=\"art-h\">Cómo hacerlo</h3><ul class=\"art-ul\"><li><b>No te quedes en la cama sin dormir.</b> Si no te duermes en más de 15–20 minutos, levántate, ve a otro sitio con luz tenue y haz algo tranquilo. Vuelve cuando empiece a entrarte el sueño.</li><li><b>En la cama no trabajes ni mires el móvil.</b> Carga el móvil lejos de la cama.</li><li><b>No mires el reloj por la noche.</b> Contar las horas que quedan solo añade ansiedad.</li><li><b>Acuéstate cuando te entre el sueño y levántate a la misma hora.</b> Acostarte pronto «por si acaso» a menudo significa pasar más tiempo despierta en la cama.</li><li><b>Sin pantallas entre 30 y 60 minutos antes de dormir.</b></li></ul><h3 class=\"art-h\">Quién debe tener más cuidado</h3><p class=\"art-p\"><b>Si tomas medicamentos para la tensión o tienes más de 70 años:</b> por la noche no te levantes de golpe; siéntate primero un minuto en el borde de la cama. Luz del pasillo tenue, pero suficiente para no tropezar.</p><p class=\"art-p\">Si de día la somnolencia te dificulta conducir, no cojas el coche cansada.</p><h3 class=\"art-h\">Qué puede dificultarlo</h3><ul class=\"art-ul\"><li>«El móvil es mi despertador». Un despertador normal, o el móvil donde tengas que levantarte para cogerlo.</li><li>«Me cuesta levantarme por la noche». Los primeros días puede resultar raro. Lo importante es no pasar horas despierta en la cama.</li><li>«En casa no tengo adónde ir». Un sillón en la misma habitación con una lámpara tenue también sirve.</li></ul><h3 class=\"art-h\">Qué esperar</h3><p class=\"art-p\">Fíjate en cuánto tiempo pasas despierta en la cama y cuántas veces te despiertas. Anota tu sueño en VIA-L para ver la diferencia semana a semana.</p><h3 class=\"art-h\">Cuándo ir al médico</h3><p class=\"art-p\">Si el mal sueño dura más de tres meses pese a estos pasos, o si roncas con pausas, el sueño no te descansa o te quedas dormida de día, conviene ir al médico o a un especialista en sueño. Más en el artículo «Por qué empeora el sueño después de los 40».</p><!--EV--><p class=\"art-p art-note\"><i>Esto es información general, no una prescripción.</i></p>","codes":["P-F17","P-F3","P-F4"]},"order":{"t":"Verduras y proteína antes que los carbohidratos: la misma comida, más suave para el azúcar","min":"3 minutos de lectura","h":"<p class=\"art-p\">Este paso no va de comer menos ni de renunciar a lo que te gusta. Va del orden: qué comer primero. Un simple cambio de orden en el plato cambia claramente cómo maneja tu cuerpo la comida.</p><h3 class=\"art-h\">Por qué funciona</h3><p class=\"art-p\">Si empiezas la comida con verduras y proteína, y el pan, los cereales, las patatas o la pasta los tomas después, el pico de azúcar tras la comida es más suave: aproximadamente un tercio menos. Un pico menor significa un bajón menor después: menos somnolencia tras la comida y menos antojos de dulce.</p><p class=\"art-p\">En la transición el cuerpo responde peor al azúcar, por eso estos trucos sencillos son especialmente útiles. Y junto con caminar después de comer, los efectos se suman.</p><h3 class=\"art-h\">Cómo hacerlo</h3><ul class=\"art-ul\"><li><b>Primero las verduras</b>: ensalada, verduras cocinadas o crudas.</li><li><b>Después la proteína</b>: carne, pescado, huevos, tofu, legumbres.</li><li><b>Los carbohidratos, al final:</b> la guarnición, el pan.</li></ul><p class=\"art-p\">Todo en el mismo plato, simplemente en este orden. No hace falta comer menos.</p><h3 class=\"art-h\">Quién debe tener más cuidado</h3><ul class=\"art-ul\"><li><b>Si has tenido dificultades con la comida</b> —un trastorno de la conducta alimentaria ahora o en el pasado—, las normas sobre la comida es mejor hablarlas con un especialista que aplicarlas por tu cuenta.</li><li><b>Si tomas warfarina:</b> no cambies de golpe la cantidad de verduras de hoja verde; de ello depende cómo actúa el medicamento. Comenta con tu médico cualquier cambio en la alimentación.</li></ul><h3 class=\"art-h\">Qué puede dificultarlo</h3><ul class=\"art-ul\"><li>«No tengo verduras». Sirven las congeladas o algo sencillo: pepino, tomate, pimiento.</li><li>«Comer fuera o en casa de alguien». Empieza por una ensalada o un entrante de verduras, y el pan, después.</li><li>«El desayuno es avena o un bocadillo». Añádele primero un huevo, requesón o verduras.</li></ul><h3 class=\"art-h\">Qué esperar</h3><p class=\"art-p\">Fíjate en la saciedad después de comer, en la somnolencia tras la comida y en los antojos de dulce. El peso cambia más despacio, así que guíate por cómo te sientes. Anótalo en VIA-L.</p><h3 class=\"art-h\">A quién ayuda este paso</h3><p class=\"art-p\">A quienes tienen una cintura que crece, bajones de energía después de comer y antojos de dulce. Funciona bien junto con caminar después de comer y la proteína en cada comida.</p><!--EV--><p class=\"art-p art-note\"><i>Esto es información general, no una prescripción.</i></p>","codes":["P-F7","P-F1"]}},"ru":{"start-peri":{"t":"Что такое перименопауза и как её узнать","min":"4 минуты чтения","h":"<p class=\"art-p\">Сон стал хуже, месячные — непредсказуемее, настроение скачет, а анализы «в порядке». Знакомо? Очень часто за этим стоит перименопауза — переходные годы перед последними месячными. Это не болезнь, а этап, через который проходит каждая женщина. Но о нём почти не говорят, поэтому многие годами не понимают, что с ними происходит.</p><h3 class=\"art-h\">Что происходит в теле</h3><p class=\"art-p\">В переходе гормоны меняются не плавно и не одновременно.</p><p class=\"art-p\"><b>Прогестерон падает первым и ровно.</b> После 40 всё больше циклов проходит без овуляции — и это обычная часть перехода. Прогестерон питает естественный «успокоитель» мозга, поэтому его спад чаще всего чувствуется как трудное засыпание.</p><p class=\"art-p\"><b>Эстроген в это время не падает, а качается.</b> Он то снижается, то скачет выше обычного, и только потом уходит вниз окончательно. Главное, что раскачивает самочувствие в эти годы, — именно амплитуда качелей, а не сам уровень. Отсюда и ощущение, что «ничего не понятно»: одна неделя хорошая, следующая — тяжёлая.</p><h3 class=\"art-h\">Как её узнать</h3><p class=\"art-p\">Перименопаузу узнают по картине, которая складывается во времени, а не по одному анализу. Типичные сигналы:</p><ul class=\"art-ul\"><li><b>Цикл меняется.</b> В 35–50 лет месячные часто становятся обильнее, длиннее или нерегулярнее.</li><li><b>Сон.</b> Труднее заснуть, больше ночных пробуждений, мозг «не выключается».</li><li><b>Настроение.</b> Перепады, раздражительность, сильнее, чем раньше, ощущается время перед месячными.</li><li><b>Грудь и вода.</b> Налитость и болезненность груди, вздутие.</li><li><b>Голова.</b> Мигрени, «туман», хуже концентрация.</li><li><b>Приливы и ночная потливость.</b> Могут начаться уже в эти годы.</li></ul><p class=\"art-p\">Не обязательно, чтобы было всё сразу. Важнее рисунок: что повторяется и как это связано с циклом.</p><h3 class=\"art-h\">Что сделать в первую очередь</h3><p class=\"art-p\"><b>Начать отмечать.</b> Первый день месячных, сон, приливы, настроение — каждый день, коротко. Через несколько недель видна связь, которую в памяти не удержать. Именно это и есть лучший «анализ» перехода.</p><p class=\"art-p\"><b>Поставить якорь сна.</b> Подъём в одно и то же время все семь дней недели, включая выходные, и 10–15 минут дневного света в первый час после подъёма. Это самый сильный поведенческий рычаг для сна — сильнее любых добавок.</p><p class=\"art-p\"><b>Убрать то, что раскачивает ночь.</b> Кофе и крепкий чай — до 14:00, вечером — без алкоголя: он усыпляет, но режет вторую половину ночи.</p><p class=\"art-p\"><b>Проверить железо при обильных месячных.</b> Обильные месячные — самая частая причина нехватки железа у женщин, и его запасы падают раньше, чем меняются обычные анализы крови. Усталость, одышка на лестнице, выпадение волос — повод попросить у врача анализ на ферритин. Железо — по анализу, не вслепую.</p><h3 class=\"art-h\">Когда к врачу без промедления</h3><ul class=\"art-ul\"><li>Прокладку или тампон приходится менять каждый час несколько часов подряд.</li><li>Месячные длятся дольше 8 дней.</li><li>Кровь между месячными.</li><li>Кровотечение вместе с сильной усталостью или дурнотой.</li></ul><p class=\"art-p\">Это не «просто переход» — такие сигналы нужно показать гинекологу.</p><h3 class=\"art-h\">Что попробовать на этой неделе</h3><ul class=\"art-ul\"><li>Отмечать первый день месячных и сон в VIA-L.</li><li>Вставать в одно и то же время все семь дней.</li><li>Кофе — до 14:00, вечер без алкоголя.</li></ul><!--EV--><p class=\"art-p art-note\"><i>Это общие сведения, а не назначение. Обследование и лечение подбирает врач.</i></p>","codes":["P-F1","P-F3","P-F17","P-F22"]},"start-meno":{"t":"Менопауза: что меняется после последних месячных","min":"5 минут чтения","h":"<p class=\"art-p\">Менопауза — это момент, когда месячных нет двенадцать месяцев подряд. Всё, что после, — постменопауза. Эстроген теперь стабильно низкий, и тело перестраивается под эту новую реальность. Часть перемен чувствуется сразу, часть — «немая» и проявится только через годы. О вторых стоит знать заранее: именно в первые годы после менопаузы больше всего можно сделать на десятилетия вперёд.</p><h3 class=\"art-h\">Что чувствуется</h3><p class=\"art-p\">Когда эстрогена мало, складывается узнаваемая картина: приливы, ночная потливость, дробный сон, сухость и дискомфорт при близости, ноющие суставы и мышцы, «туман» в голове. Это одна история, а не набор отдельных бед, и браться за неё лучше целиком.</p><p class=\"art-p\">Отдельно о сухости и дискомфорте при близости. Это очень частая перемена — у половины женщин и больше, — но о ней почти не говорят. В отличие от приливов, она сама не проходит и со временем усиливается. Зато она хорошо поддаётся помощи: регулярный увлажнитель, лубрикант для близости, тренировки тазового дна — и разговор с врачом. Терпеть не нужно.</p><h3 class=\"art-h\">Что не чувствуется, но важно</h3><p class=\"art-p\"><b>Сердце и сосуды.</b> До менопаузы риск болезней сердца у женщин примерно вдвое ниже, чем у мужчин, а с падением эстрогена разрыв быстро закрывается. Самое резкое ускорение — за год-два вокруг последних месячных: растёт «плохой» холестерин, жёстче становятся сосуды. Это не приговор, а окно профилактики.</p><p class=\"art-p\"><b>Кости.</b> Быстрее всего кость теряется примерно за год до последних месячных и два года после — до 2% в год у позвоночника. Симптомов нет до самого перелома. Если были ранняя менопауза до 45, перелом от лёгкой травмы, долгий приём стероидов или перелом бедра у родителей — стоит обсудить с врачом денситометрию уже сейчас, не дожидаясь 65.</p><p class=\"art-p\"><b>Мышцы и обмен.</b> Жир смещается к животу, тело хуже отвечает на сахар, мышца — на белок и нагрузку. Тяга к сладкому, «туман» и изменение фигуры — одна цепочка.</p><h3 class=\"art-h\">Что делать</h3><p class=\"art-p\"><b>Силовые тренировки два раза в неделю.</b> Это рычаг сразу на всё: на приливы, настроение, кости, мышцы и обмен. Основа — приседания, тяги и жимы, без боли.</p><p class=\"art-p\"><b>Белок в каждый приём пищи, начиная с завтрака.</b> После 40 мышце нужно больше белка, чем раньше, а на завтрак его обычно меньше всего.</p><p class=\"art-p\"><b>Ходьба после еды.</b> 10–15 минут после еды помогают телу справиться с сахаром.</p><p class=\"art-p\"><b>Средиземноморский стиль питания.</b> Оливковое масло, рыба, орехи, овощи и клетчатка — лучший изученный способ поддержать сердце и сосуды.</p><p class=\"art-p\"><b>Знать свои цифры.</b> Давление, сахар, холестерин — и по возможности попросить у врача ApoB и Lp(a): они точнее показывают риск для сосудов, а Lp(a) достаточно сдать один раз в жизни.</p><h3 class=\"art-h\">Когда к врачу без промедления</h3><p class=\"art-p\">Любое кровотечение после двенадцати месяцев без месячных — всегда повод быстро показаться гинекологу.</p><h3 class=\"art-h\">Что попробовать на этой неделе</h3><ul class=\"art-ul\"><li>Две силовые тренировки по 30–40 минут в разные дни.</li><li>В каждом приёме пищи — источник белка; начать с завтрака.</li><li>10–15 минут ходьбы после основного приёма пищи.</li></ul><!--EV--><p class=\"art-p art-note\"><i>Это общие сведения, а не назначение. Обследование и лечение подбирает врач.</i></p>","codes":["P-F1","P-F12","P-F13","P-F15"]},"start-tests":{"t":"Почему анализы на гормоны в 40+ мало что скажут","min":"4 минуты чтения","h":"<p class=\"art-p\">Первое желание, когда самочувствие меняется, — «сдать гормоны» и увидеть ответ в цифрах. Но в переходные годы как раз эти анализы подводят чаще всего. Разберёмся почему — и какие анализы действительно стоит сдать.</p><h3 class=\"art-h\">Почему гормоны не ловятся анализом</h3><p class=\"art-p\"><b>Они скачут.</b> В перименопаузе эстроген качается то вверх, то вниз, а ФСГ, эстрадиол и прогестерон в 40+ меняются так сильно, что один анализ — это снимок одного случайного дня. Завтра цифры будут другими.</p><p class=\"art-p\"><b>Прогестерон пульсирует.</b> Его уровень в крови меняется в разы за считаные минуты. Даже анализ крови показывает лишь мгновение, а домашние тесты его не измеряют вовсе.</p><p class=\"art-p\"><b>Гаджет гормоны не измеряет.</b> Кольцо или часы видят подъём температуры после овуляции — но задним числом и только как метку. Если подъёма не было, это не значит «мало прогестерона»: после 40 часть циклов проходит без овуляции, бывает и шум датчика, и прилив, и простуда.</p><p class=\"art-p\">Поэтому перименопаузу узнают не по анализу, а по картине во времени: как меняются цикл, сон, настроение, приливы. Дневник за несколько недель скажет больше, чем один бланк.</p><h3 class=\"art-h\">Что важно исключить</h3><p class=\"art-p\">Часть симптомов перехода похожа на другие состояния, которые легко проверить и с которыми можно работать. Их стоит исключить в первую очередь:</p><ul class=\"art-ul\"><li><b>Щитовидная железа</b> — если появились зябкость, запоры, редкий пульс: анализ на ТТГ.</li><li><b>Запасы железа</b> — если месячные обильные, есть усталость, одышка на лестнице, тянет грызть лёд, вечером беспокоят ноги: анализ на ферритин. Железо падает раньше, чем меняется обычный анализ крови.</li><li><b>Настроение</b> — если подавленность или тревога держатся весь месяц, а не только перед месячными, это повод поговорить с врачом отдельно.</li><li><b>Дыхание во сне</b> — храп с паузами, неосвежающий сон, дневная сонливость: после менопаузы это частая и часто пропускаемая причина усталости.</li></ul><h3 class=\"art-h\">Какие анализы действительно полезны в 40+</h3><ul class=\"art-ul\"><li><b>Давление и сахар</b> — регулярно.</li><li><b>ApoB</b> — точнее обычного «плохого холестерина» показывает частицы, опасные для сосудов.</li><li><b>Lp(a)</b> — достаточно сдать один раз в жизни: он наследственный и после менопаузы растёт.</li><li><b>hs-CRP</b> — показатель фонового воспаления, у женщин он хорошо предсказывает риск для сердца.</li><li><b>Ферритин и ТТГ</b> — по сигналам выше.</li><li><b>Денситометрия</b> — уже на менопаузе, если есть факторы риска: менопауза до 45, перелом от лёгкой травмы, долгий приём стероидов, перелом бедра у родителей.</li></ul><p class=\"art-p\">Просите у врача не только «холестерин», а по возможности ApoB и Lp(a).</p><h3 class=\"art-h\">Что попробовать на этой неделе</h3><ul class=\"art-ul\"><li>Начать дневник в VIA-L: первый день месячных, сон, приливы, настроение.</li><li>Записать, что из списка «важно исключить» относится к вам.</li><li>Составить для врача список: какие анализы вы хотите обсудить.</li></ul><!--EV--><p class=\"art-p art-note\"><i>Это общие сведения, а не назначение. Какие анализы сдавать, решает врач.</i></p>","codes":["P-F3","P-F6","P-F13","P-F22"]},"hf":{"t":"Приливы: почему они бывают и что на самом деле помогает","min":"4 минуты чтения","h":"<p class=\"art-p\">Жар поднимается к лицу и шее, бросает в пот, потом может зазнобить. Ночью то же самое будит, и утром кажется, что вы не спали вовсе. Приливы — одна из самых частых примет перименопаузы и менопаузы. Хорошая новость: про них много известно, и часть привычных советов работает, а часть — нет. Разберёмся, где что.</p><h3 class=\"art-h\">Почему тело вдруг перегревается</h3><p class=\"art-p\">У каждого из нас есть «зона теплового комфорта» — диапазон, в котором тело не пытается ни остыть, ни согреться. Когда в переходе снижается эстроген, эта зона сужается. Теперь телу хватает совсем небольшого повышения температуры, чтобы решить, что пора срочно охлаждаться: сосуды расширяются, кожа краснеет, выступает пот.</p><p class=\"art-p\">Обычно рядом с приливами идут ночная потливость, дробный сон, сухость, ноющие суставы и «туман» в голове. Это одна картина, а не набор отдельных бед. Если у вас есть кольцо или часы, ночью на них часто видны резкие скачки температуры кожи вместе с пробуждениями.</p><h3 class=\"art-h\">Почему ночью хуже всего</h3><p class=\"art-p\">Большинство ночных приливов совпадает с пробуждением. Ночь рвётся на куски, и наутро нет сил, хуже настроение, сильнее тянет на сладкое. Поэтому всё, что уменьшает ночные пробуждения, помогает не только с приливами, но и со всем днём.</p><h3 class=\"art-h\">Что помогает — по силе доказательств</h3><p class=\"art-p\"><b>Силовые тренировки два раза в неделю.</b> Это самый сильный рычаг без лекарств. В лучшем исследовании приливов стало примерно вдвое меньше, а настроение улучшалось, даже когда сила и вес ещё не изменились. Начинать стоит именно с этого, а не оставлять «на потом».</p><p class=\"art-p\"><b>Когнитивно-поведенческая терапия и клинический гипноз.</b> Это единственные методы без лекарств с сильной опорой именно по приливам. После КПТ приливы меньше беспокоят и меньше мешают жить, гипноз снижает и их частоту. Бывают групповые, онлайн- и книжные форматы; ведёт психолог или психотерапевт с такой практикой.</p><p class=\"art-p\"><b>Прохладная тёмная спальня.</b> Около 16–19 °C, дышащие ткани, одежда и одеяло слоями, чтобы ночью легко снять лишнее. Честно: охлаждение не возвращает «зону комфорта», но заметно уменьшает пробуждения и дискомфорт.</p><p class=\"art-p\"><b>Меньше алкоголя и кофеина.</b> Алкоголь усиливает приливы даже в небольших количествах и режет вторую половину ночи. Кофе и крепкий чай — до 14:00.</p><h3 class=\"art-h\">Что не помогает от приливов, хотя часто советуют</h3><ul class=\"art-ul\"><li><b>Дыхательные практики, йога, медитация</b> приливы не снижают лучше пустышки. Но они помогают спокойствию и сну — ради этого их и стоит делать.</li><li><b>Соя, тофу и молотый лён</b> в исследованиях приливы не уменьшили. Как еда они хороши — белок и клетчатка, — но не как «средство от приливов».</li><li><b>Травы</b> — клопогон, красный клевер, дон-квай, витекс — в качественных исследованиях от приливов не лучше пустышки, а с лекарствами бывают взаимодействия. Если хочется попробовать, сначала обсудите со специалистом.</li><li><b>Омега-3</b> полезна сердцу и сосудам, но от приливов в исследованиях не помогает.</li></ul><p class=\"art-p\">Ни у одной безрецептурной добавки убедительной опоры по приливам нет.</p><h3 class=\"art-h\">Когда стоит пойти к врачу</h3><p class=\"art-p\">Если приливы часто будят ночью или мешают работать и жить — это повод к врачу, а не к терпению. Самое действенное здесь — рецептурное: есть и гормональные, и негормональные варианты. Это полноценный вариант, а не «провал естественного пути»; питание и привычки остаются поддержкой, а не заменой.</p><p class=\"art-p\">И ещё одна причина рассказать врачу о приливах: сильные и долгие приливы и ночная потливость — не только дискомфорт. Врачи учитывают их, когда оценивают сердце и сосуды, — а после менопаузы это особенно важно.</p><h3 class=\"art-h\">Что попробовать на этой неделе</h3><ul class=\"art-ul\"><li>Спальня прохладная и тёмная; постель и одежда для сна — из дышащих тканей, слоями.</li><li>Две силовые тренировки по 30–40 минут в разные дни; основа — приседания, тяги и жимы, без боли.</li><li>Кофе и крепкий чай — только до 14:00, вечером — без алкоголя.</li></ul><p class=\"art-p\">Отмечайте приливы каждый день в VIA-L: через две-три недели будет видно, что из этого работает именно у вас.</p><!--EV--><p class=\"art-p art-note\"><i>Это общие сведения, а не назначение. Дозу и схему лечения подбирает врач.</i></p>","codes":["P-F1","P-F17","P-F13"]},"sleep":{"t":"Почему после 40 портится сон и что с этим делать","min":"5 минут чтения","h":"<p class=\"art-p\">Раньше засыпали за десять минут, а теперь лежите час. Или засыпаете легко, но в три часа ночи — глаза открыты, и мысли не дают уснуть снова. Сон — одна из первых вещей, которые меняются в переходе. И одна из самых благодарных: здесь привычки работают сильнее таблеток.</p><h3 class=\"art-h\">Что на самом деле меняется</h3><p class=\"art-p\">Честно: часть ухудшения сна с годами — это просто возраст. Но у перехода есть свои приметы.</p><p class=\"art-p\"><b>Труднее заснуть.</b> Прогестерон питает естественный «успокоитель» мозга. Когда его становится меньше, засыпание даётся тяжелее.</p><p class=\"art-p\"><b>Мозг не выключается.</b> Ночью будто кто-то держит палец на кнопке — мысли крутятся, тело устало, а сна нет. Это бывает и без всяких приливов.</p><p class=\"art-p\"><b>Ночь рвут приливы.</b> Большинство ночных приливов совпадает с пробуждением.</p><p class=\"art-p\"><b>Вечером не отпускает.</b> Сбитый суточный ритм стресса не даёт телу «выдохнуть» к ночи — отсюда пробуждения в 3–4 утра.</p><p class=\"art-p\">Если у вас кольцо или часы: общий сон, засыпание и число пробуждений они показывают надёжно. А вот «глубокий» и «быстрый» сон — приблизительно; смотрите на них как на подсказку, а не как на факт.</p><h3 class=\"art-h\">Что работает сильнее всего</h3><p class=\"art-p\"><b>Якорь подъёма.</b> Вставать в одно и то же время все семь дней, включая выходные, с разбросом не больше получаса. Регулярность важнее длительности сна. И 10–15 минут дневного света в первый час после подъёма — на улице, даже в пасмурную погоду.</p><p class=\"art-p\"><b>Кровать — только для сна.</b> Не лежать без сна: если не спится дольше 15–20 минут, встать и вернуться, когда начнёт клонить. В постели не работать и не листать телефон, на часы ночью не смотреть.</p><p class=\"art-p\"><b>Прохладная тёмная спальня.</b> Около 16–19 °C, дышащие ткани, одежда слоями. Это уменьшает пробуждения от приливов.</p><p class=\"art-p\"><b>Тёплый тусклый вечер.</b> За 30–60 минут до сна — приглушённый тёплый свет и без экранов.</p><h3 class=\"art-h\">Что убрать — это важнее, чем что добавить</h3><ul class=\"art-ul\"><li><b>Алкоголь вечером.</b> Он «ложный друг»: помогает уснуть, но режет вторую половину ночи и усиливает приливы — даже в небольших количествах.</li><li><b>Поздний кофе.</b> Кофе и крепкий чай — только до 14:00.</li><li><b>Поздний ужин.</b> Последняя тяжёлая еда — за три часа до сна.</li></ul><p class=\"art-p\">Движение днём сну помогает — но вечерний алкоголь эту пользу стирает.</p><h3 class=\"art-h\">А добавки?</h3><p class=\"art-p\">Их эффект скромный. <b>Магний</b> вечером — опора слабая; смысл есть, если его мало в еде (тыквенные семечки, зелень, бобовые). <b>Мелатонин</b> помогает в основном тем, у кого сон уже нарушен, и зависит от времени приёма — обсудите со специалистом. Валериана доказательно не подтверждается, а адаптогены вроде ашваганды мы не советуем: есть риски для печени и щитовидной железы.</p><h3 class=\"art-h\">Когда к врачу</h3><ul class=\"art-ul\"><li>Храп с паузами или ощущение удушья во сне, неосвежающий сон при достаточной длительности, засыпание днём — особенно за рулём. После менопаузы нарушения дыхания во сне часты и часто пропускаются.</li><li>Вечером непреодолимо тянет двигать ногами, а в движении легче — стоит проверить запасы железа (ферритин).</li><li>Плохой сон дольше трёх месяцев, несмотря на всё перечисленное.</li><li>Ночь дробят сильные приливы — их лечение улучшает и сон.</li></ul><h3 class=\"art-h\">Что попробовать на этой неделе</h3><ul class=\"art-ul\"><li>Вставать в одно и то же время все семь дней.</li><li>Не лежать без сна: не спится — встать и вернуться, когда клонит в сон.</li><li>Кофе — до 14:00, вечер без алкоголя.</li></ul><!--EV--><p class=\"art-p art-note\"><i>Это общие сведения, а не назначение. Обследование и лечение подбирает врач.</i></p>","codes":["P-F17","P-F3","P-F4"]},"energy":{"t":"Откуда берётся усталость после 40 и как вернуть силы","min":"5 минут чтения","h":"<p class=\"art-p\">Вроде бы спите, вроде бы едите как обычно, а сил нет с самого утра. К обеду хочется лечь, к вечеру — ничего не хочется. Первая мысль — «не хватает витаминов». Но чаще всего дело не в них.</p><h3 class=\"art-h\">Что чаще всего стоит за усталостью</h3><p class=\"art-p\">Снижение эстрогена действительно влияет на выносливость. Но усталость в этом возрасте гораздо чаще идёт от другого — и почти всё это можно проверить и поправить:</p><ul class=\"art-ul\"><li><b>Сон.</b> Рваные ночи накапливаются, и никакой кофе это не перекрывает.</li><li><b>Запасы железа.</b> Обильные месячные в переходе истощают запас, и усталость появляется задолго до того, как изменится обычный анализ крови.</li><li><b>Щитовидная железа.</b> Её отличает зябкость — в менопаузе обычно наоборот, жарко.</li><li><b>Настроение.</b> Когда ничего не радует больше двух недель, это не «просто устала».</li></ul><p class=\"art-p\">Поэтому начинать стоит не с баночек «для энергии», а с проверки.</p><h3 class=\"art-h\">Признаки, с которыми — на анализ, а не «бодриться»</h3><ul class=\"art-ul\"><li><b>Железо:</b> обильные месячные, одышка или сердцебиение на лестнице, выпадение волос, бледность, тянет грызть лёд, вечером беспокоят ноги → ферритин и анализ крови.</li><li><b>Щитовидная железа:</b> зябкость, запоры, редкий пульс, сухая кожа, отёчные веки, осиплость → ТТГ.</li><li><b>Витамин B12:</b> онемение или покалывание в руках и ногах, «ватные» ноги; риск выше на метформине, на препаратах от изжоги и у веганов → анализ на B12.</li><li><b>Дыхание во сне:</b> сон не освежает при достаточной длительности, храп с паузами → к сомнологу.</li></ul><p class=\"art-p\">⚠️ Отдельный случай: если после нагрузки на следующий день становится резко хуже — на часы или сутки, — наращивать нагрузку через силу нельзя. С этим — к врачу.</p><h3 class=\"art-h\">Что возвращает силы</h3><p class=\"art-p\"><b>Движение.</b> Самый сильный рычаг энергии из всех известных. Лучше всего работает сочетание: силовые тренировки, короткие интенсивные отрезки с полным отдыхом между ними и лёгкое кардио. Хуже всего — «всё время средне-тяжело». Хорошая новость: в первые годы после менопаузы тело особенно отзывчиво к тренировкам.</p><p class=\"art-p\"><b>Белок с утра.</b> Белковый завтрак в течение часа-двух после подъёма. Пропущенный завтрак и скачки сахара сами подстёгивают гормоны стресса — и днём наступает провал.</p><p class=\"art-p\"><b>Ходьба после еды.</b> 10–15 минут после основных приёмов пищи сглаживают «сахарные качели» и послеобеденную сонливость.</p><p class=\"art-p\"><b>Якорь сна.</b> Подъём в одно и то же время все семь дней и дневной свет утром. Иногда самое простое — лечь на полчаса раньше.</p><h3 class=\"art-h\">Что убрать</h3><p class=\"art-p\">Алкоголь, рафинированные сладости и ультраобработанная еда, хронический недосып, интенсивные тренировки без восстановления — убрать эти «утечки энергии» важнее, чем что-то добавить.</p><h3 class=\"art-h\">А добавки?</h3><p class=\"art-p\">Еда и движение сильнее любой из них. <b>Железо</b> — только по анализу на ферритин, не вслепую. <b>Витамин D</b> можно и без анализа. Магний и витамины группы B добавляют энергии, только если их не хватает. Модные «бустеры молодости» (NMN, NR и подобные) у людей энергию в исследованиях не улучшили — мы их не советуем.</p><h3 class=\"art-h\">Когда к врачу</h3><ul class=\"art-ul\"><li>Усталость дольше четырёх недель, несмотря на сон и движение.</li><li>Усталость вместе с необъяснимой потерей веса, проливным ночным потом или увеличенными лимфоузлами.</li><li>Одышка, боль в груди или сердцебиение — срочно.</li></ul><h3 class=\"art-h\">Что попробовать на этой неделе</h3><ul class=\"art-ul\"><li>Источник белка в каждом приёме пищи, начиная с завтрака.</li><li>10–15 минут ходьбы после основных приёмов пищи.</li><li>Две силовые тренировки по 30–40 минут в разные дни.</li></ul><!--EV--><p class=\"art-p art-note\"><i>Это общие сведения, а не назначение. Обследование и лечение подбирает врач.</i></p>","codes":["P-F5","P-F22","P-F4","P-F17"]},"mood":{"t":"Перепады настроения, тревога и раздражительность: что происходит","min":"5 минут чтения","h":"<p class=\"art-p\">«Я себя не узнаю». Срываетесь из-за мелочи, плачете без причины, тревога накрывает на ровном месте, а то, что раньше радовало, стало безразличным. Это не характер испортился. В переходе так бывает у очень многих — и этому есть объяснение.</p><h3 class=\"art-h\">Почему качает</h3><p class=\"art-p\">Эстроген поддерживает вещества мозга, отвечающие за настроение и удовольствие. В перименопаузе он не просто падает, а качается — и раскачивает настроение именно амплитуда этих качелей. Вдобавок уходит прогестерон, а с ним — естественный «успокоитель» мозга. Отсюда тревога, раздражительность, вспышки гнева, слёзы, ощущение, что выдерживать нагрузку стало труднее.</p><p class=\"art-p\">Раздражительность и гнев часто выражены сильнее грусти. Это гормональная картина, а не «плохой характер».</p><p class=\"art-p\">И важное, чтобы не пугаться: у большинства женщин это проходящая реакция. Обычно пик приходится на перименопаузу, а после всё стихает. Внимательнее стоит быть тем, у кого раньше уже были тяжёлые периоды подавленности.</p><h3 class=\"art-h\">Как понять, что именно происходит</h3><p class=\"art-p\">Ключ — в том, <b>когда</b> бывает плохо:</p><ul class=\"art-ul\"><li><b>только в последнюю неделю перед месячными</b> и проходит в первые дни после начала;</li><li><b>весь месяц</b>, но перед месячными становится хуже;</li><li><b>весь месяц</b> без связи с циклом.</li></ul><p class=\"art-p\">От этого зависит, что поможет. А различить можно только дневником хотя бы за два цикла — память задним числом всё сваливает на «перед месячными». Отмечайте настроение и первый день месячных в VIA-L — через пару месяцев рисунок будет виден.</p><h3 class=\"art-h\">Что помогает</h3><p class=\"art-p\"><b>Сон.</b> Рваный сон и накопленная усталость усиливают гормональные качели настроения. Если сон рваный — начните с него.</p><p class=\"art-p\"><b>Движение.</b> Самый доказанный рычаг, для многих сравнимый по силе с лекарством. Около 150 минут в неделю: ходьба, силовые, а мягкие практики вроде йоги и тай-чи сильнее всего снимают тревогу. Силовые особенно помогают женщинам.</p><p class=\"art-p\"><b>Утренний свет.</b> Яркий дневной свет сразу после подъёма заметно поднимает настроение в перименопаузе. Прогулка при дневном свете — простой ежедневный шаг.</p><p class=\"art-p\"><b>Медленное дыхание.</b> 5–10 минут в день с удлинённым выдохом — около шести вдохов в минуту. Действует на тревогу напрямую, без «силы воли».</p><p class=\"art-p\"><b>Еда.</b> Средиземноморский стиль, клетчатка, ферментированные продукты, белковый завтрак. Магний лучше получать из еды — тёмная зелень, тыквенные семечки, бобовые; добавка имеет смысл, если в рационе его мало.</p><h3 class=\"art-h\">Что убрать</h3><ul class=\"art-ul\"><li><b>Алкоголь.</b> Успокаивает на час, а потом тревога возвращается сильнее — в перименопаузе особенно.</li><li><b>Много кофе.</b> Кофеин раскручивает тревогу и усиливает приливы — только до полудня.</li><li><b>«Стресс-формулы» с витамином B6</b> при долгом приёме небезопасны.</li></ul><h3 class=\"art-h\">Что может предложить врач</h3><p class=\"art-p\">Если подавленность или тревога мешают жить, основа помощи — психотерапия (в том числе программы именно для менопаузы) и, при необходимости, лекарства. В перименопаузе, особенно вместе с приливами, настроению может помочь и гормональная терапия — это решает врач.</p><h3 class=\"art-h\">Когда за помощью — сразу</h3><ul class=\"art-ul\"><li>Любые мысли о том, чтобы причинить себе вред, или что «лучше не жить», — немедленно к специалисту или на линию кризисной помощи. Это не то, что можно переждать.</li><li>Подавленность или потеря интереса почти каждый день дольше двух недель, тревога, мешающая жить и работать, — к врачу в ближайшие дни.</li><li>Спите заметно меньше, а сил при этом много, речь ускорилась, тянет на импульсивные траты и решения — к врачу.</li></ul><h3 class=\"art-h\">Что попробовать на этой неделе</h3><ul class=\"art-ul\"><li>Прогулка при дневном свете в первый час после подъёма.</li><li>Вставать в одно и то же время все семь дней.</li><li>Отмечать настроение и первый день месячных в VIA-L.</li></ul><!--EV--><p class=\"art-p art-note\"><i>Это общие сведения, а не назначение. Обследование и лечение подбирает врач.</i></p>","codes":["P-F9","P-F4","P-F17"]},"fog":{"t":"«Туман» в голове: забываю слова, теряю мысль — что со мной?","min":"4 минуты чтения","h":"<p class=\"art-p\">Входите в комнату и не помните зачем. Имя знакомого «вертится на языке». Мысль ускользает посреди фразы. Многие женщины в переходе пугаются: «неужели память начинает сдавать?» Давайте спокойно разберёмся.</p><h3 class=\"art-h\">Это реально — и это проходит</h3><p class=\"art-p\">Эстроген питает мозг: участки, отвечающие за память и речь, и то, как мозг получает энергию. Поэтому «туман» в переходе — не выдумка. Чаще всего он задевает подбор слов, скорость и запоминание услышанного.</p><p class=\"art-p\">Но вот что важно знать:</p><ul class=\"art-ul\"><li>по большим исследованиям этот туман <b>лёгкий</b> и обычно <b>проходит</b> после менопаузы;</li><li>это <b>не начало болезни памяти</b> — в этом возрасте такие болезни очень редки;</li><li>ощущение тумана обычно <b>сильнее</b>, чем то, что показывают тесты.</li></ul><h3 class=\"art-h\">Что раздувает туман сильнее всего</h3><p class=\"art-p\"><b>Тревога и настроение.</b> Сама мысль «не схожу ли я с ума» ухудшает концентрацию — и круг замыкается. Часто туман идёт именно от тревоги, а не от «слабой памяти».</p><p class=\"art-p\"><b>Недосып.</b> Рваные ночи бьют по вниманию сильнее, чем кажется.</p><p class=\"art-p\"><b>Перегруз.</b> Десять дел одновременно — и мозг теряет нить. Одна задача за раз — простой и рабочий приём.</p><h3 class=\"art-h\">Что стоит проверить</h3><p class=\"art-p\">Не всё стоит списывать на менопаузу. С этими сигналами — к врачу на проверку:</p><ul class=\"art-ul\"><li><b>Щитовидная железа</b> — зябкость, запоры, редкий пульс → ТТГ.</li><li><b>Витамин B12</b> — онемение или покалывание в руках и ногах; риск выше на метформине, на препаратах от изжоги и у веганов.</li><li><b>Запасы железа</b> — если месячные обильные → ферритин.</li><li><b>Дыхание во сне</b> — сон не освежает, есть храп.</li><li><b>Лекарства.</b> Некоторые антигистаминные «для сна», снотворные и средства от частых позывов к мочеиспусканию притупляют память и внимание. Не отменяйте сами — обсудите с врачом замену.</li><li><b>Слух.</b> Снижение слуха — заметный фактор для мозга, и его можно поправить.</li></ul><h3 class=\"art-h\">Что помогает мозгу</h3><p class=\"art-p\"><b>Движение.</b> Самый сильный рычаг: и ходьба, и силовые тренировки улучшают внимание и способность держать в голове несколько задач.</p><p class=\"art-p\"><b>Сон.</b> Начните с него — туман чаще идёт от недосыпа.</p><p class=\"art-p\"><b>Еда.</b> Средиземноморский стиль, жирная рыба (именно рыба, а не капсулы), яйца, ягоды.</p><p class=\"art-p\"><b>Сердце и сосуды.</b> Давление, сахар, талия — то, что хорошо для сердца, хорошо и для мозга. Меньше алкоголя.</p><p class=\"art-p\"><b>Общение и новое.</b> Социальная и умственная активность поддерживают мозг.</p><h3 class=\"art-h\">А добавки «для памяти»?</h3><p class=\"art-p\">Готовые добавки «для памяти» пользы не показали — ни гинкго, ни модные «ноотропы». <b>Креатин</b> в исследованиях даёт небольшое улучшение памяти — заметнее всего при недосыпе и у людей старше 65; у женщин в пери- и менопаузе есть первое небольшое исследование, где реакция стала быстрее, но результат пока не повторили. При болезни почек — только после разговора с врачом.</p><h3 class=\"art-h\">Когда к врачу без промедления</h3><p class=\"art-p\">Это уже не обычный туман, если:</p><ul class=\"art-ul\"><li>становится трудно справляться с привычным — деньгами, лекарствами, дорогой в знакомых местах;</li><li>близкие замечают ухудшение сильнее, чем вы сами;</li><li>становится хуже месяц за месяцем, без «хороших дней»;</li><li>вы повторяете один и тот же вопрос, не замечая этого, или путаете смысл слов.</li></ul><h3 class=\"art-h\">Что попробовать на этой неделе</h3><ul class=\"art-ul\"><li>Вставать в одно и то же время все семь дней — сначала сон.</li><li>Две силовые тренировки по 30–40 минут в разные дни.</li><li>Одна задача за раз: важные дела — по одному, без переключений.</li></ul><!--EV--><p class=\"art-p art-note\"><i>Это общие сведения, а не назначение. Обследование и лечение подбирает врач.</i></p>","codes":["P-F10","P-F9","P-F17"]},"weight":{"t":"Почему растёт талия, даже если вес почти не меняется","min":"5 минут чтения","h":"<p class=\"art-p\">Ешь как раньше, а джинсы не сходятся. Весы показывают почти то же, а живот — другой. Знакомо многим женщинам в переходе. И это не «слабая воля» — у тела здесь своя логика.</p><h3 class=\"art-h\">Что происходит</h3><p class=\"art-p\">Когда снижается эстроген, тело хуже отвечает на сахар, а жир начинает откладываться не на бёдрах, а вокруг талии — в переходе примерно на 6% больше каждый год. Отсюда три вещи, которые кажутся отдельными, но на деле — одна цепочка:</p><ul class=\"art-ul\"><li>тяга к сладкому и провалы сил после еды;</li><li>«туман» после обеда;</li><li>растущая талия при прежнем весе.</li></ul><p class=\"art-p\">Провал после еды и тяга к сладкому — это реакция тела на скачок и падение сахара, а не характер.</p><h3 class=\"art-h\">Мерить талию, а не вес</h3><p class=\"art-p\">В переходе вес может почти не меняться, а жир вокруг талии — расти. Поэтому на весы смотреть мало толку. Самый надёжный домашний ориентир — <b>талия меньше половины роста</b>: например, при росте 166 см — меньше 83 см. Окружность талии около 88 см — сигнал присмотреться (для азиатского телосложения — около 80 см). Это ориентир, а не приговор.</p><h3 class=\"art-h\">Что сильнее всего влияет</h3><p class=\"art-p\"><b>Недосып.</b> Даже час-два недосыпа заметно ухудшают то, как тело справляется с сахаром, — у женщин в менопаузе особенно. Сон — это рычаг обмена, а не только отдых.</p><p class=\"art-p\"><b>Мало мышечной нагрузки.</b> Мышца — главный «потребитель» сахара. Чем её меньше, тем труднее телу.</p><p class=\"art-p\"><b>Скачки сахара после еды.</b> Их можно заметно сгладить — порядком еды и движением.</p><h3 class=\"art-h\">Что делать</h3><p class=\"art-p\"><b>Овощи и белок — раньше углеводов.</b> Начинать еду с овощей и белка, хлеб, крупу или сладкое — после. Это сглаживает скачок сахара примерно на треть.</p><p class=\"art-p\"><b>Ходьба после еды.</b> 10–15 минут сразу после еды — отдельный путь, которым мышцы забирают сахар. Работает вместе с порядком еды.</p><p class=\"art-p\"><b>Силовые тренировки.</b> Главный рычаг в менопаузе: мышца забирает сахар и не даёт себе таять с возрастом.</p><p class=\"art-p\"><b>Белок в каждый приём и клетчатка.</b> Белок даёт сытость и держит мышцы, клетчатка из овощей, бобовых и цельных злаков сглаживает сахар.</p><p class=\"art-p\"><b>Ранний ужин.</b> Вечером сахар держится выше, поэтому основная еда лучше раньше. Но жёсткие голодовки женщинам в переходе не на пользу.</p><p class=\"art-p\"><b>Меньше рафинированного сахара, сладких напитков и алкоголя.</b></p><h3 class=\"art-h\">О печени</h3><p class=\"art-p\">Частый молчаливый спутник растущей талии — жир в печени. Обычно он ничем не проявляет себя, а обычные печёночные анализы могут быть в порядке. Никаких «чисток» и «детоксов» не нужно — работают те же шаги: талия, цельная еда, силовые, меньше сахара и алкоголя. Оценить риск может врач.</p><h3 class=\"art-h\">А добавки для похудения?</h3><p class=\"art-p\">У добавок «для похудения» опоры нет, а смеси с экстрактом зелёного чая могут вредить печени. Работают белок в каждый приём и клетчатка из еды.</p><h3 class=\"art-h\">Когда к врачу</h3><p class=\"art-p\">Сильная жажда, частое мочеиспускание, резкое похудение без причины, эпизоды дурноты — это повод показаться врачу и проверить сахар.</p><h3 class=\"art-h\">Что попробовать на этой неделе</h3><ul class=\"art-ul\"><li>Начинать еду с овощей и белка, углеводы — после.</li><li>10–15 минут ходьбы после основных приёмов пищи.</li><li>Одна силовая тренировка на этой неделе — а лучше две.</li></ul><!--EV--><p class=\"art-p art-note\"><i>Это общие сведения, а не назначение. Обследование и лечение подбирает врач.</i></p>","codes":["P-F7","P-F1","P-F8"]},"pain":{"t":"Ноют суставы, по утрам скованность: что это и как помочь телу","min":"5 минут чтения","h":"<p class=\"art-p\">Утром встаёте — и тело как деревянное. Ноют колени, пальцы, плечи, хотя ничего не случилось. Часто это списывают на «возраст». Но у такой ломоты в переходе есть понятная причина — и понятные шаги.</p><h3 class=\"art-h\">Почему болит</h3><p class=\"art-p\">Эстроген действует по всей опорно-двигательной системе — в костях, суставах, связках и мышцах. Когда его становится меньше, это чувствуется сразу везде. Ломота и скованность в суставах <b>без припухлости</b> бывают у больше чем половины женщин в переходе. Это часть перехода, а не «просто возраст».</p><p class=\"art-p\">Вдобавок снижение эстрогена снимает естественный «тормоз» фонового воспаления — поэтому суставы, сон, усталость и настроение часто тянут друг друга за собой.</p><p class=\"art-p\">Отдельная частая история в 50–60 лет — «замороженное плечо»: руку трудно поднять и самой, и с чьей-то помощью. С этим — к физиотерапевту или ортопеду.</p><h3 class=\"art-h\">Беречься или двигаться?</h3><p class=\"art-p\">Двигаться. Силовые тренировки и регулярное движение — основа для суставов, мышц и костей.</p><h3 class=\"art-h\">Что помогает</h3><p class=\"art-p\"><b>Силовые тренировки 2–3 раза в неделю, без боли.</b> Это основа и для суставов, и для мышц, и для костей. Сочетание силовых с ходьбой или другим кардио — лучшее. С тренером защита для костей заметно выше, а под присмотром даже интенсивные силовые безопасны.</p><p class=\"art-p\"><b>Немного прыжков и ударной нагрузки</b> — если суставы позволяют. Именно такая нагрузка лучше всего поддерживает кости бедра и позвоночника.</p><p class=\"art-p\"><b>Баланс и подвижность.</b> Упражнения на равновесие — профилактика падений, а значит, и переломов.</p><p class=\"art-p\"><b>Белок в каждый приём пищи.</b> После 40 мышца хуже отвечает на белок и нагрузку — нужно больше и того, и другого.</p><p class=\"art-p\"><b>Средиземноморский стиль.</b> Жирная рыба, оливковое масло, ягоды, овощи и цельные злаки снижают фоновое воспаление; переработанное мясо, сладкие напитки и ультраобработанная еда его разгоняют.</p><h3 class=\"art-h\">О костях — то, что не болит</h3><p class=\"art-p\">Кость теряется быстрее всего примерно за год до последних месячных и два года после, и никаких симптомов нет до самого перелома. Косвенные сигналы: вы стали ниже ростом больше чем на 4 см по сравнению с молодостью, появилась сутулость, ослаб хват. Если есть факторы риска — менопауза до 45, перелом от лёгкой травмы, долгий приём стероидов, перелом бедра у родителей, — стоит обсудить с врачом денситометрию уже сейчас. Если риск высокий, у врача есть средства, которые заметно снижают риск переломов.</p><h3 class=\"art-h\">А добавки?</h3><ul class=\"art-ul\"><li><b>Кальций</b> — лучше едой: йогурт, сыр, сардины с костями, тофу. Пищевой кальций безопасен, а большие дозы добавок спорны.</li><li><b>Витамин D</b> можно и без анализа.</li><li><b>Коллаген</b> мышцам не помогает.</li></ul><h3 class=\"art-h\">Когда к врачу без промедления</h3><ul class=\"art-ul\"><li>Сустав припух, горячий или покраснел; болят симметрично мелкие суставы кистей; утренняя скованность держится дольше получаса-часа и проходит в движении — к ревматологу: здесь важно не упустить первые месяцы.</li><li>Внезапная боль в спине от обычного движения — кашля, поворота в кровати — вместе с потерей роста.</li><li>Любой перелом от лёгкой травмы.</li><li>Боль в спине, которая будит ночью, вместе с температурой или необъяснимой потерей веса.</li><li>Онемение в промежности, слабость в обеих ногах, проблемы с мочеиспусканием — неотложно.</li></ul><h3 class=\"art-h\">Что попробовать на этой неделе</h3><ul class=\"art-ul\"><li>Две силовые тренировки по 30–40 минут в разные дни; основа — приседания, тяги и жимы, без боли.</li><li>Источник белка в каждом приёме пищи.</li><li>Кальций — едой: йогурт, сыр, сардины с костями или тофу каждый день.</li></ul><!--EV--><p class=\"art-p art-note\"><i>Это общие сведения, а не назначение. Обследование и лечение подбирает врач.</i></p>","codes":["P-F12","P-F8"]},"muscle":{"t":"Мышцы после 40: почему слабеют и как их сохранить","min":"4 минуты чтения","h":"<p class=\"art-p\">Тяжелее поднять сумку, труднее встать с низкого дивана, подъём по лестнице сбивает дыхание. Мышцы с возрастом незаметно тают — и в переходе этот процесс ускоряется. Хорошая новость: мышца отзывчива в любом возрасте, и вернуть силу реально.</p><h3 class=\"art-h\">Что происходит</h3><p class=\"art-p\">Эстроген помогает мышцам, и когда его становится меньше, мышца хуже отвечает и на белок, и на нагрузку. Проще говоря, после 40 нужно <b>больше</b> и того, и другого, чтобы получить тот же результат.</p><p class=\"art-p\">Почему это важно не только для фигуры:</p><ul class=\"art-ul\"><li>мышца — главный «потребитель» сахара, и чем её больше, тем легче обмену;</li><li>мышца — «завод энергии»: с ней меньше усталости;</li><li>слабость ведёт к падениям, а падения — к переломам.</li></ul><h3 class=\"art-h\">Что работает</h3><p class=\"art-p\"><b>Силовые тренировки 2–3 раза в неделю.</b> Это главное. Основа — приседания, тяги и жимы, без боли. Нагрузка должна быть ощутимой: последние повторения даются с усилием. С тренером результат и безопасность выше.</p><p class=\"art-p\"><b>Белок — больше, чем кажется.</b> Ориентир — 30–40 г белка в каждый приём пищи, начиная с завтрака: обычно там его меньше всего. Это, например, порция творога или греческого йогурта с яйцами, кусок рыбы или курицы, тарелка чечевицы с тофу. В сумме за день стоит стремиться минимум к 1–1,2 г белка на килограмм веса, а при силовых тренировках — больше.</p><p class=\"art-p\"><b>Движение каждый день.</b> Ходьба, лестницы, работа по дому — в дополнение к силовым, а не вместо.</p><p class=\"art-p\"><b>Баланс.</b> Упражнения на равновесие защищают от падений.</p><h3 class=\"art-h\">А добавки?</h3><ul class=\"art-ul\"><li><b>Белковый порошок</b> — удобен, если едой не получается добрать белок. Это еда, а не лекарство.</li><li><b>Креатин</b> лучше всего изучен в паре с силовыми: небольшая, но реальная прибавка силы и мышц, в том числе у женщин после менопаузы. Без тренировок данные противоречивы. При болезни почек — только после разговора с врачом. Креатинин в анализе при приёме слегка растёт — это не повреждение почек.</li><li><b>Коллаген</b> мышцам не помогает.</li></ul><h3 class=\"art-h\">Когда к врачу</h3><ul class=\"art-ul\"><li>Слабость нарастает быстро, без понятной причины.</li><li>Было падение или перелом от лёгкой травмы.</li><li>Трудно встать со стула без помощи рук, а раньше получалось.</li></ul><h3 class=\"art-h\">Что попробовать на этой неделе</h3><ul class=\"art-ul\"><li>Две силовые тренировки по 30–40 минут в разные дни.</li><li>Источник белка в каждом приёме пищи — начните с завтрака.</li><li>Каждый день хотя бы один подъём по лестнице вместо лифта.</li></ul><!--EV--><p class=\"art-p art-note\"><i>Это общие сведения, а не назначение. Обследование и лечение подбирает врач.</i></p>","codes":["P-F12","P-F5"]},"libido_f":{"t":"Желание и близость в переходе: что меняется и как вернуть комфорт","min":"5 минут чтения","h":"<p class=\"art-p\">Желание стало приходить реже, близость иногда неприятна или больно, и об этом неловко говорить даже с врачом. Вы не одна: это одна из самых частых перемен в переходе — и одна из самых решаемых.</p><h3 class=\"art-h\">Что меняется с желанием</h3><p class=\"art-p\">В переходе часто уходит <b>спонтанное</b> желание — то, что возникает «само». Это не поломка. У многих женщин желание <b>ответное</b>: оно приходит уже в процессе близости, а не до неё, — и это здоровый вариант.</p><p class=\"art-p\">На желание влияют не только гормоны. Сильнее всего мешают:</p><ul class=\"art-ul\"><li><b>усталость и недосып</b> — когда сил нет, желания тоже нет;</li><li><b>настроение и стресс</b>;</li><li><b>отношения</b> — то, что происходит между людьми, а не только в теле;</li><li><b>лекарства</b> — например, некоторые антидепрессанты снижают желание; если подозреваете это, обсудите с врачом;</li><li><b>сухость и дискомфорт</b> — о них отдельно.</li></ul><h3 class=\"art-h\">Сухость и дискомфорт: терпеть не нужно</h3><p class=\"art-p\">Сухость, жжение, боль при близости, частые позывы или повторяющиеся циститы бывают у половины женщин после менопаузы и больше. Но о них почти не говорят: лишь примерно половина рассказывает врачу, а большинство не знает, что с этим можно справиться.</p><p class=\"art-p\">Важно знать: в отличие от приливов, это <b>само не проходит</b> и со временем усиливается. Зато хорошо поддаётся помощи. И ещё одно: боль ведёт к избеганию близости, а избегание — к спаду желания. Убрать дискомфорт — часто значит вернуть и желание.</p><h3 class=\"art-h\">Что можно начать сразу, без рецепта</h3><p class=\"art-p\"><b>Увлажнитель и лубрикант — это разные вещи.</b> Их постоянно путают:</p><ul class=\"art-ul\"><li><b>вагинальный увлажнитель</b> применяют регулярно, 2–3 раза в неделю, независимо от близости — он удерживает влагу в тканях;</li><li><b>лубрикант</b> — только в момент близости, чтобы снизить трение. Водный или силиконовый, без отдушек и «согревающих» добавок.</li></ul><p class=\"art-p\">Регулярность значит не меньше, чем само средство: «дорогое» не значит «работающее».</p><p class=\"art-p\"><b>Тренировки мышц тазового дна</b> и регулярная близость или стимуляция поддерживают кровоток и комфорт.</p><p class=\"art-p\"><b>Убрать раздражители:</b> интимное мыло и гели, спринцевание, ароматизированные средства, тесное синтетическое бельё. Пить достаточно воды, не курить.</p><h3 class=\"art-h\">Что может предложить врач</h3><p class=\"art-p\">Если увлажнителя и лубриканта мало — стоит поговорить с гинекологом. Есть местные средства, в том числе с низкой дозой эстрогена: они действуют на месте, почти не всасываются в кровь и, по многим исследованиям, заметно уменьшают и сухость, и мочевые симптомы. Есть и негормональные варианты. Какой подходит вам, решает врач.</p><h3 class=\"art-h\">Что не помогает</h3><ul class=\"art-ul\"><li><b>Добавки «для либидо»</b> и «для увлажнения изнутри» — опоры нет.</li><li><b>«Лазерное омоложение»</b> и радиочастотные процедуры, которые активно продают клиники: в исследованиях, где их сравнивали с имитацией процедуры, разницы не было. Это дорого и не доказано.</li></ul><h3 class=\"art-h\">Когда к врачу</h3><ul class=\"art-ul\"><li><b>Любое кровотечение или мазня после менопаузы</b> — даже капля, даже после близости. Чаще всего причина безобидная, но показаться нужно всегда.</li><li>Сильный зуд, белые пятна, трещины или язвочки, которые не проходят от увлажнителя, — к гинекологу.</li><li>Циститы повторяются, или есть температура с болью в пояснице.</li></ul><h3 class=\"art-h\">Что попробовать на этой неделе</h3><ul class=\"art-ul\"><li>Сон и отдых — первое: лечь на полчаса раньше хотя бы три вечера.</li><li>Если есть сухость — начать вагинальный увлажнитель 2–3 раза в неделю, а для близости — лубрикант.</li><li>Несколько минут упражнений для мышц тазового дна каждый день.</li></ul><!--EV--><p class=\"art-p art-note\"><i>Это общие сведения, а не назначение. Обследование и лечение подбирает врач.</i></p>","codes":["P-F15","P-F9","P-F20"]},"cycle":{"t":"Цикл после 35: обильнее, реже, непредсказуемее — что происходит","min":"5 минут чтения","h":"<p class=\"art-p\">Месячные то приходят через три недели, то пропадают на два месяца. Стали обильнее и длиннее, появились сгустки. Прокладки не хватает на ночь. В 35–50 лет такие перемены очень часты — это одна из первых примет перехода. Но «частое» не значит «терпеть».</p><h3 class=\"art-h\">Почему цикл меняется</h3><p class=\"art-p\">В переходе всё больше циклов проходит без овуляции, и прогестерона становится меньше. Эстроген в это время не падает, а качается — иногда выше обычного. Отсюда и непредсказуемость, и более обильные месячные.</p><p class=\"art-p\">Если у вас кольцо или часы: подъём ночной температуры после овуляции они видят задним числом. Если подъёма в цикле не было, это не значит «мало прогестерона» — после 40 часть циклов просто проходит без овуляции.</p><h3 class=\"art-h\">Что считать обильным</h3><p class=\"art-p\">Обильные месячные часто считают «моей особенностью» и годами не проверяют. Ориентиры:</p><ul class=\"art-ul\"><li>прокладку или тампон приходится менять <b>каждый час несколько часов подряд</b>;</li><li>сгустки крупнее монеты;</li><li>протекания, нужна «двойная защита»;</li><li>месячные дольше 7 дней;</li><li>кровотечение ограничивает обычный день.</li></ul><h3 class=\"art-h\">Обильные месячные и железо</h3><p class=\"art-p\">Обильные месячные — самая частая причина нехватки железа у женщин. Запасы железа падают раньше, чем меняется обычный анализ крови, и усталость, одышка на лестнице, выпадение волос, ломкие ногти, зябкость появляются уже тогда. Особые подсказки: тянет грызть лёд и вечером беспокоят ноги.</p><p class=\"art-p\"><b>Что делать:</b></p><ul class=\"art-ul\"><li><b>Попросить анализ на ферритин</b> — это главный показатель запасов. Железо — по анализу, не вслепую: избыток железа тоже вреден.</li><li><b>Еда с железом.</b> Лучше всего усваивается железо из мяса, птицы, рыбы и морепродуктов. Растительное — чечевицу, фасоль, тофу, тыквенные семечки, тёмную зелень — сочетать с витамином C в тот же приём: болгарский перец, цитрусы, киви.</li><li><b>Чай, кофе и молочное — отдельно</b> от еды с железом, примерно через час: они мешают его усвоению.</li></ul><p class=\"art-p\">И главное: обильные месячные решаются. У гинеколога есть варианты, которые снижают кровопотерю в разы. Железо без работы с причиной — заплатка, а не решение.</p><h3 class=\"art-h\">Отмечать — это половина дела</h3><p class=\"art-p\">Отмечайте первый день месячных в VIA-L. Через несколько циклов видно, как меняется длина цикла, и с этим проще идти к врачу. А ещё дневник помогает понять, как цикл связан со сном, настроением и приливами.</p><h3 class=\"art-h\">Что не нужно</h3><ul class=\"art-ul\"><li><b>Наборы добавок «по фазам цикла»</b> — маркетинг: приём по фазам не лучше ежедневного.</li><li><b>«Семена по фазам»</b> — клинических данных нет. Семена полезны как еда, но ротация по дням ничего не меняет.</li></ul><h3 class=\"art-h\">Когда к врачу без промедления</h3><ul class=\"art-ul\"><li>Прокладку или тампон приходится менять каждый час несколько часов подряд.</li><li>Месячные дольше 8 дней.</li><li>Кровь между месячными или после близости.</li><li>Кровотечение вместе с сильной усталостью, одышкой, дурнотой, обмороками.</li><li><b>Любое кровотечение после 12 месяцев без месячных</b> — всегда повод быстро показаться гинекологу.</li></ul><h3 class=\"art-h\">Что попробовать на этой неделе</h3><ul class=\"art-ul\"><li>Отмечать первый день месячных в VIA-L.</li><li>При обильных месячных — еда с железом вместе с витамином C; чай и кофе — через час после.</li><li>Если узнали себя в «обильных» — записаться к гинекологу и попросить анализ на ферритин.</li></ul><!--EV--><p class=\"art-p art-note\"><i>Это общие сведения, а не назначение. Обследование и лечение подбирает врач.</i></p>","codes":["P-F22","P-F3","P-F1"]},"evening":{"t":"Кофе до 14:00, вечер без алкоголя, ранний ужин: почему это работает","min":"3 минуты чтения","h":"<p class=\"art-p\">Это один из самых простых шагов «Фокуса недели» — и один из самых действенных для сна. Он не про то, чтобы что-то добавить, а про то, чтобы убрать три вещи, которые незаметно портят ночь.</p><h3 class=\"art-h\">Почему это работает</h3><p class=\"art-p\"><b>Кофе держит тело «включённым».</b> Кофеин поднимает гормоны стресса и не даёт им опуститься к вечеру. Действует он долго, поэтому чашка в четыре часа дня мешает заснуть в полночь. Граница — около 14:00, то есть за 8–9 часов до сна.</p><p class=\"art-p\"><b>Алкоголь — «ложный друг».</b> Бокал вечером помогает уснуть, но режет вторую половину ночи: больше пробуждений, хуже восстановление. Он усиливает приливы даже в небольших количествах, а в перименопаузе раскачивает тревогу — успокаивает на час, а потом становится хуже.</p><p class=\"art-p\"><b>Поздний ужин мешает телу остыть и успокоиться.</b> Последняя тяжёлая еда — за три часа до сна.</p><h3 class=\"art-h\">Как делать</h3><ul class=\"art-ul\"><li><b>Кофе и крепкий чай — только до 14:00.</b> После — травяной чай, вода, кофе без кофеина.</li><li><b>Алкоголь вечером — пауза на неделю.</b> Не навсегда, а на неделю — чтобы увидеть разницу на себе.</li><li><b>Ужин — за три часа до сна.</b> Если ложитесь в 23:00 — ужин до 20:00.</li></ul><h3 class=\"art-h\">Что может мешать</h3><ul class=\"art-ul\"><li>Привычка «кофе после обеда, чтобы не уснуть». Вместо него — 10 минут ходьбы на улице.</li><li>Бокал вина «чтобы расслабиться». Попробуйте замену-ритуал: тёплый душ, прогулка, медленное дыхание.</li><li>Поздний приход с работы. Тогда — лёгкий ужин, а основная еда раньше, днём.</li></ul><h3 class=\"art-h\">Чего ждать</h3><p class=\"art-p\">Смотрите не на одну ночь, а на неделю: как быстро засыпаете, сколько раз просыпаетесь, как себя чувствуете утром. Отмечайте сон и приливы в VIA-L — так разница будет видна в цифрах, а не только по ощущениям.</p><h3 class=\"art-h\">Кому этот шаг помогает</h3><p class=\"art-p\">Тем, у кого плохой сон, ночные приливы и утренняя усталость. Он часто идёт в паре с шагом «Подъём в одно время и утренний свет».</p><!--EV--><p class=\"art-p art-note\"><i>Это общие сведения, а не назначение.</i></p>","codes":["P-F17","P-F4","P-F9"]},"wake":{"t":"Подъём в одно время и утренний свет: якорь для всего дня","min":"3 минуты чтения","h":"<p class=\"art-p\">Кажется, что сон начинается вечером. На самом деле он начинается утром — с того, во сколько вы встаёте и видите свет. Это самый сильный поведенческий рычаг для сна, настроения и сил, и он не стоит ничего.</p><h3 class=\"art-h\">Почему это работает</h3><p class=\"art-p\">У тела есть внутренние часы. Они решают, когда вам бодро, а когда хочется спать, и сверяются в первую очередь с двумя сигналами: <b>временем подъёма</b> и <b>дневным светом утром</b>. Когда эти сигналы каждый день разные, часы сбиваются: вечером мозг не выключается, утром не разгоняется. В переходе это чувствуется особенно сильно.</p><p class=\"art-p\"><b>Регулярность подъёма важнее длительности сна.</b> Выходные «отоспаться» до обеда снова сбивают часы.</p><p class=\"art-p\"><b>Утренний свет — самый сильный сигнал часам.</b> 10–15 минут на улице работают даже в пасмурную погоду — это сильнее любой лампы. А яркий утренний свет ещё и заметно поднимает настроение в перименопаузе.</p><h3 class=\"art-h\">Как делать</h3><ul class=\"art-ul\"><li><b>Вставать в одно и то же время все семь дней</b>, включая выходные, с разбросом не больше получаса.</li><li><b>В первый час после подъёма — 10–15 минут дневного света.</b> Прогулка, кофе на балконе, дорога пешком.</li><li><b>Вечером — наоборот:</b> за 30–60 минут до сна тёплый приглушённый свет и без экранов.</li></ul><h3 class=\"art-h\">Что может мешать</h3><ul class=\"art-ul\"><li>Плохая ночь. Даже после неё вставайте в обычное время — так следующая ночь будет лучше.</li><li>Тёмное зимнее утро. Выйдите на улицу, как только рассвело, или проведите первые минуты у окна.</li><li>Выходные. Можно позволить себе полчаса, но не три часа.</li></ul><h3 class=\"art-h\">Чего ждать</h3><p class=\"art-p\">Часы перестраиваются не за одну ночь. Оценивайте по неделе-двум: как засыпаете, как просыпаетесь, какое настроение утром. Отмечайте сон и самочувствие в VIA-L.</p><h3 class=\"art-h\">Кому этот шаг помогает</h3><p class=\"art-p\">Тем, у кого трудное засыпание, пробуждения среди ночи, утренняя разбитость, перепады настроения и «туман». Хорошо работает вместе с шагом «Кофе до 14:00, вечер без алкоголя».</p><!--EV--><p class=\"art-p art-note\"><i>Это общие сведения, а не назначение.</i></p>","codes":["P-F4","P-F17","P-F9"]},"strength":{"t":"Силовые тренировки дважды в неделю: один шаг — польза сразу для всего","min":"4 минуты чтения","h":"<p class=\"art-p\">Если бы из всех советов для перехода можно было выбрать только один, это были бы силовые тренировки. Они работают сразу на приливы, настроение, кости, мышцы, обмен и сон. И для этого не нужен спортзал.</p><h3 class=\"art-h\">Почему это работает</h3><ul class=\"art-ul\"><li><b>Приливы.</b> Силовые — самый сильный рычаг без лекарств: в лучшем исследовании приливов стало примерно вдвое меньше.</li><li><b>Настроение.</b> Улучшается, даже когда сила и вес ещё не изменились.</li><li><b>Кости.</b> Нагрузка — главный сигнал кости оставаться крепкой; лучше всего работают силовые вместе с небольшими прыжками.</li><li><b>Мышцы и силы.</b> После 40 мышца хуже отвечает на нагрузку — поэтому её нужно больше, а не меньше.</li><li><b>Обмен.</b> Мышца — главный «потребитель» сахара; силовые снижают и фоновое воспаление, даже без потери веса.</li><li><b>Мозг.</b> Движение улучшает внимание и ясность.</li></ul><h3 class=\"art-h\">Как делать</h3><ul class=\"art-ul\"><li><b>Две тренировки по 30–40 минут в разные дни.</b></li><li><b>Основа — приседания, тяги и жимы.</b> Например: приседания со стулом, тяга резиновой ленты к поясу, отжимания от стены или стола, подъём на ступеньку, жим гантелей вверх.</li><li><b>Без боли.</b> Нагрузка должна быть ощутимой, но не болезненной.</li><li><b>Постепенно прибавлять.</b> Когда становится легко — чуть больше веса или повторений.</li></ul><p class=\"art-p\">С тренером результат и безопасность выше. В VIA-L есть «Тренировка дня» с голосом — можно начать с неё.</p><h3 class=\"art-h\">Кому осторожнее</h3><ul class=\"art-ul\"><li><b>Высокое давление:</b> не задерживайте дыхание на усилии — выдыхайте, когда поднимаете вес. После упражнений на полу вставайте не резко.</li><li><b>Препараты от диабета:</b> при новой нагрузке сахар может снижаться сильнее обычного. Держите под рукой быстрый перекус, а при слабости или дрожи остановитесь.</li><li><b>Боль в суставе или спине:</b> если упражнение отдаётся болью, замените его более лёгким или уменьшите вес.</li></ul><p class=\"art-p\">Если вы не уверены, подходит ли вам нагрузка, — обсудите с врачом.</p><h3 class=\"art-h\">Что может мешать</h3><ul class=\"art-ul\"><li>«Нет времени». Две тренировки по 30 минут — это час в неделю.</li><li>«Я никогда этого не делала». Начните с собственного веса и стула. Важна регулярность, а не рекорды.</li></ul><h3 class=\"art-h\">Чего ждать</h3><p class=\"art-p\">Настроение и самочувствие часто меняются раньше, чем сила и фигура. Отмечайте тренировки, приливы и настроение в VIA-L — через несколько недель будет видно, что меняется у вас.</p><h3 class=\"art-h\">Кому этот шаг помогает</h3><p class=\"art-p\">Почти всем: при приливах, усталости, перепадах настроения, растущей талии, ломоте в суставах и слабости в мышцах.</p><!--EV--><p class=\"art-p art-note\"><i>Это общие сведения, а не назначение.</i></p>","codes":["P-F1","P-F12","P-F7","P-F8"]},"protein":{"t":"Белок в каждый приём пищи: почему после 40 его нужно больше","min":"3 минуты чтения","h":"<p class=\"art-p\">Утром — кофе с печеньем, днём — что-то на бегу, вечером — полноценный ужин. Так едят очень многие. И именно белка в этой схеме почти нет до самого вечера. После 40 это заметно сказывается и на силах, и на мышцах, и на тяге к сладкому.</p><h3 class=\"art-h\">Почему это работает</h3><p class=\"art-p\"><b>Мышца стала «требовательнее».</b> После 40 она хуже отвечает на белок, поэтому, чтобы её сохранить, белка нужно больше, чем раньше, — и равномерно в течение дня, а не всё за ужином.</p><p class=\"art-p\"><b>Белок даёт сытость и ровный сахар.</b> Белковый приём пищи насыщает надолго и сглаживает скачки сахара — меньше провалов и меньше тяги к сладкому.</p><p class=\"art-p\"><b>Белковый завтрак выравнивает день.</b> Пропущенный или «пустой» завтрак держит гормоны стресса высокими, и днём наступает провал. Лучше позавтракать в течение часа-двух после подъёма.</p><h3 class=\"art-h\">Как делать</h3><ul class=\"art-ul\"><li><b>В каждом приёме пищи — источник белка.</b> Ориентир — 30–40 г белка за приём.</li><li><b>Начать с завтрака:</b> там белка обычно меньше всего.</li><li><b>За день</b> — минимум 1–1,2 г белка на килограмм веса, а при силовых тренировках больше.</li></ul><p class=\"art-p\">Как выглядят 30–40 г белка на практике — примерно:</p><ul class=\"art-ul\"><li>завтрак: омлет из 2–3 яиц с творогом или греческий йогурт с орехами;</li><li>обед: порция рыбы, курицы или мяса размером с ладонь;</li><li>ужин: чечевица или фасоль с тофу, сыр, морепродукты.</li></ul><p class=\"art-p\">Белковый порошок — удобная подстраховка, если едой не получается добрать.</p><h3 class=\"art-h\">Кому осторожнее</h3><ul class=\"art-ul\"><li><b>При болезни почек</b> количество белка обязательно согласуйте с врачом.</li><li><b>Если были трудности с едой</b> — расстройство пищевого поведения сейчас или в прошлом, — правила про еду лучше обсуждать со специалистом, а не вводить самой.</li></ul><h3 class=\"art-h\">Что может мешать</h3><ul class=\"art-ul\"><li>«Утром не лезет». Начните с малого: йогурт, яйцо, стакан кефира.</li><li>«Нет времени готовить». Варёные яйца, творог, консервированная рыба, готовая чечевица — без готовки.</li></ul><h3 class=\"art-h\">Чего ждать</h3><p class=\"art-p\">Смотрите, как меняются сытость и тяга к сладкому между приёмами пищи. Отмечайте силы и самочувствие в VIA-L.</p><h3 class=\"art-h\">Кому этот шаг помогает</h3><p class=\"art-p\">Тем, у кого усталость, растущая талия, слабость в мышцах и ломота в суставах. Хорошо работает в паре с силовыми тренировками.</p><!--EV--><p class=\"art-p art-note\"><i>Это общие сведения, а не назначение.</i></p>","codes":["P-F12","P-F7","P-F4"]},"cool":{"t":"Прохладная спальня: простой способ спать лучше при приливах","min":"3 минуты чтения","h":"<p class=\"art-p\">Ночью бросает в жар, вы сбрасываете одеяло, потом мёрзнете, потом снова жарко — и так до утра. Если это знакомо, прохладная спальня — один из самых простых шагов, который можно сделать уже сегодня.</p><h3 class=\"art-h\">Почему это работает</h3><p class=\"art-p\">В переходе сужается «зона теплового комфорта»: телу хватает совсем небольшого тепла, чтобы запустить прилив. А большинство ночных приливов совпадает с пробуждением. Прохладная спальня держит тело дальше от этой границы.</p><p class=\"art-p\">Честно: охлаждение не возвращает зону комфорта и не «отменяет» приливы. Но оно заметно уменьшает ночные пробуждения и дискомфорт — и добавляет глубокого сна.</p><h3 class=\"art-h\">Как делать</h3><ul class=\"art-ul\"><li><b>Температура в спальне — около 16–19 °C.</b> Проветрить перед сном, убавить отопление.</li><li><b>Темнота.</b> Плотные шторы или маска для сна.</li><li><b>Дышащие ткани.</b> Постельное бельё и одежда для сна — из хлопка, льна или других дышащих тканей.</li><li><b>Слои вместо одного тёплого одеяла.</b> Лёгкое одеяло плюс плед — чтобы ночью легко снять лишнее, не просыпаясь полностью.</li><li><b>Охлаждающие наматрасник или подушка</b> — если приливы сильные.</li><li><b>Вода у кровати</b> и запасная футболка — на случай ночной потливости.</li></ul><h3 class=\"art-h\">Что может мешать</h3><ul class=\"art-ul\"><li>Партнёр мёрзнет. Помогают раздельные одеяла: у каждого своё.</li><li>Жаркое лето. Вентилятор, проветривание ночью, прохладный душ перед сном.</li><li>Привычка к тёплой пижаме. Замените на лёгкую, а тёплые носки оставьте — если мёрзнут ноги.</li></ul><h3 class=\"art-h\">Чего ждать</h3><p class=\"art-p\">Смотрите прежде всего на то, сколько раз за ночь вы просыпаетесь. Отмечайте сон и приливы в VIA-L, чтобы сравнить неделю до и неделю после.</p><h3 class=\"art-h\">Если не помогает</h3><p class=\"art-p\">Если ночь всё равно рвут сильные приливы — это повод к врачу. Лечение самих приливов улучшает и сон. Подробнее — в статье «Приливы: почему они бывают и что на самом деле помогает».</p><h3 class=\"art-h\">Кому этот шаг помогает</h3><p class=\"art-p\">Тем, у кого ночные приливы, ночная потливость и пробуждения среди ночи.</p><!--EV--><p class=\"art-p art-note\"><i>Это общие сведения, а не назначение.</i></p>","codes":["P-F17","P-F1"]},"walk":{"t":"Ходьба после еды: 10 минут, которые меняют весь день","min":"3 минуты чтения","h":"<p class=\"art-p\">После обеда клонит в сон, через пару часов тянет на сладкое, к вечеру нет сил. Это часто не «характер», а качели сахара после еды. И одно из самых простых средств против них — короткая прогулка сразу после еды.</p><h3 class=\"art-h\">Почему это работает</h3><p class=\"art-p\">После еды сахар в крови поднимается. Когда мышцы двигаются, они забирают сахар — это отдельный путь его усвоения, в дополнение к обычному. Пик получается ниже, а значит, меньше и последующий провал: меньше сонливости и тяги к сладкому.</p><p class=\"art-p\">Ходьба особенно хорошо работает вместе с другим шагом — «Овощи и белок раньше углеводов»: эффекты складываются.</p><h3 class=\"art-h\">Как делать</h3><ul class=\"art-ul\"><li><b>10–15 минут ходьбы после основных приёмов пищи.</b> Лучше — сразу после еды, а не через час.</li><li><b>Темп — обычный,</b> можно разговаривать. Это не тренировка, а движение.</li><li><b>Если выйти нельзя</b> — ходить по дому, по лестнице, убирать, мыть посуду стоя.</li></ul><h3 class=\"art-h\">Кому осторожнее</h3><ul class=\"art-ul\"><li><b>Препараты от диабета:</b> при новой нагрузке сахар может снижаться сильнее обычного. Держите под рукой быстрый перекус, а при слабости или дрожи остановитесь.</li><li><b>Травма, болезнь, температура</b> — сначала поправиться; шаг подождёт.</li></ul><h3 class=\"art-h\">Что может мешать</h3><ul class=\"art-ul\"><li>Работа за столом. Короткая прогулка после обеда, звонок на ходу, лестница вместо лифта.</li><li>Погода. Ходьба по дому или в торговом центре тоже считается.</li><li>Вечер. Даже 10 минут после ужина — лучше, чем диван сразу.</li></ul><h3 class=\"art-h\">Чего ждать</h3><p class=\"art-p\">Смотрите на послеобеденную сонливость и тягу к сладкому. Отмечайте силы и самочувствие в VIA-L.</p><h3 class=\"art-h\">Кому этот шаг помогает</h3><p class=\"art-p\">Тем, у кого провалы сил после еды, тяга к сладкому и растущая талия.</p><!--EV--><p class=\"art-p art-note\"><i>Это общие сведения, а не назначение.</i></p>","codes":["P-F7","P-F1"]},"breath":{"t":"Медленное дыхание: спокойствие за пять минут","min":"3 минуты чтения","h":"<p class=\"art-p\">Тревога накатывает без причины, раздражение вспыхивает из-за мелочи, вечером мысли не дают уснуть. Медленное дыхание — один из самых простых способов успокоить нервную систему. Оно работает без усилия воли и без особых условий.</p><h3 class=\"art-h\">Почему это работает</h3><p class=\"art-p\">Медленный вдох и особенно длинный выдох напрямую переключают нервную систему из режима «тревога» в режим «покой». Это рефлекс — не нужно себя уговаривать. По силе действия на тревогу медленное дыхание и медитация в исследованиях сопоставимы с лекарством.</p><h3 class=\"art-h\">Чего дыхание не делает</h3><p class=\"art-p\">Честно: сами приливы медленное дыхание не уменьшает — в исследованиях оно не лучше пустышки. Йога и медитация тоже. Против приливов сильнее работают силовые тренировки, прохладная спальня, а без лекарств — когнитивно-поведенческая терапия и клинический гипноз. Подробнее — в статье «Приливы: почему они бывают и что на самом деле помогает».</p><p class=\"art-p\">Дыхание — для спокойствия, тревоги и раздражения. Ради этого его и стоит делать.</p><h3 class=\"art-h\">Как делать</h3><ul class=\"art-ul\"><li><b>Вдох носом на четыре счёта, медленный выдох на шесть.</b> Получается около шести вдохов в минуту.</li><li><b>5–10 минут в день.</b> Даже пять минут дают эффект.</li><li><b>Удобнее вечером</b> — помогает перейти ко сну. Но можно и днём, в любую паузу: перед встречей, в машине до выхода, после работы.</li><li><b>Когда накрывает тревога</b> — сразу перейти на медленные длинные выдохи.</li></ul><p class=\"art-p\">Плечи расслаблены, дышит живот. Если кружится голова — дышите неглубоко и чуть быстрее.</p><h3 class=\"art-h\">Кому осторожнее</h3><p class=\"art-p\"><b>При астме</b> дышите спокойно, без задержек и напряжения. Если начинается приступ, остановитесь и используйте ваши обычные средства.</p><h3 class=\"art-h\">Что может мешать</h3><ul class=\"art-ul\"><li>«Мысли уплывают». Это часть тренировки: заметили — вернулись к счёту.</li><li>«Забываю». Привяжите дыхание к тому, что и так бывает каждый день: чистка зубов вечером, свет выключен.</li><li>«Только дыханием сон не наладить». Верно: для сна сильнее якорь подъёма и правило «кровать только для сна». Дыхание — дополнение к ним.</li></ul><h3 class=\"art-h\">Чего ждать</h3><p class=\"art-p\">Смотрите, как часто накрывают тревога и раздражение и как вы засыпаете. Если у вас кольцо или часы, можно сравнить вариабельность пульса в вечера с дыханием и без. Отмечайте самочувствие в VIA-L.</p><h3 class=\"art-h\">Если не помогает</h3><p class=\"art-p\">Если тревога или подавленность держатся больше двух недель и мешают жить — это повод к врачу. Подробнее — в статье «Перепады настроения, тревога и раздражительность».</p><!--EV--><p class=\"art-p art-note\"><i>Это общие сведения, а не назначение.</i></p>","codes":["P-F4","P-F9","P-F1"]},"bed":{"t":"Кровать только для сна: как вернуть телу привычку засыпать","min":"3 минуты чтения","h":"<p class=\"art-p\">Ложитесь уставшей — и сон пропадает. Лежите час, листаете телефон, считаете, сколько осталось до будильника. Чем дольше так продолжается, тем прочнее мозг связывает кровать не со сном, а с бодрствованием и тревогой. Этот шаг возвращает правильную связь.</p><h3 class=\"art-h\">Почему это работает</h3><p class=\"art-p\">Это основа поведенческого подхода ко сну — по исследованиям он сильнее и снотворных, и простого списка правил «гигиены сна». Смысл простой: кровать снова должна означать сон. Когда вы в ней только спите, мозг заново учится засыпать, едва голова касается подушки.</p><h3 class=\"art-h\">Как делать</h3><ul class=\"art-ul\"><li><b>Не лежать без сна.</b> Если не спится дольше 15–20 минут — встать, перейти в другое место с тусклым светом, заняться спокойным делом. Вернуться, когда начнёт клонить в сон.</li><li><b>В постели не работать и не листать телефон.</b> Телефон — на зарядку подальше от кровати.</li><li><b>Не смотреть на часы ночью.</b> Подсчёт оставшихся часов только добавляет тревоги.</li><li><b>Ложиться, когда клонит в сон, а вставать в одно время.</b> Рано лечь «на всякий случай» часто значит дольше лежать без сна.</li><li><b>Без экранов за 30–60 минут до сна.</b></li></ul><h3 class=\"art-h\">Кому осторожнее</h3><p class=\"art-p\"><b>Если принимаете препараты от давления или вам больше 70:</b> ночью вставайте не резко — сначала посидите минуту на краю кровати. Свет в коридоре — приглушённый, но достаточный, чтобы не споткнуться.</p><p class=\"art-p\">Если днём сонливость мешает водить машину — не садитесь за руль уставшей.</p><h3 class=\"art-h\">Что может мешать</h3><ul class=\"art-ul\"><li>«Телефон — мой будильник». Обычный будильник или телефон так, чтобы до него надо было встать.</li><li>«Вставать ночью тяжело». В первые дни может быть непривычно. Главное — не лежать часами без сна.</li><li>«В квартире некуда уйти». Кресло в той же комнате с тусклой лампой тоже подойдёт.</li></ul><h3 class=\"art-h\">Чего ждать</h3><p class=\"art-p\">Смотрите, сколько времени вы лежите без сна и сколько раз просыпаетесь. Отмечайте сон в VIA-L, чтобы видеть разницу по неделям.</p><h3 class=\"art-h\">Когда к врачу</h3><p class=\"art-p\">Если плохой сон держится больше трёх месяцев, несмотря на эти шаги, если есть храп с паузами, неосвежающий сон или засыпание днём — стоит показаться врачу или сомнологу. Подробнее — в статье «Почему после 40 портится сон».</p><!--EV--><p class=\"art-p art-note\"><i>Это общие сведения, а не назначение.</i></p>","codes":["P-F17","P-F3","P-F4"]},"order":{"t":"Овощи и белок раньше углеводов: тот же обед, но мягче для сахара","min":"3 минуты чтения","h":"<p class=\"art-p\">Этот шаг не про то, чтобы есть меньше или отказываться от любимого. Он про порядок: что съесть первым. Простая перестановка на тарелке заметно меняет то, как тело справляется с едой.</p><h3 class=\"art-h\">Почему это работает</h3><p class=\"art-p\">Если начать еду с овощей и белка, а хлеб, крупу, картофель или макароны съесть после, скачок сахара после еды получается мягче — примерно на треть. Меньше скачок — меньше и последующий провал: меньше сонливости после обеда и тяги к сладкому.</p><p class=\"art-p\">В переходе тело хуже отвечает на сахар, поэтому такие простые приёмы особенно полезны. А вместе с ходьбой после еды эффекты складываются.</p><h3 class=\"art-h\">Как делать</h3><ul class=\"art-ul\"><li><b>Сначала овощи</b> — салат, тушёные или свежие овощи.</li><li><b>Потом белок</b> — мясо, рыба, яйца, тофу, бобовые.</li><li><b>Углеводы — в конце:</b> гарнир, хлеб.</li></ul><p class=\"art-p\">Всё на одной тарелке, просто в таком порядке. Есть меньше при этом не нужно.</p><h3 class=\"art-h\">Кому осторожнее</h3><ul class=\"art-ul\"><li><b>Если были трудности с едой</b> — расстройство пищевого поведения сейчас или в прошлом, — правила про еду лучше обсуждать со специалистом, а не вводить самой.</li><li><b>Если принимаете варфарин:</b> количество зелёных овощей не меняйте резко — от этого зависит действие препарата. Перемены в питании обсудите с врачом.</li></ul><h3 class=\"art-h\">Что может мешать</h3><ul class=\"art-ul\"><li>«Нет овощей». Подойдут замороженные или простая нарезка — огурец, помидор, перец.</li><li>«В гостях и в кафе». Начните с салата или овощной закуски, хлеб — потом.</li><li>«Завтрак — каша или бутерброд». Добавьте к нему сначала яйцо, творог или овощи.</li></ul><h3 class=\"art-h\">Чего ждать</h3><p class=\"art-p\">Смотрите на сытость после еды, сонливость после обеда и тягу к сладкому. Вес меняется медленнее, поэтому ориентируйтесь на самочувствие. Отмечайте его в VIA-L.</p><h3 class=\"art-h\">Кому этот шаг помогает</h3><p class=\"art-p\">Тем, у кого растущая талия, провалы сил после еды и тяга к сладкому. Хорошо работает вместе с ходьбой после еды и белком в каждый приём.</p><!--EV--><p class=\"art-p art-note\"><i>Это общие сведения, а не назначение.</i></p>","codes":["P-F7","P-F1"]}}}};
